        public class QueueZone
        {
            public string Name { get; set; }
            public Vector3 MinBounds { get; set; }
            public Vector3 MaxBounds { get; set; }
            public List<ulong> QueuedPlayers { get; set; } = new List<ulong>();
            public int TeamSize { get; set; } = 5;
            public bool IsActive { get; set; } = true;
            public string SelectedMap { get; set; } = "dust2";
            
            // Bug Fix: Add validation
            public float CreatedTime { get; set; } = 0f;
            public bool IsValid()
            {
                return !string.IsNullOrEmpty(Name) && TeamSize > 0 && TeamSize <= 10;
            }
            
            public Vector3 GetCenter()
            {
                return (MinBounds + MaxBounds) / 2f;
            }
        }
        
        public class BombSite
        {
            public string Name { get; set; }
            public Vector3 MinBounds { get; set; }
            public Vector3 MaxBounds { get; set; }
            public string MapName { get; set; }
            public bool IsActive { get; set; } = true;
            
            // Bug Fix: Add validation
            public bool IsValid()
            {
                return !string.IsNullOrEmpty(Name) && !string.IsNullOrEmpty(MapName);
            }
            
            public bool ContainsPosition(Vector3 position)
            {
                return position.x >= MinBounds.x && position.x <= MaxBounds.x &&
                       position.y >= MinBounds.y && position.y <= MaxBounds.y &&
                       position.z >= MinBounds.z && position.z <= MaxBounds.z;
            }
        }
        
        public class MapConfiguration
        {
            public string MapName { get; set; }
            public List<Vector3> TerroristSpawns { get; set; } = new List<Vector3>();
            public List<Vector3> CounterTerroristSpawns { get; set; } = new List<Vector3>();
            public List<string> BombSiteNames { get; set; } = new List<string>();
            public Vector3 SpectatorArea { get; set; }
            
            // Bug Fix: Add validation
            public bool IsValid()
            {
                return !string.IsNullOrEmpty(MapName) && 
                       TerroristSpawns.Count >= 5 && 
                       CounterTerroristSpawns.Count >= 5 &&
                       BombSiteNames.Count >= 2;
            }
        }
        
        public class Match
        {
            public ulong MatchId { get; set; }
            public List<ulong> TerroristPlayers { get; set; } = new List<ulong>();
            public List<ulong> CounterTerroristPlayers { get; set; } = new List<ulong>();
            public int TerroristScore { get; set; } = 0;
            public int CounterTerroristScore { get; set; } = 0;
            public int CurrentRound { get; set; } = 0; // Bug Fix: Start at 0, increment to 1
            public MatchState State { get; set; } = MatchState.WaitingForPlayers;
            public string MapName { get; set; } = "dust2";
            public float RoundStartTime { get; set; }
            public bool IsBuyPhase { get; set; } = false;
            public PlantedBomb PlantedBomb { get; set; }
            public bool HasSwappedSides { get; set; } = false;
            public Timer RoundTimer { get; set; }
            public Timer BuyPhaseTimer { get; set; }
            public string QueueZoneName { get; set; }
            
            // Bug Fix: Add safety and validation
            public float MatchStartTime { get; set; } = 0f;
            public List<Timer> ActiveTimers { get; set; } = new List<Timer>();
            public bool IsValid()
            {
                return MatchId != 0 && 
                       TerroristPlayers.Count > 0 && 
                       CounterTerroristPlayers.Count > 0 &&
                       !string.IsNullOrEmpty(MapName);
            }
            
            public void CleanupTimers()
            {
                try
                {
                    RoundTimer?.Destroy();
                    RoundTimer = null;
                    BuyPhaseTimer?.Destroy();
                    BuyPhaseTimer = null;
                    PlantedBomb?.ExplosionTimer?.Destroy();
                    if (PlantedBomb != null) PlantedBomb.ExplosionTimer = null;
                    
                    foreach (var timer in ActiveTimers.ToList())
                    {
                        timer?.Destroy();
                    }
                    ActiveTimers.Clear();
                }
                catch (Exception ex)
                {
                    // Handle cleanup errors gracefully
                }
            }
        }
        
        public class PlantedBomb
        {
            public Vector3 Position { get; set; }
            public float PlantTime { get; set; }
            public ulong PlanterId { get; set; }
            public string BombSiteName { get; set; }
            public Timer ExplosionTimer { get; set; }
            public bool IsBeingDefused { get; set; } = false;
            public ulong DefuserId { get; set; } = 0;
            
            // Bug Fix: Add validation
            public bool IsValid()
            {
                return PlanterId != 0 && !string.IsNullOrEmpty(BombSiteName) && PlantTime > 0;
            }
            
            public float GetTimeLeft(float bombTimer)
            {
                return bombTimer - (Time.time - PlantTime);
            }
        }
        
