        private void InitializeTimers()
        {
            uiUpdateTimer = timer.Every(2f, UpdateAllUI); // Bug Fix: Reduced frequency
            matchUpdateTimer = timer.Every(0.5f, UpdateMatches); // Bug Fix: Reduced frequency
            cleanupTimer = timer.Every(config.AutoCleanupInterval, PerformCleanup);
        }
        
        void OnServerInitialized()
        {
            try
            {
                LoadData();
                InitializeDefaultMaps();
                InitializeWeaponSkins();
                
                if (config.GenerateMapOnStart)
                {
                    timer.Once(10f, () => SafeAutoGenerateServerMaps());
                }
                
                if (config.AutoDetectMapCenter)
                {
                    DetectMapCenter();
                }
                
                if (config.EnableMapValidation)
                {
                    ValidateAllMaps();
                }
                
                PrintWarning("CS2 Style Plugin loaded successfully!");
                PrintWarning($"Map generation center: {config.MapGenerationCenter}");
                PrintWarning($"Available maps: {mapConfigurations.Count}");
                PrintWarning($"Available skins: {availableSkins.Count}");
                PrintWarning($"Large map mode: {config.LargeMapMode}");
            }
            catch (Exception ex)
            {
                PrintError($"Error during server initialization: {ex.Message}");
            }
        }
        
        void Unload()
        {
            try
            {
                SaveData();
                
                // Bug Fix: Proper cleanup of all resources
                CleanupAllResources();
                
                PrintWarning("CS2 Style Plugin unloaded successfully!");
            }
            catch (Exception ex)
            {
                PrintError($"Error during plugin unload: {ex.Message}");
            }
        }
        
        private void CleanupAllResources()
        {
            // Clean up timers safely
            DestroyTimer(ref uiUpdateTimer);
            DestroyTimer(ref matchUpdateTimer);
            DestroyTimer(ref cleanupTimer);
            
            // Clean up all active matches
            SafeModifyCollection(() =>
            {
                foreach (var match in activeMatches.Values.ToList())
                {
                    try
                    {
                        EndMatch(match, "Plugin unloaded");
                    }
                    catch (Exception ex)
                    {
                        PrintError($"Error ending match {match.MatchId}: {ex.Message}");
                    }
                }
            });
            
            // Clean up player data timers
            foreach (var data in playerData.Values.ToList())
            {
                try
                {
                    data.DefuseTimer?.Destroy();
                    data.DefuseTimer = null;
                }
                catch (Exception ex)
                {
                    PrintError($"Error cleaning up player {data.PlayerId}: {ex.Message}");
                }
            }
            
            // Destroy all UI elements safely
            foreach (var player in BasePlayer.activePlayerList.ToList())
            {
                if (IsValidPlayer(player))
                {
                    SafeDestroyUI(player, "LobbyUI");
                    SafeDestroyUI(player, "MatchUI");
                    SafeDestroyUI(player, "BuyMenu");
                    SafeDestroyUI(player, "SpectatorUI");
                    SafeDestroyUI(player, "FreeCamUI");
                    SafeDestroyUI(player, "VoiceChatUI");
                    SafeDestroyUI(player, "VoteUI");
                }
            }
            
            // Clear collections
            processingPlayers.Clear();
            lastActionTime.Clear();
        }
        
