        #region Safety and Validation (Bug Fixes)
        
        // Thread-safe collection modification
        private void SafeModifyCollection(Action action)
        {
            lock (_lockObject)
            {
                try
                {
                    action();
                }
                catch (Exception ex)
                {
                    PrintError($"Error in SafeModifyCollection: {ex.Message}");
                }
            }
        }
        
        // Enhanced timer management
        private void DestroyTimer(ref Timer timer)
        {
            try
            {
                timer?.Destroy();
                timer = null;
            }
            catch (Exception ex)
            {
                PrintError($"Error destroying timer: {ex.Message}");
            }
        }
        
        // Enhanced player validation
        private bool IsValidPlayer(BasePlayer player)
        {
            return player != null && 
                   player.IsConnected && 
                   !player.IsDestroyed && 
                   player.net?.connection != null;
        }
        
        // Safe player data access
        private PlayerData GetSafePlayerData(ulong playerId)
        {
            if (playerId == 0) return null;
            
            lock (_lockObject)
            {
                if (!playerData.ContainsKey(playerId))
                {
                    var player = BasePlayer.FindByID(playerId);
                    if (!IsValidPlayer(player)) return null;
                    
                    playerData[playerId] = new PlayerData
                    {
                        PlayerId = playerId,
                        PlayerName = player.displayName,
                        JoinTime = DateTime.Now,
                        IsProcessing = false
                    };
                }
                
                return playerData[playerId];
            }
        }
        
        // Safe match access
        private Match GetSafeMatch(ulong matchId)
        {
            lock (_lockObject)
            {
                return activeMatches.ContainsKey(matchId) ? activeMatches[matchId] : null;
            }
        }
        
        // Safe collection iteration with modification
        private void SafeIterateAndModify<T>(ICollection<T> collection, Func<T, bool> shouldRemove, Action<T> onRemove = null)
        {
            lock (_lockObject)
            {
                var itemsToRemove = collection.Where(shouldRemove).ToList();
                foreach (var item in itemsToRemove)
                {
                    collection.Remove(item);
                    onRemove?.Invoke(item);
                }
            }
        }
        
        // Enhanced UI cleanup
        private void SafeDestroyUI(BasePlayer player, string uiName)
        {
            if (!IsValidPlayer(player)) return;
            
            try
            {
                CuiHelper.DestroyUi(player, uiName);
            }
            catch (Exception ex)
            {
                PrintError($"Error destroying UI '{uiName}' for {player.displayName}: {ex.Message}");
            }
        }
        
        // Resource cleanup helper
        private void CleanupPlayerResources(ulong playerId)
        {
            SafeModifyCollection(() =>
            {
                // Clean up player data
                if (playerData.ContainsKey(playerId))
                {
                    var data = playerData[playerId];
                    data.CleanupTimers();
                    playerData.Remove(playerId);
                }
                
                // Clean up from queues
                foreach (var zone in queueZones.Values.ToList())
                {
                    zone.QueuedPlayers.Remove(playerId);
                }
                
                // Clean up from matches
                foreach (var match in activeMatches.Values.ToList())
                {
                    match.TerroristPlayers.Remove(playerId);
                    match.CounterTerroristPlayers.Remove(playerId);
                }
                
                // Clean up processing states
                processingPlayers.Remove(playerId);
                lastActionTime.Remove(playerId);
            });
        }
        
        private bool CanPlayerPerformAction(BasePlayer player)
        {
            if (player == null || !player.IsConnected) return false;
            
            ulong playerId = player.userID;
            
            // Bug Fix: Prevent spam actions
            if (lastActionTime.ContainsKey(playerId))
            {
                if (Time.time - lastActionTime[playerId] < ACTION_COOLDOWN)
                {
                    return false;
                }
            }
            
            // Bug Fix: Prevent concurrent processing
            if (processingPlayers.Contains(playerId))
            {
                return false;
            }
            
            return true;
        }
        
        private void StartPlayerAction(BasePlayer player)
        {
            if (player == null) return;
            
            ulong playerId = player.userID;
            lastActionTime[playerId] = Time.time;
            processingPlayers.Add(playerId);
            
            var data = GetPlayerData(playerId);
            if (data != null)
            {
                data.IsProcessing = true;
                data.LastActionTime = Time.time;
            }
        }
        
        private void EndPlayerAction(BasePlayer player)
        {
            if (player == null) return;
            
            ulong playerId = player.userID;
            processingPlayers.Remove(playerId);
            
            var data = GetPlayerData(playerId);
            if (data != null)
            {
                data.IsProcessing = false;
            }
        }
        
        private bool IsValidPosition(Vector3 position)
        {
            // Bug Fix: Validate position is not NaN or infinity
            if (float.IsNaN(position.x) || float.IsNaN(position.y) || float.IsNaN(position.z))
                return false;
            
            if (float.IsInfinity(position.x) || float.IsInfinity(position.y) || float.IsInfinity(position.z))
                return false;
            
            // Bug Fix: Check if position is within reasonable bounds
            if (Mathf.Abs(position.x) > 10000f || Mathf.Abs(position.z) > 10000f)
                return false;
            
            if (position.y < -1000f || position.y > 1000f)
                return false;
            
            return true;
        }
        
        private Vector3 GetSafePosition(Vector3 position)
        {
            if (IsValidPosition(position))
                return position;
            
            // Bug Fix: Return a safe fallback position
            return config.LobbySpawnPoint != Vector3.zero ? config.LobbySpawnPoint : Vector3.zero;
        }
        
        private void PerformCleanup()
        {
            try
            {
                CleanupExpiredQueues();
                CleanupInactiveMatches();
                CleanupDisconnectedPlayers();
                CleanupOrphanedTimers();
            }
            catch (Exception ex)
            {
                PrintError($"Error during cleanup: {ex.Message}");
            }
        }
        
        private void CleanupExpiredQueues()
        {
            SafeModifyCollection(() =>
            {
                foreach (var zone in queueZones.Values.ToList())
                {
                    SafeIterateAndModify(zone.QueuedPlayers, playerId =>
                    {
                        var data = GetPlayerData(playerId);
                        return data == null || !data.IsInQueue || 
                               (data.QueueJoinTime > 0 && Time.time - data.QueueJoinTime > config.MaxQueueTime);
                    }, playerId =>
                    {
                        var data = GetPlayerData(playerId);
                        if (data != null)
                        {
                            data.IsInQueue = false;
                            data.QueueZoneName = "";
                        }
                    });
                }
            });
        }
        
        private void CleanupInactiveMatches()
        {
            SafeModifyCollection(() =>
            {
                var inactiveMatches = activeMatches.Where(kvp =>
                {
                    var match = kvp.Value;
                    
                    // Check if match has been running too long without activity
                    if (Time.time - match.MatchStartTime > 3600f) return true; // 1 hour
                    
                    // Check if all players have disconnected
                    var connectedPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers)
                        .Count(id => IsValidPlayer(BasePlayer.FindByID(id)));
                    
                    return connectedPlayers == 0;
                }).Select(kvp => kvp.Key).ToList();
                
                foreach (var matchId in inactiveMatches)
                {
                    if (activeMatches.ContainsKey(matchId))
                    {
                        EndMatch(activeMatches[matchId], "Match cleanup - inactive");
                    }
                }
            });
        }
        
        private void CleanupDisconnectedPlayers()
        {
            SafeModifyCollection(() =>
            {
                var disconnectedPlayers = playerData.Where(kvp =>
                {
                    var playerId = kvp.Key;
                    var player = BasePlayer.FindByID(playerId);
                    return !IsValidPlayer(player);
                }).Select(kvp => kvp.Key).ToList();
                
                foreach (var playerId in disconnectedPlayers)
                {
                    CleanupPlayerResources(playerId);
                }
            });
        }
                    if (data.CurrentMatchId != 0)
                    {
                        if (activeMatches.ContainsKey(data.CurrentMatchId))
                        {
                            var match = activeMatches[data.CurrentMatchId];
                            match.TerroristPlayers.Remove(playerId);
                            match.CounterTerroristPlayers.Remove(playerId);
                        }
                    }
                    
                    // Clean up queue involvement
                    if (data.IsInQueue && !string.IsNullOrEmpty(data.QueueZoneName))
                    {
                        if (queueZones.ContainsKey(data.QueueZoneName))
                        {
                            queueZones[data.QueueZoneName].QueuedPlayers.Remove(playerId);
                        }
                    }
                    
                    // Clean up timers
                    data.DefuseTimer?.Destroy();
                    
                    disconnectedPlayers.Add(playerId);
                }
            }
            
            foreach (var playerId in disconnectedPlayers)
            {
                playerData.Remove(playerId);
            }
        }
        
