        private void DetectMapCenter()
        {
            try
            {
                if (TerrainMeta.Size != null)
                {
                    float mapSize = TerrainMeta.Size.x;
                    config.MapGenerationCenter = new Vector3(mapSize / 2f, 0, mapSize / 2f);
                    config.MapSearchRadius = mapSize / 2f * 0.8f; // 80% of map radius
                    
                    PrintWarning($"Auto-detected map center: {config.MapGenerationCenter}");
                    PrintWarning($"Map search radius: {config.MapSearchRadius}");
                }
                else
                {
                    PrintWarning("Could not auto-detect map center, using default");
                }
            }
            catch (Exception ex)
            {
                PrintError($"Error detecting map center: {ex.Message}");
            }
        }
        
        private void SafeAutoGenerateServerMaps()
        {
            try
            {
                if (config.LargeMapMode && config.MultipleMapZones)
                {
                    GenerateMultipleCompetitiveZones();
                }
                else
                {
                    GenerateDefaultServerMap();
                }
            }
            catch (Exception ex)
            {
                PrintError($"Error during auto map generation: {ex.Message}");
            }
        }
        
        private void GenerateMultipleCompetitiveZones()
        {
            try
            {
                Vector3 center = config.MapGenerationCenter;
                float radius = config.MapSearchRadius;
                
                // Generate 4 competitive zones around the map
                var zones = new[]
                {
                    new { name = "dust2_north", offset = new Vector3(0, 0, radius * 0.6f) },
                    new { name = "dust2_south", offset = new Vector3(0, 0, -radius * 0.6f) },
                    new { name = "dust2_east", offset = new Vector3(radius * 0.6f, 0, 0) },
                    new { name = "dust2_west", offset = new Vector3(-radius * 0.6f, 0, 0) }
                };
                
                foreach (var zone in zones)
                {
                    Vector3 zoneCenter = center + zone.offset;
                    GenerateCompetitiveZone(zone.name, zoneCenter);
                }
                
                PrintWarning($"Generated {zones.Length} competitive zones for large map");
            }
            catch (Exception ex)
            {
                PrintError($"Error generating multiple zones: {ex.Message}");
            }
        }
        
        private void GenerateDefaultServerMap()
        {
            try
            {
                GenerateCompetitiveZone("dust2", config.MapGenerationCenter);
                PrintWarning("Generated default competitive zone");
            }
            catch (Exception ex)
            {
                PrintError($"Error generating default map: {ex.Message}");
            }
        }
        
        private void GenerateCompetitiveZone(string mapName, Vector3 center)
        {
            try
            {
                // Create ultra-detailed map with thousands of elements
                CreateDetailedMapStructure(mapName, center);
                CreateBombSites(mapName, center);
                CreateSpawnPoints(mapName, center);
                CreateQueueZone(mapName, center);
                
                PrintWarning($"Generated competitive zone: {mapName} at {center}");
            }
            catch (Exception ex)
            {
                PrintError($"Error generating zone {mapName}: {ex.Message}");
            }
        }
        
