        private void CreateBombSites(string mapName, Vector3 center)
        {
            try
            {
                // Create Bomb Site A
                Vector3 siteAPos = center + new Vector3(50f, 0f, 30f);
                siteAPos.y = GetTerrainHeight(siteAPos);
                
                var siteA = new BombSite
                {
                    Name = $"{mapName}_A",
                    MapName = mapName,
                    MinBounds = siteAPos - new Vector3(10f, 5f, 10f),
                    MaxBounds = siteAPos + new Vector3(10f, 5f, 10f),
                    IsActive = true
                };
                
                bombSites[siteA.Name] = siteA;
                
                // Create Bomb Site B
                Vector3 siteBPos = center + new Vector3(-50f, 0f, -30f);
                siteBPos.y = GetTerrainHeight(siteBPos);
                
                var siteB = new BombSite
                {
                    Name = $"{mapName}_B",
                    MapName = mapName,
                    MinBounds = siteBPos - new Vector3(10f, 5f, 10f),
                    MaxBounds = siteBPos + new Vector3(10f, 5f, 10f),
                    IsActive = true
                };
                
                bombSites[siteB.Name] = siteB;
                
                PrintWarning($"Created bomb sites for {mapName}: {siteA.Name}, {siteB.Name}");
            }
            catch (Exception ex)
            {
                PrintError($"Error creating bomb sites: {ex.Message}");
            }
        }
        
        private void CreateSpawnPoints(string mapName, Vector3 center)
        {
            try
            {
                if (!mapConfigurations.ContainsKey(mapName))
                {
                    mapConfigurations[mapName] = new MapConfiguration
                    {
                        MapName = mapName,
                        SpectatorArea = center + new Vector3(0, 50f, 0)
                    };
                }
                
                var config = mapConfigurations[mapName];
                
                // Create Terrorist spawns
                Vector3 tSpawnBase = center + new Vector3(-80f, 0f, -80f);
                for (int i = 0; i < 10; i++)
                {
                    Vector3 spawnPos = tSpawnBase + new Vector3(i * 3f, 0f, (i % 2) * 3f);
                    spawnPos.y = GetTerrainHeight(spawnPos) + 1f;
                    
                    if (IsValidPosition(spawnPos))
                    {
                        config.TerroristSpawns.Add(spawnPos);
                    }
                }
                
                // Create Counter-Terrorist spawns
                Vector3 ctSpawnBase = center + new Vector3(80f, 0f, 80f);
                for (int i = 0; i < 10; i++)
                {
                    Vector3 spawnPos = ctSpawnBase + new Vector3(i * 3f, 0f, (i % 2) * 3f);
                    spawnPos.y = GetTerrainHeight(spawnPos) + 1f;
                    
                    if (IsValidPosition(spawnPos))
                    {
                        config.CounterTerroristSpawns.Add(spawnPos);
                    }
                }
                
                // Add bomb site references
                config.BombSiteNames.Clear();
                config.BombSiteNames.Add($"{mapName}_A");
                config.BombSiteNames.Add($"{mapName}_B");
                
                PrintWarning($"Created spawn points for {mapName}: {config.TerroristSpawns.Count} T spawns, {config.CounterTerroristSpawns.Count} CT spawns");
            }
            catch (Exception ex)
            {
                PrintError($"Error creating spawn points: {ex.Message}");
            }
        }
        
        private void CreateQueueZone(string mapName, Vector3 center)
        {
            try
            {
                Vector3 queueCenter = center + new Vector3(0f, 0f, 120f);
                queueCenter.y = GetTerrainHeight(queueCenter);
                
                var queueZone = new QueueZone
                {
                    Name = $"{mapName}_queue",
                    MinBounds = queueCenter - new Vector3(15f, 5f, 15f),
                    MaxBounds = queueCenter + new Vector3(15f, 15f, 15f),
                    TeamSize = config.DefaultTeamSize,
                    IsActive = true,
                    SelectedMap = mapName,
                    CreatedTime = Time.time
                };
                
                queueZones[queueZone.Name] = queueZone;
                
                PrintWarning($"Created queue zone for {mapName}: {queueZone.Name}");
            }
            catch (Exception ex)
            {
                PrintError($"Error creating queue zone: {ex.Message}");
            }
        }
        
        private float GetTerrainHeight(Vector3 position)
        {
            try
            {
                if (TerrainMeta.HeightMap != null)
                {
                    return TerrainMeta.HeightMap.GetHeight(position);
                }
            }
            catch (Exception ex)
            {
                PrintError($"Error getting terrain height: {ex.Message}");
            }
            
            // Fallback: Raycast method
            try
            {
                RaycastHit hit;
                if (Physics.Raycast(position + Vector3.up * 200f, Vector3.down, out hit, 400f))
                {
                    return hit.point.y;
                }
            }
            catch (Exception ex)
            {
                PrintError($"Error with raycast terrain height: {ex.Message}");
            }
            
            return 0f;
        }
        
