        #region Player Events
        
        void OnPlayerConnected(BasePlayer player)
        {
            if (player == null) return;
            
            var data = GetPlayerData(player.userID);
            data.PlayerName = player.displayName;
            
            // If player was in a match, handle reconnection
            if (data.CurrentMatchId != 0 && activeMatches.ContainsKey(data.CurrentMatchId))
            {
                var match = activeMatches[data.CurrentMatchId];
                if (match.State == MatchState.InProgress)
                {
                    // Teleport player back to their spawn or spectator area
                    timer.Once(2f, () => HandlePlayerReconnection(player, match));
                }
            }
            
            timer.Once(1f, () => CreateUI(player));
        }
        
        void OnPlayerDisconnected(BasePlayer player, string reason)
        {
            if (player == null) return;
            
            var data = GetPlayerData(player.userID);
            
            // Remove from queue if in one
            if (data.IsInQueue)
            {
                RemovePlayerFromQueue(player.userID);
            }
            
            // Handle match disconnection
            if (data.CurrentMatchId != 0 && activeMatches.ContainsKey(data.CurrentMatchId))
            {
                var match = activeMatches[data.CurrentMatchId];
                // In a real implementation, you might want to pause the match or handle substitutions
                PrintToChat($"{player.displayName} disconnected from match {match.MatchId}");
            }
            
            DestroyUI(player);
        }
        
        void OnPlayerDeath(BasePlayer victim, HitInfo info)
        {
            if (victim == null) return;
            
            var victimData = GetPlayerData(victim.userID);
            if (victimData.CurrentMatchId == 0) return;
            
            if (!activeMatches.ContainsKey(victimData.CurrentMatchId)) return;
            var match = activeMatches[victimData.CurrentMatchId];
            
            if (match.State != MatchState.InProgress) return;
            
            victimData.Deaths++;
            victimData.RoundDeaths++;
            
            BasePlayer attacker = info?.InitiatorPlayer;
            if (attacker != null && attacker != victim)
            {
                var attackerData = GetPlayerData(attacker.userID);
                
                // Check for team kill
                if (victimData.CurrentTeam == attackerData.CurrentTeam)
                {
                    HandleTeamKill(attacker, victim, info);
                }
                else
                {
                    attackerData.Kills++;
                    attackerData.RoundKills++;
                    PrintToChat($"{attacker.displayName} eliminated {victim.displayName}");
                }
            }
            
            // Move player to spectator area
            timer.Once(2f, () => MoveToSpectatorArea(victim, match));
            
            // Check if round should end
            CheckRoundEnd(match);
        }
        
        void OnPlayerRespawned(BasePlayer player)
        {
            if (player == null) return;
            
            var data = GetPlayerData(player.userID);
            if (data.CurrentMatchId != 0 && activeMatches.ContainsKey(data.CurrentMatchId))
            {
                var match = activeMatches[data.CurrentMatchId];
                if (match.State == MatchState.InProgress && !data.IsSpectating)
                {
                    // Restore player inventory and position
                    timer.Once(0.5f, () => RestorePlayerForMatch(player, match));
                }
            }
        }
        
        #endregion
        
        #region Queue System
        
        void OnPlayerInput(BasePlayer player, InputState input)
        {
            if (player == null || input == null) return;
            
            var data = GetPlayerData(player.userID);
            
            // Check if player is in a queue zone
            CheckPlayerInQueueZone(player);
            
            // Handle spectator controls
            if (data.IsSpectating && !data.IsInFreeCam)
            {
                if (input.WasJustPressed(BUTTON.FIRE_PRIMARY))
                {
                    SpectateNextPlayer(player);
                }
                else if (input.WasJustPressed(BUTTON.FIRE_SECONDARY))
                {
                    SpectatePreviousPlayer(player);
                }
                else if (input.WasJustPressed(BUTTON.USE))
                {
                    ToggleFreeCam(player);
                }
            }
            
            // Handle defuse mechanics
            if (data.CurrentMatchId != 0 && activeMatches.ContainsKey(data.CurrentMatchId))
            {
                var match = activeMatches[data.CurrentMatchId];
                
                if (match.State == MatchState.InProgress && match.PlantedBomb != null)
                {
                    // Check if player is trying to defuse (USE key)
                    if (input.IsDown(BUTTON.USE) && data.CurrentTeam == Team.CounterTerrorist && !data.IsSpectating)
                    {
                        float distance = Vector3.Distance(player.transform.position, match.PlantedBomb.Position);
                        if (distance <= 2f) // Within defuse range
                        {
                            StartDefuse(player, match);
                        }
                    }
                    else if (!input.IsDown(BUTTON.USE) && data.IsDefusing)
                    {
                        StopDefuse(player, match);
                    }
                }
            }
        }
        
        private void CheckPlayerInQueueZone(BasePlayer player)
        {
            var data = GetPlayerData(player.userID);
            var playerPos = player.transform.position;
            
            foreach (var zone in queueZones.Values)
            {
                if (!zone.IsActive) continue;
                
                bool inZone = IsPlayerInZone(playerPos, zone.MinBounds, zone.MaxBounds);
                
                if (inZone && !data.IsInQueue)
                {
                    // Player entered queue zone
                    AddPlayerToQueue(player, zone);
                }
                else if (!inZone && data.IsInQueue && data.QueueZoneName == zone.Name)
                {
                    // Player left queue zone
                    RemovePlayerFromQueue(player.userID);
                }
            }
        }
        
        private bool IsPlayerInZone(Vector3 position, Vector3 minBounds, Vector3 maxBounds)
        {
            return position.x >= minBounds.x && position.x <= maxBounds.x &&
                   position.y >= minBounds.y && position.y <= maxBounds.y &&
                   position.z >= minBounds.z && position.z <= maxBounds.z;
        }
        
        private void AddPlayerToQueue(BasePlayer player, QueueZone zone)
        {
            var data = GetPlayerData(player.userID);
            
            // Check if player is already in a match
            if (data.CurrentMatchId != 0)
            {
                SendReply(player, "You are already in a match!");
                return;
            }
            
            data.IsInQueue = true;
            data.QueueZoneName = zone.Name;
            zone.QueuedPlayers.Add(player.userID);
            
            SendReply(player, $"Added to queue ({zone.QueuedPlayers.Count}/{zone.TeamSize * 2})");
            
            // Check if queue is full
            if (zone.QueuedPlayers.Count >= zone.TeamSize * 2)
            {
                StartMatch(zone);
            }
        }
        
        private void RemovePlayerFromQueue(ulong playerId)
        {
            var data = GetPlayerData(playerId);
            if (!data.IsInQueue) return;
            
            if (queueZones.ContainsKey(data.QueueZoneName))
            {
                var zone = queueZones[data.QueueZoneName];
                zone.QueuedPlayers.Remove(playerId);
            }
            
            data.IsInQueue = false;
            data.QueueZoneName = "";
            
            var player = BasePlayer.FindByID(playerId);
            if (player != null)
            {
                SendReply(player, "Removed from queue");
            }
        }
        
        private void StartMatch(QueueZone zone)
        {
            var queuedPlayers = zone.QueuedPlayers.ToList();
            zone.QueuedPlayers.Clear();
            
            // Create new match
            var matchId = (ulong)UnityEngine.Random.Range(100000, 999999);
            var match = new Match
            {
                MatchId = matchId,
                MapName = zone.SelectedMap,
                QueueZoneName = zone.Name,
                State = MatchState.InProgress
            };
            
            // Assign teams randomly
            var shuffledPlayers = queuedPlayers.OrderBy(x => UnityEngine.Random.value).ToList();
            for (int i = 0; i < shuffledPlayers.Count; i++)
            {
                var playerId = shuffledPlayers[i];
                var data = GetPlayerData(playerId);
                data.CurrentMatchId = matchId;
                data.IsInQueue = false;
                data.QueueZoneName = "";
                
                if (i < zone.TeamSize)
                {
                    match.TerroristPlayers.Add(playerId);
                    data.CurrentTeam = Team.Terrorist;
                }
                else
                {
                    match.CounterTerroristPlayers.Add(playerId);
                    data.CurrentTeam = Team.CounterTerrorist;
                }
            }
            
            activeMatches[matchId] = match;
            
            // Notify players and start first round
            NotifyMatchStart(match);
            StartRound(match);
        }
        
        #endregion
        
        #region Match Management
        
        private void NotifyMatchStart(Match match)
        {
            var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
            
            foreach (var playerId in allPlayers)
            {
                var player = BasePlayer.FindByID(playerId);
                if (player != null)
                {
                    SendReply(player, $"Match {match.MatchId} started! Map: {match.MapName}");
                    SendReply(player, $"First to {config.RoundWinRequirement} rounds wins!");
                }
            }
        }
        
        private void StartRound(Match match)
        {
            match.CurrentRound++;
            match.RoundStartTime = Time.time;
            match.IsBuyPhase = true;
            match.PlantedBomb = null;
            
            // Reset round stats for all players
            var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
            foreach (var playerId in allPlayers)
            {
                var data = GetPlayerData(playerId);
                data.RoundKills = 0;
                data.RoundDeaths = 0;
            }
            
            // Check for side swap
            if (match.CurrentRound == config.SideSwapRound + 1 && !match.HasSwappedSides)
            {
                SwapTeams(match);
            }
            
            // Teleport players to spawns
            TeleportPlayersToSpawns(match);
            
            // Give satchel to terrorists
            GiveSatchelToTerrorists(match);
            
            // Start buy phase timer
            DestroyTimer(ref match.BuyPhaseTimer); // Destroy any existing timer first
            match.BuyPhaseTimer = timer.Once(config.BuyPhaseDuration, () => EndBuyPhase(match));
            
            // Start round timer (extended if bomb is planted)
            float roundDuration = 120f; // 2 minutes default
            DestroyTimer(ref match.RoundTimer); // Destroy any existing timer first
            match.RoundTimer = timer.Once(roundDuration, () => EndRound(match, RoundEndReason.TimeExpired));
            
            NotifyRoundStart(match);
        }
        
        private void SwapTeams(Match match)
        {
            match.HasSwappedSides = true;
            
            // Swap player teams
            foreach (var playerId in match.TerroristPlayers.ToList())
            {
                var data = GetPlayerData(playerId);
                data.CurrentTeam = Team.CounterTerrorist;
            }
            
            foreach (var playerId in match.CounterTerroristPlayers.ToList())
            {
                var data = GetPlayerData(playerId);
                data.CurrentTeam = Team.Terrorist;
            }
            
            // Swap team lists
            var tempList = match.TerroristPlayers.ToList();
            match.TerroristPlayers = match.CounterTerroristPlayers.ToList();
            match.CounterTerroristPlayers = tempList;
            
            NotifyTeamSwap(match);
        }
        
        private void TeleportPlayersToSpawns(Match match)
        {
            if (!mapConfigurations.ContainsKey(match.MapName)) return;
            
            var mapConfig = mapConfigurations[match.MapName];
            
            // Teleport terrorists
            for (int i = 0; i < match.TerroristPlayers.Count; i++)
            {
                var player = BasePlayer.FindByID(match.TerroristPlayers[i]);
                if (player != null && i < mapConfig.TerroristSpawns.Count)
                {
                    TeleportPlayer(player, mapConfig.TerroristSpawns[i]);
                    GetPlayerData(player.userID).IsSpectating = false;
                }
            }
            
            // Teleport counter-terrorists
            for (int i = 0; i < match.CounterTerroristPlayers.Count; i++)
            {
                var player = BasePlayer.FindByID(match.CounterTerroristPlayers[i]);
                if (player != null && i < mapConfig.CounterTerroristSpawns.Count)
                {
                    TeleportPlayer(player, mapConfig.CounterTerroristSpawns[i]);
                    GetPlayerData(player.userID).IsSpectating = false;
                }
            }
        }
        
        private void TeleportPlayer(BasePlayer player, Vector3 position)
        {
            if (player == null) return;
            
            player.Teleport(position);
            player.SendNetworkUpdateImmediate();
        }
        
        private void GiveSatchelToTerrorists(Match match)
        {
            // Give satchel to first alive terrorist
            foreach (var playerId in match.TerroristPlayers)
            {
                var player = BasePlayer.FindByID(playerId);
                if (player != null && !player.IsDead())
                {
                    GiveItem(player, "explosive.satchel", 1);
                    SendReply(player, "You have the bomb! Plant it at a bomb site.");
                    break;
                }
            }
        }
        
        private void EndBuyPhase(Match match)
        {
            match.IsBuyPhase = false;
            
            var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
            foreach (var playerId in allPlayers)
            {
                var player = BasePlayer.FindByID(playerId);
                if (player != null)
                {
                    var data = GetPlayerData(playerId);
                    if (data.HasBuyMenuOpen)
                    {
                        CloseBuyMenu(player);
                    }
                    SendReply(player, "Buy phase ended!");
                }
            }
        }
        
        #endregion
        
        #region Round Management
        
        private void CheckRoundEnd(Match match)
        {
            if (match.State != MatchState.InProgress) return;
            
            int aliveTerrorists = CountAlivePlayers(match.TerroristPlayers);
            int aliveCounterTerrorists = CountAlivePlayers(match.CounterTerroristPlayers);
            
            if (aliveTerrorists == 0 && match.PlantedBomb == null)
            {
                EndRound(match, RoundEndReason.TerroristsEliminated);
            }
            else if (aliveCounterTerrorists == 0)
            {
                EndRound(match, RoundEndReason.CounterTerroristsEliminated);
            }
        }
        
        private int CountAlivePlayers(List<ulong> playerIds)
        {
            int count = 0;
            foreach (var playerId in playerIds)
            {
                var player = BasePlayer.FindByID(playerId);
                if (player != null && !player.IsDead())
                {
                    count++;
                }
            }
            return count;
        }
        
        private void EndRound(Match match, RoundEndReason reason)
        {
            // Cancel timers
            match.RoundTimer?.Destroy();
            match.BuyPhaseTimer?.Destroy();
            
            // Determine winner
            Team winningTeam = DetermineRoundWinner(reason);
            
            if (winningTeam == Team.Terrorist)
            {
                match.TerroristScore++;
            }
            else if (winningTeam == Team.CounterTerrorist)
            {
                match.CounterTerroristScore++;
            }
            
            // Notify round end
            NotifyRoundEnd(match, reason, winningTeam);
            
            // Check if match is over
            if (match.TerroristScore >= config.RoundWinRequirement || 
                match.CounterTerroristScore >= config.RoundWinRequirement)
            {
                EndMatch(match, "Score limit reached");
            }
            else
            {
                // Start next round after delay
                timer.Once(5f, () => StartRound(match));
            }
        }
        
        private Team DetermineRoundWinner(RoundEndReason reason)
        {
            switch (reason)
            {
                case RoundEndReason.TerroristsEliminated:
                case RoundEndReason.BombDefused:
                    return Team.CounterTerrorist;
                case RoundEndReason.CounterTerroristsEliminated:
                case RoundEndReason.BombExploded:
                    return Team.Terrorist;
                case RoundEndReason.TimeExpired:
                    return Team.CounterTerrorist; // CTs win on time
                default:
                    return Team.None;
            }
        }
        
        private void NotifyRoundStart(Match match)
        {
            var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
            
            foreach (var playerId in allPlayers)
            {
                var player = BasePlayer.FindByID(playerId);
                if (player != null)
                {
                    SendReply(player, $"Round {match.CurrentRound} started!");
                    SendReply(player, $"Score: T {match.TerroristScore} - {match.CounterTerroristScore} CT");
                }
            }
        }
        
        private void NotifyRoundEnd(Match match, RoundEndReason reason, Team winner)
        {
            string message = GetRoundEndMessage(reason, winner);
            
            var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
            foreach (var playerId in allPlayers)
            {
                var player = BasePlayer.FindByID(playerId);
                if (player != null)
                {
                    SendReply(player, message);
                    SendReply(player, $"Score: T {match.TerroristScore} - {match.CounterTerroristScore} CT");
                }
            }
        }
        
        private string GetRoundEndMessage(RoundEndReason reason, Team winner)
        {
            string teamName = winner == Team.Terrorist ? "Terrorists" : "Counter-Terrorists";
            
            switch (reason)
            {
                case RoundEndReason.TerroristsEliminated:
                    return "Counter-Terrorists win - All terrorists eliminated!";
                case RoundEndReason.CounterTerroristsEliminated:
                    return "Terrorists win - All counter-terrorists eliminated!";
                case RoundEndReason.BombExploded:
                    return "Terrorists win - Bomb exploded!";
                case RoundEndReason.BombDefused:
                    return "Counter-Terrorists win - Bomb defused!";
                case RoundEndReason.TimeExpired:
                    return "Counter-Terrorists win - Time expired!";
                default:
                    return $"{teamName} win the round!";
            }
        }
        
        private void NotifyTeamSwap(Match match)
        {
            var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
            
            foreach (var playerId in allPlayers)
            {
                var player = BasePlayer.FindByID(playerId);
                if (player != null)
                {
                    SendReply(player, "Teams have been swapped!");
                }
            }
        }
        
        private void EndMatch(Match match, string reason)
        {
            match.State = MatchState.Finished;
            
            // Calculate ELO changes
            CalculateELOChange(match);
            
            // Determine match winner
            Team winningTeam = Team.None;
            if (match.TerroristScore > match.CounterTerroristScore)
                winningTeam = Team.Terrorist;
            else if (match.CounterTerroristScore > match.TerroristScore)
                winningTeam = Team.CounterTerrorist;
            
            // Notify match end
            NotifyMatchEnd(match, winningTeam, reason);
            
            // Update player statistics and analytics
            UpdatePlayerStatistics(match);
            
            // Give daily skin drops
            var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
            foreach (var playerId in allPlayers)
            {
                var player = BasePlayer.FindByID(playerId);
                if (player != null)
                {
                    CheckDailySkinDrop(player);
                }
            }
            
            // Clean up players
            foreach (var playerId in allPlayers)
            {
                var data = GetPlayerData(playerId);
                data.CurrentMatchId = 0;
                data.CurrentTeam = Team.None;
                data.IsSpectating = false;
                data.TeamDamageDealt = 0f;
                
                var player = BasePlayer.FindByID(playerId);
                if (player != null)
                {
                    TeleportPlayer(player, config.LobbySpawnPoint);
                    ResetPlayerInventory(player);
                }
            }
            
            // Clean up match
            match.RoundTimer?.Destroy();
            match.BuyPhaseTimer?.Destroy();
            match.PlantedBomb?.ExplosionTimer?.Destroy();
            
            activeMatches.Remove(match.MatchId);
        }
        
        private void NotifyMatchEnd(Match match, Team winner, string reason)
        {
            string message = winner == Team.None ? 
                $"Match {match.MatchId} ended in a tie! ({reason})" :
                $"Match {match.MatchId} won by {(winner == Team.Terrorist ? "Terrorists" : "Counter-Terrorists")}! ({reason})";
            
            var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
            foreach (var playerId in allPlayers)
            {
                var player = BasePlayer.FindByID(playerId);
                if (player != null)
                {
                    SendReply(player, message);
                    SendReply(player, $"Final Score: T {match.TerroristScore} - {match.CounterTerroristScore} CT");
                }
            }
        }
        
        #endregion
        
        #region Bomb System
        
        void OnExplosiveThrown(BasePlayer player, BaseEntity entity)
        {
            if (player == null || entity == null) return;
            
            var data = GetPlayerData(player.userID);
            if (data.CurrentMatchId == 0) return;
            
            if (!activeMatches.ContainsKey(data.CurrentMatchId)) return;
            var match = activeMatches[data.CurrentMatchId];
            
            if (match.State != MatchState.InProgress) return;
            
            // Check if it's a satchel charge
            if (entity.ShortPrefabName.Contains("satchel"))
            {
                HandleSatchelThrown(player, entity, match);
            }
        }
        
        private void HandleSatchelThrown(BasePlayer player, BaseEntity satchel, Match match)
        {
            var data = GetPlayerData(player.userID);
            
            // Only terrorists can plant
            if (data.CurrentTeam != Team.Terrorist)
            {
                SendReply(player, "Only terrorists can plant the bomb!");
                return;
            }
            
            timer.Once(0.5f, () => CheckSatchelPlacement(player, satchel, match));
        }
        
        private void CheckSatchelPlacement(BasePlayer player, BaseEntity satchel, Match match)
        {
            if (satchel == null || satchel.IsDestroyed) return;
            
            var satchelPos = satchel.transform.position;
            BombSite targetSite = null;
            
            // Check if satchel is in a bomb site
            foreach (var site in bombSites.Values)
            {
                if (site.MapName != match.MapName || !site.IsActive) continue;
                
                if (IsPlayerInZone(satchelPos, site.MinBounds, site.MaxBounds))
                {
                    targetSite = site;
                    break;
                }
            }
            
            if (targetSite == null)
            {
                // Satchel placed outside bomb site - make it droppable
                SendReply(player, "Bomb must be planted at a bomb site!");
                return;
            }
            
            // Plant the bomb
            PlantBomb(player, satchel, match, targetSite);
        }
        
        private void PlantBomb(BasePlayer player, BaseEntity satchel, Match match, BombSite site)
        {
            match.PlantedBomb = new PlantedBomb
            {
                Position = satchel.transform.position,
                PlantTime = Time.time,
                PlanterId = player.userID,
                BombSiteName = site.Name
            };
            
            // Start explosion timer
            match.PlantedBomb.ExplosionTimer = timer.Once(config.BombTimer, () => ExplodeBomb(match));
            
            // Extend round timer
            match.RoundTimer?.Destroy();
            match.RoundTimer = timer.Once(config.BombTimer + 10f, () => EndRound(match, RoundEndReason.BombExploded));
            
            // Notify players
            var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
            foreach (var playerId in allPlayers)
            {
                var targetPlayer = BasePlayer.FindByID(playerId);
                if (targetPlayer != null)
                {
                    SendReply(targetPlayer, $"Bomb planted at {site.Name}! {config.BombTimer} seconds to explosion!");
                }
            }
            
            // Start beeping sound effect
            StartBombBeeping(match);
        }
        
        private void StartBombBeeping(Match match)
        {
            if (match.PlantedBomb == null) return;
            
            // Create beeping effect (simplified - in real implementation you'd use sound effects)
            var beepTimer = timer.Repeat(1f, (int)config.BombTimer, () =>
            {
                if (match.PlantedBomb == null) return;
                
                var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
                foreach (var playerId in allPlayers)
                {
                    var player = BasePlayer.FindByID(playerId);
                    if (player != null)
                    {
                        // In a real implementation, play beep sound here
                        float timeLeft = config.BombTimer - (Time.time - match.PlantedBomb.PlantTime);
                        if (timeLeft <= 10f)
                        {
                            SendReply(player, $"BOMB: {timeLeft:F0}s");
                        }
                    }
                }
            });
        }
        
        private void ExplodeBomb(Match match)
        {
            if (match.PlantedBomb == null) return;
            
            // Create explosion effect at bomb position
            var explosionPos = match.PlantedBomb.Position;
            
            // Deal damage to nearby players
            var nearbyPlayers = BasePlayer.activePlayerList.Where(p => 
                Vector3.Distance(p.transform.position, explosionPos) <= 10f).ToList();
            
            foreach (var player in nearbyPlayers)
            {
                player.Hurt(100f, DamageType.Explosion);
            }
            
            // End round
            EndRound(match, RoundEndReason.BombExploded);
        }
        
        #endregion
        
        #region Defuse System
        
        private void StartDefuse(BasePlayer player, Match match)
        {
            var data = GetPlayerData(player.userID);
            
            if (data.IsDefusing) return; // Already defusing
            
            if (match.PlantedBomb.IsBeingDefused && match.PlantedBomb.DefuserId != player.userID)
            {
                SendReply(player, "Someone else is already defusing!");
                return;
            }
            
            data.IsDefusing = true;
            match.PlantedBomb.IsBeingDefused = true;
            match.PlantedBomb.DefuserId = player.userID;
            
            SendReply(player, "Defusing bomb... Hold USE key!");
            
            // Notify other players
            var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
            foreach (var playerId in allPlayers)
            {
                if (playerId == player.userID) continue;
                
                var targetPlayer = BasePlayer.FindByID(playerId);
                if (targetPlayer != null)
                {
                    SendReply(targetPlayer, $"{player.displayName} is defusing the bomb!");
                }
            }
            
            // Start defuse timer (5 seconds)
            data.DefuseTimer = timer.Once(5f, () => CompleteDefuse(player, match));
        }
        
        private void StopDefuse(BasePlayer player, Match match)
        {
            var data = GetPlayerData(player.userID);
            
            if (!data.IsDefusing) return;
            
            data.IsDefusing = false;
            data.DefuseTimer?.Destroy();
            
            if (match.PlantedBomb != null && match.PlantedBomb.DefuserId == player.userID)
            {
                match.PlantedBomb.IsBeingDefused = false;
                match.PlantedBomb.DefuserId = 0;
            }
            
            SendReply(player, "Defuse cancelled!");
        }
        
        private void CompleteDefuse(BasePlayer player, Match match)
        {
            var data = GetPlayerData(player.userID);
            
            if (!data.IsDefusing || match.PlantedBomb == null) return;
            
            // Stop defuse
            data.IsDefusing = false;
            data.DefuseTimer?.Destroy();
            
            // Cancel bomb explosion
            match.PlantedBomb.ExplosionTimer?.Destroy();
            match.PlantedBomb = null;
            
            // End round
            EndRound(match, RoundEndReason.BombDefused);
        }
        
        #endregion
        
        #region Buy System
        
        private void CmdBuyMenu(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_USE))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            var data = GetPlayerData(player.userID);
            if (data.CurrentMatchId == 0)
            {
                SendReply(player, "You must be in a match to use the buy menu!");
                return;
            }
            
            if (!activeMatches.ContainsKey(data.CurrentMatchId)) return;
            var match = activeMatches[data.CurrentMatchId];
            
            if (!match.IsBuyPhase)
            {
                SendReply(player, "Buy phase is over!");
                return;
            }
            
            if (data.HasBuyMenuOpen)
            {
                CloseBuyMenu(player);
            }
            else
            {
                OpenBuyMenu(player);
            }
        }
        
