        private void CmdBuyItem(BasePlayer player, string command, string[] args)
        {
            if (args.Length == 0) return;
            
            string itemShortname = args[0];
            BuyItem(player, itemShortname);
        }
        
        private void CmdCloseBuyMenu(BasePlayer player, string command, string[] args)
        {
            CloseBuyMenu(player);
        }
        
        private void BuyItem(BasePlayer player, string itemShortname)
        {
            var data = GetPlayerData(player.userID);
            
            if (data.CurrentMatchId == 0) return;
            if (!activeMatches.ContainsKey(data.CurrentMatchId)) return;
            var match = activeMatches[data.CurrentMatchId];
            
            if (!match.IsBuyPhase)
            {
                SendReply(player, "Buy phase is over!");
                return;
            }
            
            // Check item category and enforce limits
            var itemCategory = GetItemCategory(itemShortname);
            
            switch (itemCategory)
            {
                case ItemCategory.Primary:
                    RemoveItemsByCategory(player, ItemCategory.Primary);
                    break;
                case ItemCategory.Secondary:
                    RemoveItemsByCategory(player, ItemCategory.Secondary);
                    break;
                case ItemCategory.Armor:
                    RemoveItemsByCategory(player, ItemCategory.Armor);
                    break;
            }
            
            // Give the item
            GiveItem(player, itemShortname, 1);
            SendReply(player, $"Purchased {itemShortname}");
        }
        
        private ItemCategory GetItemCategory(string itemShortname)
        {
            if (itemShortname.Contains("rifle") || itemShortname.Contains("smg"))
                return ItemCategory.Primary;
            if (itemShortname.Contains("pistol"))
                return ItemCategory.Secondary;
            if (itemShortname.Contains("metal.plate") || itemShortname.Contains("metal.facemask"))
                return ItemCategory.Armor;
            
            return ItemCategory.Utility;
        }
        
        private void RemoveItemsByCategory(BasePlayer player, ItemCategory category)
        {
            var itemsToRemove = new List<Item>();
            
            foreach (var item in player.inventory.AllItems())
            {
                if (GetItemCategory(item.info.shortname) == category)
                {
                    itemsToRemove.Add(item);
                }
            }
            
            foreach (var item in itemsToRemove)
            {
                item.RemoveFromContainer();
                item.Remove();
            }
        }
        
        private void CloseBuyMenu(BasePlayer player)
        {
            var data = GetPlayerData(player.userID);
            data.HasBuyMenuOpen = false;
            
            CuiHelper.DestroyUi(player, "BuyMenu");
        }
        
        private void GiveItem(BasePlayer player, string itemShortname, int amount)
        {
            var item = ItemManager.CreateByName(itemShortname, amount);
            if (item != null)
            {
                player.GiveItem(item);
            }
        }
        
        public enum ItemCategory
        {
            Primary,
            Secondary,
            Armor,
            Utility
        }
        
        #endregion
        
        #region Team Damage System
        
        void OnEntityTakeDamage(BaseCombatEntity entity, HitInfo info)
        {
            if (entity == null || info == null) return;
            
            var victim = entity as BasePlayer;
            var attacker = info.InitiatorPlayer;
            
            if (victim == null || attacker == null || victim == attacker) return;
            
            var victimData = GetPlayerData(victim.userID);
            var attackerData = GetPlayerData(attacker.userID);
            
            // Check if both players are in the same match
            if (victimData.CurrentMatchId == 0 || attackerData.CurrentMatchId == 0) return;
            if (victimData.CurrentMatchId != attackerData.CurrentMatchId) return;
            
            if (!activeMatches.ContainsKey(victimData.CurrentMatchId)) return;
            var match = activeMatches[victimData.CurrentMatchId];
            
            if (match.State != MatchState.InProgress) return;
            
            // Check for team damage
            if (victimData.CurrentTeam == attackerData.CurrentTeam)
            {
                HandleTeamDamage(attacker, victim, info);
            }
            
            // Handle grenade damage cap
            if (info.damageTypes.Has(DamageType.Explosion))
            {
                if (info.damageTypes.Get(DamageType.Explosion) > config.MaxGrenadeDamage)
                {
                    info.damageTypes.Set(DamageType.Explosion, config.MaxGrenadeDamage);
                }
            }
        }
        
        private void HandleTeamDamage(BasePlayer attacker, BasePlayer victim, HitInfo info)
        {
            var attackerData = GetPlayerData(attacker.userID);
            
            float damage = info.damageTypes.Total();
            attackerData.TeamDamageDealt += damage;
            
            SendReply(attacker, $"Team damage dealt: {damage:F0} (Total: {attackerData.TeamDamageDealt:F0}/{config.MaxTeamDamage})");
            
            if (attackerData.TeamDamageDealt >= config.MaxTeamDamage)
            {
                KickPlayerForTeamDamage(attacker);
            }
        }
        
        private void HandleTeamKill(BasePlayer attacker, BasePlayer victim, HitInfo info)
        {
            var attackerData = GetPlayerData(attacker.userID);
            
            // Add significant team damage for team kill
            attackerData.TeamDamageDealt += 100f;
            
            SendReply(attacker, $"Team kill! Total team damage: {attackerData.TeamDamageDealt:F0}/{config.MaxTeamDamage}");
            
            // Notify all players in the match
            if (activeMatches.ContainsKey(attackerData.CurrentMatchId))
            {
                var match = activeMatches[attackerData.CurrentMatchId];
                var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
                
                foreach (var playerId in allPlayers)
                {
                    var player = BasePlayer.FindByID(playerId);
                    if (player != null && player != attacker)
                    {
                        SendReply(player, $"{attacker.displayName} team killed {victim.displayName}");
                    }
                }
            }
            
            if (attackerData.TeamDamageDealt >= config.MaxTeamDamage)
            {
                KickPlayerForTeamDamage(attacker);
            }
        }
        
        private void KickPlayerForTeamDamage(BasePlayer player)
        {
            var data = GetPlayerData(player.userID);
            
            SendReply(player, "You have been kicked for excessive team damage!");
            
            // Remove from match
            if (data.CurrentMatchId != 0 && activeMatches.ContainsKey(data.CurrentMatchId))
            {
                var match = activeMatches[data.CurrentMatchId];
                
                // Notify other players
                var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
                foreach (var playerId in allPlayers)
                {
                    if (playerId == player.userID) continue;
                    
                    var targetPlayer = BasePlayer.FindByID(playerId);
                    if (targetPlayer != null)
                    {
                        SendReply(targetPlayer, $"{player.displayName} was kicked for team damage");
                    }
                }
                
                // Remove from team lists
                match.TerroristPlayers.Remove(player.userID);
                match.CounterTerroristPlayers.Remove(player.userID);
                
                // Check if match should end due to insufficient players
                if (match.TerroristPlayers.Count == 0 || match.CounterTerroristPlayers.Count == 0)
                {
                    EndMatch(match, "Insufficient players");
                }
            }
            
            // Reset player data
            data.CurrentMatchId = 0;
            data.CurrentTeam = Team.None;
            data.TeamDamageDealt = 0f;
            data.IsSpectating = false;
            
            // Teleport to lobby
            TeleportPlayer(player, config.LobbySpawnPoint);
        }
        
        #endregion
        
        #region Spectator System
        
        private void MoveToSpectatorArea(BasePlayer player, Match match)
        {
            if (player == null || match == null) return;
            
            var data = GetPlayerData(player.userID);
            data.IsSpectating = true;
            
            if (mapConfigurations.ContainsKey(match.MapName))
            {
                var mapConfig = mapConfigurations[match.MapName];
                TeleportPlayer(player, mapConfig.SpectatorArea);
            }
            
            SendReply(player, "You are now spectating. You will respawn next round.");
            SendReply(player, "Commands: /spec [player] | /specnext | /specprev | /freecam");
            
            // Auto-start spectating teammates
            timer.Once(1f, () => StartSpectatingTeammate(player));
        }
        
        private void HandlePlayerReconnection(BasePlayer player, Match match)
        {
            var data = GetPlayerData(player.userID);
            
            if (player.IsDead() || data.IsSpectating)
            {
                MoveToSpectatorArea(player, match);
            }
            else
            {
                // Teleport to appropriate spawn
                if (data.CurrentTeam == Team.Terrorist && mapConfigurations.ContainsKey(match.MapName))
                {
                    var mapConfig = mapConfigurations[match.MapName];
                    if (mapConfig.TerroristSpawns.Count > 0)
                    {
                        TeleportPlayer(player, mapConfig.TerroristSpawns[0]);
                    }
                }
                else if (data.CurrentTeam == Team.CounterTerrorist && mapConfigurations.ContainsKey(match.MapName))
                {
                    var mapConfig = mapConfigurations[match.MapName];
                    if (mapConfig.CounterTerroristSpawns.Count > 0)
                    {
                        TeleportPlayer(player, mapConfig.CounterTerroristSpawns[0]);
                    }
                }
            }
            
            SendReply(player, $"Reconnected to match {match.MatchId}");
        }
        
        private void RestorePlayerForMatch(BasePlayer player, Match match)
        {
            // Clear inventory first
            ResetPlayerInventory(player);
            
            // Give basic equipment based on team
            var data = GetPlayerData(player.userID);
            
            if (data.CurrentTeam == Team.Terrorist)
            {
                GiveItem(player, "rifle.ak", 1);
                GiveItem(player, "pistol.m92", 1);
            }
            else if (data.CurrentTeam == Team.CounterTerrorist)
            {
                GiveItem(player, "rifle.lr300", 1);
                GiveItem(player, "pistol.m92", 1);
            }
            
            // Give basic armor
            GiveItem(player, "metal.plate.torso", 1);
            
            // Give ammunition
            GiveItem(player, "ammo.rifle", 90);
            GiveItem(player, "ammo.pistol", 60);
        }
        
        private void ResetPlayerInventory(BasePlayer player)
        {
            player.inventory.Strip();
        }
        
