            {
                Text = { Text = roundInfo, FontSize = 14, Align = TextAnchor.MiddleCenter, Color = "1 1 1 1" },
                RectTransform = { AnchorMin = "0 0.7", AnchorMax = "1 1" }
            }, "MatchUI");
            
            // Score display
            string scoreText = $"T {match.TerroristScore} - {match.CounterTerroristScore} CT";
            container.Add(new CuiLabel
            {
                Text = { Text = scoreText, FontSize = 16, Align = TextAnchor.MiddleCenter, Color = "1 1 0 1" },
                RectTransform = { AnchorMin = "0 0.4", AnchorMax = "1 0.7" }
            }, "MatchUI");
            
            // Bomb status
            if (match.PlantedBomb != null)
            {
                float bombTimeLeft = config.BombTimer - (Time.time - match.PlantedBomb.PlantTime);
                string bombText = $"BOMB PLANTED: {bombTimeLeft:F0}s";
                if (match.PlantedBomb.IsBeingDefused)
                {
                    bombText += " (DEFUSING)";
                }
                
                container.Add(new CuiLabel
                {
                    Text = { Text = bombText, FontSize = 12, Align = TextAnchor.MiddleCenter, Color = "1 0 0 1" },
                    RectTransform = { AnchorMin = "0 0.1", AnchorMax = "1 0.4" }
                }, "MatchUI");
            }
            
            CuiHelper.AddUi(player, container);
        }
        
        private string GetQueueStatusText()
        {
            var status = new List<string>();
            
            foreach (var zone in queueZones.Values)
            {
                if (zone.IsActive)
                {
                    status.Add($"{zone.Name}: {zone.QueuedPlayers.Count}/{zone.TeamSize * 2}");
                }
            }
            
            return status.Count > 0 ? string.Join("\n", status) : "No active queues";
        }
        
        private float GetRoundTimeLeft(Match match)
        {
            if (match.PlantedBomb != null)
            {
                return config.BombTimer - (Time.time - match.PlantedBomb.PlantTime);
            }
            
            return 120f - (Time.time - match.RoundStartTime); // Default 2 minute rounds
        }
        
        private void UpdateAllUI()
        {
            foreach (var player in BasePlayer.activePlayerList)
            {
                UpdatePlayerUI(player);
            }
        }
        
        private void UpdatePlayerUI(BasePlayer player)
        {
            if (!IsValidPlayer(player)) return;
            DestroyUI(player);
            CreateUI(player);
        }
        
        private void DestroyUI(BasePlayer player)
        {
            if (!IsValidPlayer(player)) return;
            
            SafeDestroyUI(player, "LobbyUI");
            SafeDestroyUI(player, "MatchUI");
            SafeDestroyUI(player, "BuyMenu");
            SafeDestroyUI(player, "SpectatorUI");
            SafeDestroyUI(player, "FreeCamUI");
            SafeDestroyUI(player, "VoiceChatUI");
            SafeDestroyUI(player, "VoteUI");
        }
        
