        private void CmdSetQueueZone(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_ADMIN))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length == 0)
            {
                SendReply(player, "Usage: /setqzone <name> [teamsize]");
                return;
            }
            
            string zoneName = args[0];
            int teamSize = args.Length > 1 ? int.Parse(args[1]) : config.DefaultTeamSize;
            
            var clipboard = GetClipboard(player.userID);
            
            if (clipboard.PointA == null)
            {
                clipboard.PointA = player.transform.position;
                clipboard.PendingCommand = $"setqzone {zoneName} {teamSize}";
                SendReply(player, $"Point A set at {clipboard.PointA}. Move to Point B and run the command again.");
                return;
            }
            
            if (clipboard.PointB == null)
            {
                clipboard.PointB = player.transform.position;
            }
            
            // Create queue zone
            var minBounds = new Vector3(
                Mathf.Min(clipboard.PointA.Value.x, clipboard.PointB.Value.x),
                Mathf.Min(clipboard.PointA.Value.y, clipboard.PointB.Value.y),
                Mathf.Min(clipboard.PointA.Value.z, clipboard.PointB.Value.z)
            );
            
            var maxBounds = new Vector3(
                Mathf.Max(clipboard.PointA.Value.x, clipboard.PointB.Value.x),
                Mathf.Max(clipboard.PointA.Value.y, clipboard.PointB.Value.y),
                Mathf.Max(clipboard.PointA.Value.z, clipboard.PointB.Value.z)
            );
            
            queueZones[zoneName] = new QueueZone
            {
                Name = zoneName,
                MinBounds = minBounds,
                MaxBounds = maxBounds,
                TeamSize = teamSize,
                IsActive = true
            };
            
            SendReply(player, $"Queue zone '{zoneName}' created with team size {teamSize}!");
            
            // Clear clipboard
            clipboard.PointA = null;
            clipboard.PointB = null;
            clipboard.PendingCommand = "";
            
            SaveData();
        }
        
        private void CmdRemoveQueueZone(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_ADMIN))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length == 0)
            {
                SendReply(player, "Usage: /removeqzone <name>");
                return;
            }
            
            string zoneName = args[0];
            
            if (!queueZones.ContainsKey(zoneName))
            {
                SendReply(player, $"Queue zone '{zoneName}' not found!");
                return;
            }
            
            // Remove players from queue
            var zone = queueZones[zoneName];
            foreach (var playerId in zone.QueuedPlayers.ToList())
            {
                RemovePlayerFromQueue(playerId);
            }
            
            queueZones.Remove(zoneName);
            SendReply(player, $"Queue zone '{zoneName}' removed!");
            
            SaveData();
        }
        
