        private void CmdSetSpawn(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_ADMIN))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length < 2)
            {
                SendReply(player, "Usage: /setspawn <mapname> <terrorist|ct>");
                return;
            }
            
            string mapName = args[0];
            string teamName = args[1].ToLower();
            
            if (teamName != "terrorist" && teamName != "ct")
            {
                SendReply(player, "Team must be 'terrorist' or 'ct'!");
                return;
            }
            
            if (!mapConfigurations.ContainsKey(mapName))
            {
                mapConfigurations[mapName] = new MapConfiguration { MapName = mapName };
            }
            
            var mapConfig = mapConfigurations[mapName];
            var spawnPosition = player.transform.position;
            
            if (teamName == "terrorist")
            {
                mapConfig.TerroristSpawns.Add(spawnPosition);
                SendReply(player, $"Terrorist spawn added for map '{mapName}' at {spawnPosition}");
            }
            else
            {
                mapConfig.CounterTerroristSpawns.Add(spawnPosition);
                SendReply(player, $"Counter-Terrorist spawn added for map '{mapName}' at {spawnPosition}");
            }
            
            SaveData();
        }
        
        private void CmdRemoveSpawn(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_ADMIN))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length < 2)
            {
                SendReply(player, "Usage: /removespawn <mapname> <terrorist|ct> [index]");
                return;
            }
            
            string mapName = args[0];
            string teamName = args[1].ToLower();
            
            if (!mapConfigurations.ContainsKey(mapName))
            {
                SendReply(player, $"Map '{mapName}' not found!");
                return;
            }
            
            var mapConfig = mapConfigurations[mapName];
            
            if (teamName == "terrorist")
            {
                if (args.Length > 2 && int.TryParse(args[2], out int index))
                {
                    if (index >= 0 && index < mapConfig.TerroristSpawns.Count)
                    {
                        mapConfig.TerroristSpawns.RemoveAt(index);
                        SendReply(player, $"Terrorist spawn {index} removed from map '{mapName}'");
                    }
                    else
                    {
                        SendReply(player, "Invalid spawn index!");
                    }
                }
                else
                {
                    if (mapConfig.TerroristSpawns.Count > 0)
                    {
                        mapConfig.TerroristSpawns.RemoveAt(mapConfig.TerroristSpawns.Count - 1);
                        SendReply(player, $"Last terrorist spawn removed from map '{mapName}'");
                    }
                    else
                    {
                        SendReply(player, "No terrorist spawns to remove!");
                    }
                }
            }
            else if (teamName == "ct")
            {
                if (args.Length > 2 && int.TryParse(args[2], out int index))
                {
                    if (index >= 0 && index < mapConfig.CounterTerroristSpawns.Count)
                    {
                        mapConfig.CounterTerroristSpawns.RemoveAt(index);
                        SendReply(player, $"Counter-Terrorist spawn {index} removed from map '{mapName}'");
                    }
                    else
                    {
                        SendReply(player, "Invalid spawn index!");
                    }
                }
                else
                {
                    if (mapConfig.CounterTerroristSpawns.Count > 0)
                    {
                        mapConfig.CounterTerroristSpawns.RemoveAt(mapConfig.CounterTerroristSpawns.Count - 1);
                        SendReply(player, $"Last counter-terrorist spawn removed from map '{mapName}'");
                    }
                    else
                    {
                        SendReply(player, "No counter-terrorist spawns to remove!");
                    }
                }
            }
            else
            {
                SendReply(player, "Team must be 'terrorist' or 'ct'!");
            }
            
            SaveData();
        }
        
        private ClipboardData GetClipboard(ulong playerId)
        {
            if (!adminClipboard.ContainsKey(playerId))
            {
                adminClipboard[playerId] = new ClipboardData();
            }
            return adminClipboard[playerId];
        }
        
