        private void CmdJoinQueue(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_USE))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            var data = GetPlayerData(player.userID);
            
            if (data.IsInQueue)
            {
                SendReply(player, "You are already in a queue!");
                return;
            }
            
            if (data.CurrentMatchId != 0)
            {
                SendReply(player, "You are already in a match!");
                return;
            }
            
            // Find nearest queue zone
            QueueZone nearestZone = null;
            float nearestDistance = float.MaxValue;
            
            foreach (var zone in queueZones.Values)
            {
                if (!zone.IsActive) continue;
                
                var center = (zone.MinBounds + zone.MaxBounds) / 2f;
                float distance = Vector3.Distance(player.transform.position, center);
                
                if (distance < nearestDistance)
                {
                    nearestDistance = distance;
                    nearestZone = zone;
                }
            }
            
            if (nearestZone == null)
            {
                SendReply(player, "No queue zones available!");
                return;
            }
            
            AddPlayerToQueue(player, nearestZone);
        }
        
        private void CmdLeaveQueue(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_USE))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            var data = GetPlayerData(player.userID);
            
            if (!data.IsInQueue)
            {
                SendReply(player, "You are not in a queue!");
                return;
            }
            
            RemovePlayerFromQueue(player.userID);
        }
        
        private void CmdForceStartMatch(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_ADMIN))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length == 0)
            {
                SendReply(player, "Usage: /forcestart <queuezone>");
                return;
            }
            
            string zoneName = args[0];
            
            if (!queueZones.ContainsKey(zoneName))
            {
                SendReply(player, $"Queue zone '{zoneName}' not found!");
                return;
            }
            
            var zone = queueZones[zoneName];
            
            if (zone.QueuedPlayers.Count < 2)
            {
                SendReply(player, "Need at least 2 players to start a match!");
                return;
            }
            
            StartMatch(zone);
            SendReply(player, $"Match started in zone '{zoneName}'!");
        }
        
        private void CmdEndMatch(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_ADMIN))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length == 0)
            {
                SendReply(player, "Usage: /endmatch <matchid>");
                return;
            }
            
            if (!ulong.TryParse(args[0], out ulong matchId))
            {
                SendReply(player, "Invalid match ID!");
                return;
            }
            
            if (!activeMatches.ContainsKey(matchId))
            {
                SendReply(player, "Match not found!");
                return;
            }
            
            var match = activeMatches[matchId];
            EndMatch(match, "Admin ended match");
            SendReply(player, $"Match {matchId} ended!");
        }
        
        private void CmdShowStats(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_USE))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            var data = GetPlayerData(player.userID);
            
            SendReply(player, "=== CS2 STATS ===");
            SendReply(player, $"Kills: {data.Kills}");
            SendReply(player, $"Deaths: {data.Deaths}");
            SendReply(player, $"Assists: {data.Assists}");
            SendReply(player, $"K/D Ratio: {(data.Deaths > 0 ? (float)data.Kills / data.Deaths : data.Kills):F2}");
            
            if (data.CurrentMatchId != 0)
            {
                SendReply(player, $"Current Match: {data.CurrentMatchId}");
                SendReply(player, $"Team: {data.CurrentTeam}");
                SendReply(player, $"Team Damage: {data.TeamDamageDealt:F0}/{config.MaxTeamDamage}");
            }
        }
        
