        #region Update Methods
        
        private void UpdateMatches()
        {
            foreach (var match in activeMatches.Values.ToList())
            {
                if (match.State != MatchState.InProgress) continue;
                
                // Update bomb beeping and defuse progress
                if (match.PlantedBomb != null)
                {
                    UpdateBombStatus(match);
                }
                
                // Check for disconnected players
                CheckForDisconnectedPlayers(match);
            }
        }
        
        private void UpdateBombStatus(Match match)
        {
            if (match.PlantedBomb == null) return;
            
            float timeLeft = config.BombTimer - (Time.time - match.PlantedBomb.PlantTime);
            
            if (timeLeft <= 0f)
            {
                ExplodeBomb(match);
                return;
            }
            
            // Update defuse progress
            if (match.PlantedBomb.IsBeingDefused)
            {
                var defuser = BasePlayer.FindByID(match.PlantedBomb.DefuserId);
                if (defuser == null || defuser.IsDead())
                {
                    // Defuser disconnected or died
                    match.PlantedBomb.IsBeingDefused = false;
                    match.PlantedBomb.DefuserId = 0;
                    
                    var data = GetPlayerData(match.PlantedBomb.DefuserId);
                    data.IsDefusing = false;
                    data.DefuseTimer?.Destroy();
                }
                else
                {
                    // Check if defuser is still in range
                    float distance = Vector3.Distance(defuser.transform.position, match.PlantedBomb.Position);
                    if (distance > 2f)
                    {
                        StopDefuse(defuser, match);
                    }
                }
            }
        }
        
        private void CheckForDisconnectedPlayers(Match match)
        {
            var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers).ToList();
            var connectedPlayers = allPlayers.Where(id => BasePlayer.FindByID(id) != null).ToList();
            
            if (connectedPlayers.Count < allPlayers.Count / 2)
            {
                // Too many disconnections, end match
                EndMatch(match, "Too many player disconnections");
            }
        }
        
