        #region Enhanced Features - Economy System
        
        public class EconomySystem
        {
            public int StartingMoney { get; set; } = 800;
            public int MaxMoney { get; set; } = 16000;
            public int RoundLossBonusBase { get; set; } = 1400;
            public int RoundLossBonusMax { get; set; } = 3400;
            public int KillReward { get; set; } = 300;
            public int BombPlantReward { get; set; } = 300;
            public int BombDefuseReward { get; set; } = 300;
            public int RoundWinReward { get; set; } = 3250;
        }
        
        private EconomySystem economy = new EconomySystem();
        
        private void HandleEconomyRoundEnd(Match match, Team winner)
        {
            // Award money based on round outcome
            foreach (var playerId in match.TerroristPlayers)
            {
                var data = GetPlayerData(playerId);
                if (winner == Team.Terrorist)
                {
                    data.Money += economy.RoundWinReward;
                    data.ConsecutiveLosses = 0;
                }
                else
                {
                    int lossBonus = Math.Min(economy.RoundLossBonusBase + (data.ConsecutiveLosses * 500), economy.RoundLossBonusMax);
                    data.Money += lossBonus;
                    data.ConsecutiveLosses++;
                }
                data.Money = Math.Min(data.Money, economy.MaxMoney);
            }
            
            foreach (var playerId in match.CounterTerroristPlayers)
            {
                var data = GetPlayerData(playerId);
                if (winner == Team.CounterTerrorist)
                {
                    data.Money += economy.RoundWinReward;
                    data.ConsecutiveLosses = 0;
                }
                else
                {
                    int lossBonus = Math.Min(economy.RoundLossBonusBase + (data.ConsecutiveLosses * 500), economy.RoundLossBonusMax);
                    data.Money += lossBonus;
                    data.ConsecutiveLosses++;
                }
                data.Money = Math.Min(data.Money, economy.MaxMoney);
            }
        }
        
        private void AwardKillMoney(BasePlayer killer, BasePlayer victim)
        {
            var killerData = GetPlayerData(killer.userID);
            killerData.Money += economy.KillReward;
            killerData.Money = Math.Min(killerData.Money, economy.MaxMoney);
            
            SendReply(killer, $"+${economy.KillReward} (Kill reward)");
        }
        
