        private Dictionary<string, List<WeaponSkin>> weaponSkins = new Dictionary<string, List<WeaponSkin>>();
        
        private void InitializeWeaponSkins()
        {
            weaponSkins["rifle.ak"] = new List<WeaponSkin>
            {
                new WeaponSkin { SkinName = "Redline", WeaponType = "rifle.ak", SkinId = 1001, Rarity = "Classified", Price = 2500, Description = "A sleek red design" },
                new WeaponSkin { SkinName = "Vulcan", WeaponType = "rifle.ak", SkinId = 1002, Rarity = "Covert", Price = 5000, Description = "Futuristic orange pattern" },
                new WeaponSkin { SkinName = "Fire Serpent", WeaponType = "rifle.ak", SkinId = 1003, Rarity = "Covert", Price = 8000, Description = "Legendary dragon design" }
            };
            
            weaponSkins["rifle.lr300"] = new List<WeaponSkin>
            {
                new WeaponSkin { SkinName = "Asiimov", WeaponType = "rifle.lr300", SkinId = 2001, Rarity = "Covert", Price = 4500, Description = "White and orange sci-fi" },
                new WeaponSkin { SkinName = "Howl", WeaponType = "rifle.lr300", SkinId = 2002, Rarity = "Contraband", Price = 12000, Description = "Rare wolf design" },
                new WeaponSkin { SkinName = "Dragon King", WeaponType = "rifle.lr300", SkinId = 2003, Rarity = "Covert", Price = 6000, Description = "Majestic dragon artwork" }
            };
        }
        
        private void ApplyWeaponSkin(BasePlayer player, Item weapon, ulong skinId)
        {
            if (weapon?.info == null) return;
            
            // In a real implementation, you'd modify the weapon's skin here
            // This is a simplified version that adds a name tag
            weapon.name = GetSkinDisplayName(weapon.info.shortname, skinId);
            weapon.MarkDirty();
            
            SendReply(player, $"Applied skin: {weapon.name}");
        }
        
        private string GetSkinDisplayName(string weaponType, ulong skinId)
        {
            if (weaponSkins.ContainsKey(weaponType))
            {
                var skin = weaponSkins[weaponType].FirstOrDefault(s => s.SkinId == skinId);
                if (skin != null)
                {
                    return $"{weaponType} | {skin.SkinName}";
                }
            }
            return weaponType;
        }
        
