        #region Enhanced Features - Killstreak System
        
        public enum KillstreakType
        {
            DoubleKill = 2,
            TripleKill = 3,
            Quadrakill = 4,
            Pentakill = 5,
            Ace = 5 // Same as pentakill but when eliminating entire enemy team
        }
        
        private Dictionary<ulong, KillstreakData> killstreaks = new Dictionary<ulong, KillstreakData>();
        
        public class KillstreakData
        {
            public int CurrentStreak { get; set; } = 0;
            public int RoundKills { get; set; } = 0;
            public float LastKillTime { get; set; } = 0f;
            public int BestStreak { get; set; } = 0;
            public List<KillstreakType> RoundStreaks { get; set; } = new List<KillstreakType>();
        }
        
        private void HandleKillstreak(BasePlayer killer, BasePlayer victim, Match match)
        {
            if (!killstreaks.ContainsKey(killer.userID))
            {
                killstreaks[killer.userID] = new KillstreakData();
            }
            
            var streakData = killstreaks[killer.userID];
            streakData.CurrentStreak++;
            streakData.RoundKills++;
            streakData.LastKillTime = Time.time;
            
            if (streakData.CurrentStreak > streakData.BestStreak)
            {
                streakData.BestStreak = streakData.CurrentStreak;
            }
            
            // Check for multi-kill streaks (within 10 seconds)
            if (streakData.RoundKills >= 2)
            {
                var killstreakType = (KillstreakType)streakData.RoundKills;
                if (Enum.IsDefined(typeof(KillstreakType), killstreakType))
                {
                    AnnounceKillstreak(killer, killstreakType, match);
                    streakData.RoundStreaks.Add(killstreakType);
                    
                    // Award bonus money for killstreaks
                    var killerData = GetPlayerData(killer.userID);
                    int bonus = streakData.RoundKills * 100;
                    killerData.Money += bonus;
                    SendReply(killer, $"+${bonus} (Killstreak bonus!)");
                }
            }
            
            // Check for ace (killing entire enemy team)
            if (IsAce(killer, match))
            {
                AnnounceAce(killer, match);
                var killerData = GetPlayerData(killer.userID);
                killerData.Money += 1000;
                SendReply(killer, "+$1000 (ACE BONUS!)");
            }
        }
        
        private void AnnounceKillstreak(BasePlayer killer, KillstreakType type, Match match)
        {
            string message = $"{killer.displayName} got a {type.ToString().ToUpper()}!";
            
            var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
            foreach (var playerId in allPlayers)
            {
                var player = BasePlayer.FindByID(playerId);
                if (player != null)
                {
                    SendReply(player, message);
                    // In real implementation, play sound effect here
                    CreateKillstreakEffect(player, type);
                }
            }
        }
        
        private void AnnounceAce(BasePlayer killer, Match match)
        {
            string message = $"🔥 {killer.displayName} GOT AN ACE! 🔥";
            
            var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
            foreach (var playerId in allPlayers)
            {
                var player = BasePlayer.FindByID(playerId);
                if (player != null)
                {
                    SendReply(player, message);
                    CreateAceEffect(player);
                }
            }
        }
        
        private bool IsAce(BasePlayer killer, Match match)
        {
            var killerData = GetPlayerData(killer.userID);
            var enemyTeam = killerData.CurrentTeam == Team.Terrorist ? match.CounterTerroristPlayers : match.TerroristPlayers;
            
            // Check if all enemy players are dead
            foreach (var enemyId in enemyTeam)
            {
                var enemy = BasePlayer.FindByID(enemyId);
                if (enemy != null && !enemy.IsDead())
                {
                    return false;
                }
            }
            
            return killstreaks.ContainsKey(killer.userID) && killstreaks[killer.userID].RoundKills >= enemyTeam.Count;
        }
        
        private void ResetRoundKillstreaks(Match match)
        {
            var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
            foreach (var playerId in allPlayers)
            {
                if (killstreaks.ContainsKey(playerId))
                {
                    killstreaks[playerId].RoundKills = 0;
                    killstreaks[playerId].RoundStreaks.Clear();
                }
            }
        }
        
