        #region Spectator System
        
        private void CmdSpectate(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_USE))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            var data = GetPlayerData(player.userID);
            
            if (data.CurrentMatchId == 0)
            {
                SendReply(player, "You must be in a match to spectate!");
                return;
            }
            
            if (!data.IsSpectating)
            {
                SendReply(player, "You must be dead to spectate!");
                return;
            }
            
            if (args.Length > 0)
            {
                // Spectate specific player
                var targetPlayer = BasePlayer.Find(args[0]);
                if (targetPlayer != null)
                {
                    StartSpectating(player, targetPlayer.userID);
                }
                else
                {
                    SendReply(player, "Player not found!");
                }
            }
            else
            {
                // Start spectating first available teammate
                StartSpectatingTeammate(player);
            }
        }
        
        private void CmdSpectateNext(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_USE))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            var data = GetPlayerData(player.userID);
            if (!data.IsSpectating) return;
            
            SpectateNextPlayer(player);
        }
        
        private void CmdSpectatePrevious(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_USE))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            var data = GetPlayerData(player.userID);
            if (!data.IsSpectating) return;
            
            SpectatePreviousPlayer(player);
        }
        
        private void CmdToggleFreeCam(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_USE))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            var data = GetPlayerData(player.userID);
            
            if (!data.IsSpectating)
            {
                SendReply(player, "You must be spectating to use free cam!");
                return;
            }
            
            ToggleFreeCam(player);
        }
        
        private void StartSpectating(BasePlayer spectator, ulong targetId)
        {
            var data = GetPlayerData(spectator.userID);
            var targetPlayer = BasePlayer.FindByID(targetId);
            
            if (targetPlayer == null || targetPlayer.IsDead()) return;
            
            data.SpectatingPlayerId = targetId;
            data.IsInFreeCam = false;
            
            // Position spectator behind target
            var targetPos = targetPlayer.transform.position;
            var spectatorPos = targetPos + (targetPlayer.transform.forward * -3f) + Vector3.up * 2f;
            
            spectator.Teleport(spectatorPos);
            spectator.SetPlayerFlag(BasePlayer.PlayerFlags.Spectating, true);
            
            // Make spectator invisible and invulnerable
            spectator.SetPlayerFlag(BasePlayer.PlayerFlags.ThirdPersonViewmode, true);
            
            SendReply(spectator, $"Now spectating {targetPlayer.displayName}");
            
            CreateSpectatorUI(spectator, targetPlayer);
        }
        
        private void StartSpectatingTeammate(BasePlayer spectator)
        {
            var data = GetPlayerData(spectator.userID);
            
            if (data.CurrentMatchId == 0) return;
            if (!activeMatches.ContainsKey(data.CurrentMatchId)) return;
            
            var match = activeMatches[data.CurrentMatchId];
            var teammates = data.CurrentTeam == Team.Terrorist ? 
                match.TerroristPlayers : match.CounterTerroristPlayers;
            
            var aliveTeammates = teammates.Where(id => 
            {
                var player = BasePlayer.FindByID(id);
                return player != null && !player.IsDead() && id != spectator.userID;
            }).ToList();
            
            if (aliveTeammates.Count == 0)
            {
                SendReply(spectator, "No alive teammates to spectate!");
                ToggleFreeCam(spectator);
                return;
            }
            
            data.SpectatorIndex = 0;
            StartSpectating(spectator, aliveTeammates[0]);
        }
        
        private void SpectateNextPlayer(BasePlayer spectator)
        {
            var data = GetPlayerData(spectator.userID);
            
            if (data.CurrentMatchId == 0) return;
            if (!activeMatches.ContainsKey(data.CurrentMatchId)) return;
            
            var match = activeMatches[data.CurrentMatchId];
            var teammates = data.CurrentTeam == Team.Terrorist ? 
                match.TerroristPlayers : match.CounterTerroristPlayers;
            
            var aliveTeammates = teammates.Where(id => 
            {
                var player = BasePlayer.FindByID(id);
                return player != null && !player.IsDead() && id != spectator.userID;
            }).ToList();
            
            if (aliveTeammates.Count == 0)
            {
                ToggleFreeCam(spectator);
                return;
            }
            
            data.SpectatorIndex = (data.SpectatorIndex + 1) % aliveTeammates.Count;
            StartSpectating(spectator, aliveTeammates[data.SpectatorIndex]);
        }
        
        private void SpectatePreviousPlayer(BasePlayer spectator)
        {
            var data = GetPlayerData(spectator.userID);
            
            if (data.CurrentMatchId == 0) return;
            if (!activeMatches.ContainsKey(data.CurrentMatchId)) return;
            
            var match = activeMatches[data.CurrentMatchId];
            var teammates = data.CurrentTeam == Team.Terrorist ? 
                match.TerroristPlayers : match.CounterTerroristPlayers;
            
            var aliveTeammates = teammates.Where(id => 
            {
                var player = BasePlayer.FindByID(id);
                return player != null && !player.IsDead() && id != spectator.userID;
            }).ToList();
            
            if (aliveTeammates.Count == 0)
            {
                ToggleFreeCam(spectator);
                return;
            }
            
            data.SpectatorIndex = data.SpectatorIndex == 0 ? 
                aliveTeammates.Count - 1 : data.SpectatorIndex - 1;
            StartSpectating(spectator, aliveTeammates[data.SpectatorIndex]);
        }
        
        private void ToggleFreeCam(BasePlayer player)
        {
            var data = GetPlayerData(player.userID);
            
            data.IsInFreeCam = !data.IsInFreeCam;
            data.SpectatingPlayerId = 0;
            
            if (data.IsInFreeCam)
            {
                // Enable free cam mode
                player.SetPlayerFlag(BasePlayer.PlayerFlags.Spectating, true);
                player.SetPlayerFlag(BasePlayer.PlayerFlags.ThirdPersonViewmode, false);
                
                // Move to spectator area
                if (data.CurrentMatchId != 0 && activeMatches.ContainsKey(data.CurrentMatchId))
                {
                    var match = activeMatches[data.CurrentMatchId];
                    if (mapConfigurations.ContainsKey(match.MapName))
                    {
                        var mapConfig = mapConfigurations[match.MapName];
                        player.Teleport(mapConfig.SpectatorArea);
                    }
                }
                
                SendReply(player, "Free cam enabled! Use WASD to move, Mouse to look around");
                CreateFreeCamUI(player);
            }
            else
            {
                SendReply(player, "Free cam disabled");
                StartSpectatingTeammate(player);
            }
        }
        
        private void CreateSpectatorUI(BasePlayer spectator, BasePlayer target)
        {
            var targetData = GetPlayerData(target.userID);
            var spectatorData = GetPlayerData(spectator.userID);
            
            var container = new CuiElementContainer();
            
            // Spectator info panel
            container.Add(new CuiPanel
            {
                Image = { Color = "0 0 0 0.6" },
                RectTransform = { AnchorMin = "0.01 0.01", AnchorMax = "0.4 0.15" }
            }, "Overlay", "SpectatorUI");
            
            // Target player info
            string teamColor = targetData.CurrentTeam == Team.Terrorist ? "1 0.5 0 1" : "0 0.5 1 1";
            
            container.Add(new CuiLabel
            {
                Text = { Text = $"SPECTATING: {target.displayName}", FontSize = 14, Align = TextAnchor.MiddleLeft, Color = teamColor },
                RectTransform = { AnchorMin = "0.05 0.7", AnchorMax = "0.95 0.95" }
            }, "SpectatorUI");
            
            // Stats
            float kd = targetData.Deaths > 0 ? (float)targetData.Kills / targetData.Deaths : targetData.Kills;
            container.Add(new CuiLabel
            {
                Text = { Text = $"K/D: {targetData.Kills}/{targetData.Deaths} ({kd:F2})", FontSize = 12, Align = TextAnchor.MiddleLeft, Color = "1 1 1 1" },
                RectTransform = { AnchorMin = "0.05 0.45", AnchorMax = "0.95 0.7" }
            }, "SpectatorUI");
            
            // Health and armor
            container.Add(new CuiLabel
            {
                Text = { Text = $"HP: {target.health:F0} | Armor: {GetPlayerArmor(target):F0}", FontSize = 12, Align = TextAnchor.MiddleLeft, Color = "0.8 0.8 0.8 1" },
                RectTransform = { AnchorMin = "0.05 0.2", AnchorMax = "0.95 0.45" }
            }, "SpectatorUI");
            
            // Controls
            container.Add(new CuiLabel
            {
                Text = { Text = "MOUSE1: Next | MOUSE2: Previous | F: Free Cam", FontSize = 10, Align = TextAnchor.MiddleLeft, Color = "0.6 0.6 0.6 1" },
                RectTransform = { AnchorMin = "0.05 0.05", AnchorMax = "0.95 0.2" }
            }, "SpectatorUI");
            
            CuiHelper.DestroyUi(spectator, "SpectatorUI");
            CuiHelper.AddUi(spectator, container);
        }
        
        private void CreateFreeCamUI(BasePlayer player)
        {
            var data = GetPlayerData(player.userID);
            
            if (data.CurrentMatchId == 0) return;
            if (!activeMatches.ContainsKey(data.CurrentMatchId)) return;
            
            var match = activeMatches[data.CurrentMatchId];
            var container = new CuiElementContainer();
            
            // Free cam overlay
            container.Add(new CuiPanel
            {
                Image = { Color = "0 0 0 0.4" },
                RectTransform = { AnchorMin = "0.6 0.01", AnchorMax = "0.99 0.25" }
            }, "Overlay", "FreeCamUI");
            
            // Title
            container.Add(new CuiLabel
            {
                Text = { Text = "FREE CAM MODE", FontSize = 16, Align = TextAnchor.MiddleCenter, Color = "1 1 0 1" },
                RectTransform = { AnchorMin = "0 0.8", AnchorMax = "1 1" }
            }, "FreeCamUI");
            
            // Alive players list
            var teammates = data.CurrentTeam == Team.Terrorist ? 
                match.TerroristPlayers : match.CounterTerroristPlayers;
            var enemies = data.CurrentTeam == Team.Terrorist ? 
                match.CounterTerroristPlayers : match.TerroristPlayers;
            
            float yPos = 0.6f;
            
            // Teammates (highlighted in blue)
            foreach (var playerId in teammates)
            {
                var teammate = BasePlayer.FindByID(playerId);
                if (teammate != null && !teammate.IsDead() && teammate.userID != player.userID)
                {
                    var teammateData = GetPlayerData(playerId);
                    container.Add(new CuiLabel
                    {
                        Text = { Text = $"★ {teammate.displayName} ({teammateData.Kills}K)", FontSize = 12, Align = TextAnchor.MiddleLeft, Color = "0.3 0.7 1 1" },
                        RectTransform = { AnchorMin = $"0.05 {yPos - 0.1f}", AnchorMax = $"0.95 {yPos}" }
                    }, "FreeCamUI");
                    yPos -= 0.12f;
                }
            }
            
            // Enemies (normal color)
            foreach (var playerId in enemies)
            {
                var enemy = BasePlayer.FindByID(playerId);
                if (enemy != null && !enemy.IsDead())
                {
                    var enemyData = GetPlayerData(playerId);
                    container.Add(new CuiLabel
                    {
                        Text = { Text = $"• {enemy.displayName} ({enemyData.Kills}K)", FontSize = 12, Align = TextAnchor.MiddleLeft, Color = "0.8 0.8 0.8 1" },
                        RectTransform = { AnchorMin = $"0.05 {yPos - 0.1f}", AnchorMax = $"0.95 {yPos}" }
                    }, "FreeCamUI");
                    yPos -= 0.12f;
                }
            }
            
            CuiHelper.DestroyUi(player, "FreeCamUI");
            CuiHelper.AddUi(player, container);
        }
        
        private float GetPlayerArmor(BasePlayer player)
        {
            float armor = 0f;
            foreach (var item in player.inventory.containerWear.itemList)
            {
                if (item.info.shortname.Contains("metal"))
                {
                    armor += item.condition;
                }
            }
            return armor;
        }
        
