        #region Voice Chat System
        
        void OnPlayerVoice(BasePlayer player, Byte[] data)
        {
            if (player == null) return;
            
            var playerData = GetPlayerData(player.userID);
            playerData.IsTalking = true;
            playerData.LastTalkTime = Time.time;
            
            // Update voice UI for all players in the same match
            if (playerData.CurrentMatchId != 0 && activeMatches.ContainsKey(playerData.CurrentMatchId))
            {
                var match = activeMatches[playerData.CurrentMatchId];
                var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
                
                foreach (var playerId in allPlayers)
                {
                    var listener = BasePlayer.FindByID(playerId);
                    if (listener != null && listener != player)
                    {
                        UpdateVoiceChatUI(listener, player);
                    }
                }
            }
            
            // Auto-hide voice indicator after 0.5 seconds
            timer.Once(0.5f, () =>
            {
                if (playerData != null)
                {
                    playerData.IsTalking = false;
                    UpdateAllVoiceChatUI();
                }
            });
        }
        
        private void UpdateVoiceChatUI(BasePlayer listener, BasePlayer speaker)
        {
            var listenerData = GetPlayerData(listener.userID);
            var speakerData = GetPlayerData(speaker.userID);
            
            if (listenerData.CurrentMatchId != speakerData.CurrentMatchId) return;
            
            // Determine if same team
            bool sameTeam = listenerData.CurrentTeam == speakerData.CurrentTeam;
            string teamColor = sameTeam ? "0.2 0.8 0.2 0.9" : "0.8 0.2 0.2 0.9"; // Green for team, red for enemy
            string textColor = "1 1 1 1";
            
            var container = new CuiElementContainer();
            
            // Voice chat panel
            container.Add(new CuiPanel
            {
                Image = { Color = teamColor },
                RectTransform = { AnchorMin = "0.01 0.2", AnchorMax = "0.35 0.35" }
            }, "Overlay", "VoiceChatUI");
            
            // Player avatar background (simulated)
            container.Add(new CuiPanel
            {
                Image = { Color = "0.1 0.1 0.1 1" },
                RectTransform = { AnchorMin = "0.02 0.1", AnchorMax = "0.25 0.9" }
            }, "VoiceChatUI", "AvatarBG");
            
            // Player name
            container.Add(new CuiLabel
            {
                Text = { Text = speaker.displayName, FontSize = 14, Align = TextAnchor.MiddleLeft, Color = textColor },
                RectTransform = { AnchorMin = "0.28 0.6", AnchorMax = "0.98 0.9" }
            }, "VoiceChatUI");
            
            // Player stats
            float kd = speakerData.Deaths > 0 ? (float)speakerData.Kills / speakerData.Deaths : speakerData.Kills;
            container.Add(new CuiLabel
            {
                Text = { Text = $"K/D: {speakerData.Kills}/{speakerData.Deaths} ({kd:F1})", FontSize = 12, Align = TextAnchor.MiddleLeft, Color = textColor },
                RectTransform = { AnchorMin = "0.28 0.35", AnchorMax = "0.98 0.6" }
            }, "VoiceChatUI");
            
            // Round stats
            container.Add(new CuiLabel
            {
                Text = { Text = $"Round: {speakerData.RoundKills}K", FontSize = 10, Align = TextAnchor.MiddleLeft, Color = "0.9 0.9 0.9 1" },
                RectTransform = { AnchorMin = "0.28 0.1", AnchorMax = "0.98 0.35" }
            }, "VoiceChatUI");
            
            // Team indicator
            string teamText = sameTeam ? "TEAM" : "ENEMY";
            container.Add(new CuiLabel
            {
                Text = { Text = teamText, FontSize = 10, Align = TextAnchor.MiddleRight, Color = textColor },
                RectTransform = { AnchorMin = "0.7 0.1", AnchorMax = "0.98 0.35" }
            }, "VoiceChatUI");
            
            // Microphone icon (simulated with text)
            container.Add(new CuiLabel
            {
                Text = { Text = "🎤", FontSize = 16, Align = TextAnchor.MiddleCenter, Color = textColor },
                RectTransform = { AnchorMin = "0.02 0.1", AnchorMax = "0.25 0.9" }
            }, "AvatarBG");
            
            CuiHelper.DestroyUi(listener, "VoiceChatUI");
            CuiHelper.AddUi(listener, container);
            
            // Auto-hide after 2 seconds
            timer.Once(2f, () => CuiHelper.DestroyUi(listener, "VoiceChatUI"));
        }
        
        private void UpdateAllVoiceChatUI()
        {
            foreach (var match in activeMatches.Values)
            {
                if (match.State != MatchState.InProgress) continue;
                
                var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
                
                foreach (var playerId in allPlayers)
                {
                    var player = BasePlayer.FindByID(playerId);
                    if (player != null)
                    {
                        var data = GetPlayerData(playerId);
                        if (!data.IsTalking)
                        {
                            CuiHelper.DestroyUi(player, "VoiceChatUI");
                        }
                    }
                }
            }
        }
        
