        #region Voting System Implementation
        
        private void CmdVoteKick(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_USE))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length == 0)
            {
                SendReply(player, "Usage: /votekick <playername>");
                return;
            }
            
            var data = GetPlayerData(player.userID);
            if (data.CurrentMatchId == 0)
            {
                SendReply(player, "You must be in a match to vote!");
                return;
            }
            
            var targetPlayer = BasePlayer.Find(args[0]);
            if (targetPlayer == null)
            {
                SendReply(player, "Player not found!");
                return;
            }
            
            StartVote(data.CurrentMatchId, VoteType.Kick, targetPlayer.UserIDString, player.userID);
        }
        
        private void CmdVoteSurrender(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_USE))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            var data = GetPlayerData(player.userID);
            if (data.CurrentMatchId == 0)
            {
                SendReply(player, "You must be in a match to vote!");
                return;
            }
            
            StartVote(data.CurrentMatchId, VoteType.Surrender, "", player.userID);
        }
        
        private void CmdVoteYes(BasePlayer player, string command, string[] args)
        {
            CastVote(player, true);
        }
        
        private void CmdVoteNo(BasePlayer player, string command, string[] args)
        {
            CastVote(player, false);
        }
        
        private void StartVote(ulong matchId, VoteType type, string target, ulong initiatorId)
        {
            if (activeVotes.ContainsKey(matchId))
            {
                var initiator = BasePlayer.FindByID(initiatorId);
                if (initiator != null)
                {
                    SendReply(initiator, "A vote is already in progress!");
                }
                return;
            }
            
            var vote = new Vote
            {
                MatchId = matchId,
                Type = type,
                Target = target,
                InitiatorId = initiatorId,
                StartTime = Time.time
            };
            
            activeVotes[matchId] = vote;
            
            // Notify all players in the match
            if (activeMatches.ContainsKey(matchId))
            {
                var match = activeMatches[matchId];
                var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
                
                string voteMessage = GetVoteMessage(type, target);
                
                foreach (var playerId in allPlayers)
                {
                    var player = BasePlayer.FindByID(playerId);
                    if (player != null)
                    {
                        SendReply(player, voteMessage);
                        SendReply(player, "Type /yes or /no to vote! (30 seconds)");
                        CreateVoteUI(player, vote);
                    }
                }
            }
            
            // Auto-end vote after duration
            timer.Once(vote.Duration, () => EndVote(matchId));
        }
        
        private void CastVote(BasePlayer player, bool isYes)
        {
            var data = GetPlayerData(player.userID);
            if (data.CurrentMatchId == 0 || !activeVotes.ContainsKey(data.CurrentMatchId))
            {
                SendReply(player, "No active vote!");
                return;
            }
            
            var vote = activeVotes[data.CurrentMatchId];
            
            // Remove previous vote if exists
            vote.YesVotes.Remove(player.userID);
            vote.NoVotes.Remove(player.userID);
            
            // Add new vote
            if (isYes)
            {
                vote.YesVotes.Add(player.userID);
                SendReply(player, "You voted YES");
            }
            else
            {
                vote.NoVotes.Add(player.userID);
                SendReply(player, "You voted NO");
            }
            
            // Check if vote should end early
            CheckVoteResult(data.CurrentMatchId);
        }
        
        private void CheckVoteResult(ulong matchId)
        {
            if (!activeVotes.ContainsKey(matchId) || !activeMatches.ContainsKey(matchId))
                return;
            
            var vote = activeVotes[matchId];
            var match = activeMatches[matchId];
            
            int totalPlayers = match.TerroristPlayers.Count + match.CounterTerroristPlayers.Count;
            int requiredVotes = Mathf.CeilToInt(totalPlayers * 0.6f); // 60% majority
            
            if (vote.YesVotes.Count >= requiredVotes)
            {
                ExecuteVote(vote, true);
                EndVote(matchId);
            }
            else if (vote.NoVotes.Count > totalPlayers - requiredVotes)
            {
                ExecuteVote(vote, false);
                EndVote(matchId);
            }
        }
        
        private void ExecuteVote(Vote vote, bool passed)
        {
            if (!activeMatches.ContainsKey(vote.MatchId)) return;
            
            var match = activeMatches[vote.MatchId];
            var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
            
            string resultMessage = passed ? "Vote PASSED!" : "Vote FAILED!";
            
            foreach (var playerId in allPlayers)
            {
                var player = BasePlayer.FindByID(playerId);
                if (player != null)
                {
                    SendReply(player, resultMessage);
                    CuiHelper.DestroyUi(player, "VoteUI");
                }
            }
            
            if (passed)
            {
                switch (vote.Type)
                {
                    case VoteType.Kick:
                        if (ulong.TryParse(vote.Target, out ulong targetId))
                        {
                            var targetPlayer = BasePlayer.FindByID(targetId);
                            if (targetPlayer != null)
                            {
                                KickPlayerFromMatch(targetPlayer, "Voted out by team");
                            }
                        }
                        break;
                    case VoteType.Surrender:
                        EndMatch(match, "Team surrendered");
                        break;
                    case VoteType.Restart:
                        RestartMatch(match);
                        break;
                }
            }
        }
        
        private void EndVote(ulong matchId)
        {
            if (activeVotes.ContainsKey(matchId))
            {
                activeVotes.Remove(matchId);
                
                // Remove vote UI from all players
                if (activeMatches.ContainsKey(matchId))
                {
                    var match = activeMatches[matchId];
                    var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
                    
                    foreach (var playerId in allPlayers)
                    {
                        var player = BasePlayer.FindByID(playerId);
                        if (player != null)
                        {
                            CuiHelper.DestroyUi(player, "VoteUI");
                        }
                    }
                }
            }
        }
        
        private string GetVoteMessage(VoteType type, string target)
        {
            switch (type)
            {
                case VoteType.Kick:
                    var targetPlayer = BasePlayer.Find(target);
                    return $"Vote to kick {(targetPlayer?.displayName ?? "Unknown")}";
                case VoteType.Surrender:
                    return "Vote to surrender the match";
                case VoteType.Restart:
                    return "Vote to restart the match";
                default:
                    return "Vote in progress";
            }
        }
        
        private void CreateVoteUI(BasePlayer player, Vote vote)
        {
            var container = new CuiElementContainer();
            
            // Vote panel
            container.Add(new CuiPanel
            {
                Image = { Color = "0 0 0 0.8" },
                RectTransform = { AnchorMin = "0.3 0.4", AnchorMax = "0.7 0.6" }
            }, "Overlay", "VoteUI");
            
            // Vote message
            string message = GetVoteMessage(vote.Type, vote.Target);
            container.Add(new CuiLabel
            {
                Text = { Text = message, FontSize = 16, Align = TextAnchor.MiddleCenter, Color = "1 1 1 1" },
                RectTransform = { AnchorMin = "0 0.6", AnchorMax = "1 0.9" }
            }, "VoteUI");
            
            // Vote counts
            container.Add(new CuiLabel
            {
                Text = { Text = $"YES: {vote.YesVotes.Count} | NO: {vote.NoVotes.Count}", FontSize = 14, Align = TextAnchor.MiddleCenter, Color = "0.8 0.8 0.8 1" },
                RectTransform = { AnchorMin = "0 0.4", AnchorMax = "1 0.6" }
            }, "VoteUI");
            
            // Yes button
            container.Add(new CuiButton
            {
                Button = { Command = "cs2.voteyes", Color = "0.2 0.8 0.2 1" },
                RectTransform = { AnchorMin = "0.1 0.1", AnchorMax = "0.4 0.4" },
                Text = { Text = "YES (F1)", FontSize = 12, Align = TextAnchor.MiddleCenter, Color = "1 1 1 1" }
            }, "VoteUI");
            
            // No button
            container.Add(new CuiButton
            {
                Button = { Command = "cs2.voteno", Color = "0.8 0.2 0.2 1" },
                RectTransform = { AnchorMin = "0.6 0.1", AnchorMax = "0.9 0.4" },
                Text = { Text = "NO (F2)", FontSize = 12, Align = TextAnchor.MiddleCenter, Color = "1 1 1 1" }
            }, "VoteUI");
            
            CuiHelper.AddUi(player, container);
        }
        
