        private Dictionary<ulong, EconomyData> playerEconomy = new Dictionary<ulong, EconomyData>();
        private Dictionary<string, WeaponData> weaponPrices = new Dictionary<string, WeaponData>();
        
        private void InitializeEconomy()
        {
            // Initialize weapon prices
            weaponPrices["pistol.m92"] = new WeaponData { Name = "M92 Beretta", ShortName = "pistol.m92", Price = 500, Category = WeaponCategory.Pistol };
            weaponPrices["pistol.python"] = new WeaponData { Name = "Python Revolver", ShortName = "pistol.python", Price = 600, Category = WeaponCategory.Pistol };
            weaponPrices["rifle.ak"] = new WeaponData { Name = "AK47", ShortName = "rifle.ak", Price = 2700, Category = WeaponCategory.Rifle };
            weaponPrices["rifle.lr300"] = new WeaponData { Name = "LR-300", ShortName = "rifle.lr300", Price = 3100, Category = WeaponCategory.Rifle };
            weaponPrices["rifle.bolt"] = new WeaponData { Name = "Bolt Action", ShortName = "rifle.bolt", Price = 4750, Category = WeaponCategory.Sniper };
            weaponPrices["smg.thompson"] = new WeaponData { Name = "Thompson", ShortName = "smg.thompson", Price = 1250, Category = WeaponCategory.SMG };
            weaponPrices["shotgun.pump"] = new WeaponData { Name = "Pump Shotgun", ShortName = "shotgun.pump", Price = 1200, Category = WeaponCategory.Shotgun };
            weaponPrices["metal.plate.torso"] = new WeaponData { Name = "Metal Chest Plate", ShortName = "metal.plate.torso", Price = 650, Category = WeaponCategory.Equipment };
            weaponPrices["metal.facemask"] = new WeaponData { Name = "Metal Facemask", ShortName = "metal.facemask", Price = 350, Category = WeaponCategory.Equipment };
            weaponPrices["grenade.f1"] = new WeaponData { Name = "F1 Grenade", ShortName = "grenade.f1", Price = 300, Category = WeaponCategory.Grenade };
            weaponPrices["grenade.flashbang"] = new WeaponData { Name = "Flashbang", ShortName = "grenade.flashbang", Price = 200, Category = WeaponCategory.Grenade };
            weaponPrices["grenade.smoke"] = new WeaponData { Name = "Smoke Grenade", ShortName = "grenade.smoke", Price = 300, Category = WeaponCategory.Grenade };
        }
        
        private EconomyData GetPlayerEconomy(ulong playerId)
        {
            if (!playerEconomy.ContainsKey(playerId))
            {
                playerEconomy[playerId] = new EconomyData();
            }
            return playerEconomy[playerId];
        }
        
        private void UpdatePlayerMoney(ulong playerId, int amount, string reason)
        {
            var economy = GetPlayerEconomy(playerId);
            economy.Money += amount;
            economy.RoundMoney += amount;
            
            var player = BasePlayer.FindByID(playerId);
            if (player != null && amount != 0)
            {
                string sign = amount > 0 ? "+" : "";
                SendReply(player, $"{sign}${amount} ({reason}) | Total: ${economy.Money}");
            }
        }
        
        private bool CanAffordItem(ulong playerId, string itemShortname)
        {
            if (!weaponPrices.ContainsKey(itemShortname)) return false;
            
            var economy = GetPlayerEconomy(playerId);
            var weapon = weaponPrices[itemShortname];
            
            return economy.Money >= weapon.Price;
        }
        
        private void PurchaseItem(BasePlayer player, string itemShortname)
        {
            if (!weaponPrices.ContainsKey(itemShortname))
            {
                SendReply(player, "Item not available for purchase!");
                return;
            }
            
            var economy = GetPlayerEconomy(player.userID);
            var weapon = weaponPrices[itemShortname];
            
            if (economy.Money < weapon.Price)
            {
                SendReply(player, $"Not enough money! Need ${weapon.Price}, have ${economy.Money}");
                return;
            }
            
            // Process purchase
            economy.Money -= weapon.Price;
            economy.PurchaseHistory.Add($"{weapon.Name} - ${weapon.Price}");
            
            // Remove existing items of same category
            RemoveItemsByCategory(player, weapon.Category);
            
            // Give the item
            GiveItem(player, itemShortname, 1);
            SendReply(player, $"Purchased {weapon.Name} for ${weapon.Price} | Remaining: ${economy.Money}");
        }
        
        #endregion
        
        #region Warmup System Implementation
        
        private Dictionary<ulong, WarmupData> matchWarmups = new Dictionary<ulong, WarmupData>();
        
        private void StartWarmup(Match match)
        {
            var warmup = new WarmupData
            {
                IsActive = true,
                StartTime = Time.time,
                Duration = 300f // 5 minutes
            };
            
            matchWarmups[match.MatchId] = warmup;
            
            // Notify players
            var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
            foreach (var playerId in allPlayers)
            {
                var player = BasePlayer.FindByID(playerId);
                if (player != null)
                {
                    SendReply(player, "Warmup started! Infinite ammo enabled.");
                    GiveWarmupLoadout(player);
                }
            }
            
            // Auto-end warmup
            timer.Once(warmup.Duration, () => EndWarmup(match));
        }
        
        private void EndWarmup(Match match)
        {
            if (matchWarmups.ContainsKey(match.MatchId))
            {
                matchWarmups.Remove(match.MatchId);
                
                var allPlayers = match.TerroristPlayers.Concat(match.CounterTerroristPlayers);
                foreach (var playerId in allPlayers)
                {
                    var player = BasePlayer.FindByID(playerId);
                    if (player != null)
                    {
                        SendReply(player, "Warmup ended! Match starting...");
                        ResetPlayerInventory(player);
                    }
                }
                
                // Start actual match
                StartRound(match);
            }
        }
        
        private void GiveWarmupLoadout(BasePlayer player)
        {
            ResetPlayerInventory(player);
            
            // Give all weapons for warmup
            GiveItem(player, "rifle.ak", 1);
            GiveItem(player, "rifle.lr300", 1);
            GiveItem(player, "pistol.m92", 1);
            GiveItem(player, "metal.plate.torso", 1);
            GiveItem(player, "metal.facemask", 1);
            GiveItem(player, "ammo.rifle", 300);
            GiveItem(player, "ammo.pistol", 200);
            GiveItem(player, "grenade.f1", 5);
            GiveItem(player, "grenade.flashbang", 3);
        }
        
