        #region Leaderboard System Implementation
        
        private Dictionary<ulong, LeaderboardEntry> leaderboard = new Dictionary<ulong, LeaderboardEntry>();
        
        private void UpdateLeaderboard(ulong playerId, bool won, int kills, int deaths)
        {
            if (!leaderboard.ContainsKey(playerId))
            {
                var player = BasePlayer.FindByID(playerId);
                leaderboard[playerId] = new LeaderboardEntry
                {
                    PlayerId = playerId,
                    PlayerName = player?.displayName ?? "Unknown"
                };
            }
            
            var entry = leaderboard[playerId];
            
            if (won)
            {
                entry.Wins++;
                entry.Rating += 25;
            }
            else
            {
                entry.Losses++;
                entry.Rating -= 20;
            }
            
            entry.TotalKills += kills;
            entry.TotalDeaths += deaths;
            entry.KDRatio = entry.TotalDeaths > 0 ? (float)entry.TotalKills / entry.TotalDeaths : entry.TotalKills;
            entry.LastPlayed = DateTime.Now;
            
            // Ensure rating doesn't go below 0
            if (entry.Rating < 0) entry.Rating = 0;
        }
        
        private void CmdLeaderboard(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_USE))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            ShowLeaderboard(player);
        }
        
        private void ShowLeaderboard(BasePlayer player)
        {
            var topPlayers = leaderboard.Values
                .OrderByDescending(x => x.Rating)
                .Take(10)
                .ToList();
            
            var container = new CuiElementContainer();
            
            // Main panel
            container.Add(new CuiPanel
            {
                Image = { Color = "0 0 0 0.9" },
                RectTransform = { AnchorMin = "0.2 0.1", AnchorMax = "0.8 0.9" }
            }, "Overlay", "LeaderboardUI");
            
            // Title
            container.Add(new CuiLabel
            {
                Text = { Text = "LEADERBOARD", FontSize = 20, Align = TextAnchor.MiddleCenter, Color = "1 1 0 1" },
                RectTransform = { AnchorMin = "0 0.9", AnchorMax = "1 1" }
            }, "LeaderboardUI");
            
            // Headers
            container.Add(new CuiLabel
            {
                Text = { Text = "RANK  PLAYER  RATING  W/L  K/D", FontSize = 14, Align = TextAnchor.MiddleLeft, Color = "0.8 0.8 0.8 1" },
                RectTransform = { AnchorMin = "0.05 0.8", AnchorMax = "0.95 0.9" }
            }, "LeaderboardUI");
            
            // Player entries
            float yPos = 0.75f;
            for (int i = 0; i < topPlayers.Count; i++)
            {
                var entry = topPlayers[i];
                string playerText = $"{i + 1}.  {entry.PlayerName}  {entry.Rating}  {entry.Wins}/{entry.Losses}  {entry.KDRatio:F2}";
                
                string color = entry.PlayerId == player.userID ? "1 1 0 1" : "1 1 1 1";
                
                container.Add(new CuiLabel
                {
                    Text = { Text = playerText, FontSize = 12, Align = TextAnchor.MiddleLeft, Color = color },
                    RectTransform = { AnchorMin = $"0.05 {yPos - 0.06f}", AnchorMax = $"0.95 {yPos}" }
                }, "LeaderboardUI");
                
                yPos -= 0.07f;
            }
            
            // Close button
            container.Add(new CuiButton
            {
                Button = { Command = "cs2.closeleaderboard", Color = "0.8 0.2 0.2 1" },
                RectTransform = { AnchorMin = "0.4 0.05", AnchorMax = "0.6 0.15" },
                Text = { Text = "CLOSE", FontSize = 12, Align = TextAnchor.MiddleCenter, Color = "1 1 1 1" }
            }, "LeaderboardUI");
            
            CuiHelper.AddUi(player, container);
        }
        
