        private void CheckAchievements(ulong playerId, AchievementType type, int value = 1)
        {
            if (!playerAchievements.ContainsKey(playerId))
            {
                playerAchievements[playerId] = new List<PlayerAchievement>();
            }
            
            var playerAchs = playerAchievements[playerId];
            
            foreach (var achievement in achievements.Values.Where(a => a.Type == type))
            {
                var playerAch = playerAchs.FirstOrDefault(pa => pa.AchievementId == achievement.Id);
                if (playerAch == null)
                {
                    playerAch = new PlayerAchievement { AchievementId = achievement.Id };
                    playerAchs.Add(playerAch);
                }
                
                if (!playerAch.IsCompleted)
                {
                    playerAch.Progress += value;
                    
                    if (playerAch.Progress >= achievement.RequiredValue)
                    {
                        playerAch.IsCompleted = true;
                        playerAch.CompletedDate = DateTime.Now;
                        
                        var player = BasePlayer.FindByID(playerId);
                        if (player != null)
                        {
                            SendReply(player, $"🏆 ACHIEVEMENT UNLOCKED: {achievement.Name}!");
                            SendReply(player, $"📝 {achievement.Description}");
                            ShowAchievementNotification(player, achievement);
                        }
                    }
                }
            }
        }
        
