        #region Anti-Cheat System Implementation
        
        private Dictionary<ulong, AntiCheatData> antiCheatData = new Dictionary<ulong, AntiCheatData>();
        
        private void MonitorPlayer(BasePlayer player)
        {
            if (!antiCheatData.ContainsKey(player.userID))
            {
                antiCheatData[player.userID] = new AntiCheatData { PlayerId = player.userID };
            }
            
            var data = antiCheatData[player.userID];
            
            // Track position for speed hacking detection
            data.RecentPositions.Add(player.transform.position);
            if (data.RecentPositions.Count > 10)
            {
                data.RecentPositions.RemoveAt(0);
            }
            
            // Check for suspicious movement
            if (data.RecentPositions.Count >= 2)
            {
                var lastPos = data.RecentPositions[data.RecentPositions.Count - 2];
                var currentPos = player.transform.position;
                var distance = Vector3.Distance(lastPos, currentPos);
                
                if (distance > 50f) // Suspicious teleportation
                {
                    data.SuspiciousActions++;
                    LogSuspiciousActivity(player, $"Suspicious movement: {distance}m in one frame");
                }
            }
            
            data.LastMoveTime = Time.time;
        }
        
        private void CheckHeadshotRatio(BasePlayer attacker, BasePlayer victim, HitInfo info)
        {
            if (!antiCheatData.ContainsKey(attacker.userID))
            {
                antiCheatData[attacker.userID] = new AntiCheatData { PlayerId = attacker.userID };
            }
            
            var data = antiCheatData[attacker.userID];
            
            // Check if it was a headshot
            if (info.isHeadshot)
            {
                data.ConsecutiveHeadshots++;
                
                if (data.ConsecutiveHeadshots >= 5) // 5 consecutive headshots is suspicious
                {
                    data.SuspiciousActions++;
                    LogSuspiciousActivity(attacker, $"Consecutive headshots: {data.ConsecutiveHeadshots}");
                }
            }
            else
            {
                data.ConsecutiveHeadshots = 0;
            }
            
            // Auto-kick if too many suspicious actions
            if (data.SuspiciousActions >= 10)
            {
                KickPlayerForCheating(attacker);
            }
        }
        
        private void LogSuspiciousActivity(BasePlayer player, string reason)
        {
            PrintWarning($"[ANTI-CHEAT] Suspicious activity from {player.displayName} ({player.UserIDString}): {reason}");
            
            // Notify admins
            foreach (var admin in BasePlayer.activePlayerList.Where(p => permission.UserHasPermission(p.UserIDString, PERMISSION_ADMIN)))
            {
                SendReply(admin, $"⚠️ [AC] {player.displayName}: {reason}");
            }
        }
        
        private void KickPlayerForCheating(BasePlayer player)
        {
            PrintWarning($"[ANTI-CHEAT] Kicking {player.displayName} for suspicious activity");
            
            // Remove from match if in one
            var data = GetPlayerData(player.userID);
            if (data.CurrentMatchId != 0)
            {
                KickPlayerFromMatch(player, "Anti-cheat violation");
            }
            
            // Kick from server
            player.Kick("Anti-cheat violation detected");
        }
        
