        #region Tournament System Implementation
        
        private Dictionary<string, Tournament> tournaments = new Dictionary<string, Tournament>();
        
        private void CmdCreateTournament(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_ADMIN))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length < 2)
            {
                SendReply(player, "Usage: /createtournament <name> <maxplayers> [prize]");
                return;
            }
            
            string tournamentName = args[0];
            if (!int.TryParse(args[1], out int maxPlayers))
            {
                SendReply(player, "Invalid max players number!");
                return;
            }
            
            string prize = args.Length > 2 ? string.Join(" ", args.Skip(2)) : "Glory";
            
            var tournament = new Tournament
            {
                Name = tournamentName,
                MaxParticipants = maxPlayers,
                Prize = prize,
                StartTime = DateTime.Now.AddMinutes(10) // Start in 10 minutes
            };
            
            tournaments[tournamentName] = tournament;
            
            PrintToChat($"🏆 Tournament '{tournamentName}' created! Prize: {prize}");
            PrintToChat($"📝 Registration open! Use /jointournament {tournamentName}");
            SendReply(player, $"Tournament '{tournamentName}' created successfully!");
        }
        
        private void CmdJoinTournament(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_USE))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length == 0)
            {
                SendReply(player, "Usage: /jointournament <name>");
                return;
            }
            
            string tournamentName = args[0];
            if (!tournaments.ContainsKey(tournamentName))
            {
                SendReply(player, "Tournament not found!");
                return;
            }
            
            var tournament = tournaments[tournamentName];
            
            if (tournament.State != TournamentState.Registration)
            {
                SendReply(player, "Tournament registration is closed!");
                return;
            }
            
            if (tournament.Participants.Contains(player.userID))
            {
                SendReply(player, "You are already registered for this tournament!");
                return;
            }
            
            if (tournament.Participants.Count >= tournament.MaxParticipants)
            {
                SendReply(player, "Tournament is full!");
                return;
            }
            
            tournament.Participants.Add(player.userID);
            SendReply(player, $"Successfully registered for tournament '{tournamentName}'!");
            PrintToChat($"🎮 {player.displayName} joined tournament '{tournamentName}' ({tournament.Participants.Count}/{tournament.MaxParticipants})");
            
            // Auto-start if full
            if (tournament.Participants.Count >= tournament.MaxParticipants)
            {
                StartTournament(tournamentName);
            }
        }
        
        private void StartTournament(string tournamentName)
        {
            if (!tournaments.ContainsKey(tournamentName)) return;
            
            var tournament = tournaments[tournamentName];
            tournament.State = TournamentState.InProgress;
            
            PrintToChat($"🏆 Tournament '{tournamentName}' is starting!");
            
            // Create brackets and start matches
            CreateTournamentBrackets(tournament);
        }
        
        private void CreateTournamentBrackets(Tournament tournament)
        {
            var participants = tournament.Participants.ToList();
            
            // Shuffle participants
            for (int i = 0; i < participants.Count; i++)
            {
                var temp = participants[i];
                var randomIndex = UnityEngine.Random.Range(i, participants.Count);
                participants[i] = participants[randomIndex];
                participants[randomIndex] = temp;
            }
            
            // Create first round matches
            int matchId = 1;
            for (int i = 0; i < participants.Count; i += 2)
            {
                if (i + 1 < participants.Count)
                {
                    // Create a match between participants[i] and participants[i+1]
                    // This would integrate with the existing match system
                    PrintToChat($"🥊 Match {matchId}: {BasePlayer.FindByID(participants[i])?.displayName} vs {BasePlayer.FindByID(participants[i + 1])?.displayName}");
                    matchId++;
                }
            }
        }
        
