        #region Map Generation Commands
        
        private void CmdGenerateMap(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_ADMIN))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length < 2)
            {
                SendReply(player, "Usage: /generatemap <template> <mapname>");
                SendReply(player, "Available templates: dust2_classic, mirage_compact, inferno_mini, cache_small, custom");
                return;
            }
            
            string template = args[0];
            string mapName = args[1];
            
            Vector3 playerPos = player.transform.position;
            
            SendReply(player, $"Generating map '{mapName}' using template '{template}'...");
            
            timer.Once(1f, () => GenerateMapFromTemplate(player, template, mapName, playerPos));
        }
        
        private void CmdClearMap(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_ADMIN))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length == 0)
            {
                SendReply(player, "Usage: /clearmap <mapname> [radius]");
                return;
            }
            
            string mapName = args[0];
            float radius = args.Length > 1 ? float.Parse(args[1]) : 100f;
            
            Vector3 playerPos = player.transform.position;
            
            SendReply(player, $"Clearing map area around you (radius: {radius}m)...");
            ClearMapArea(playerPos, radius);
            SendReply(player, "Map area cleared!");
        }
        
        private void GenerateMapFromTemplate(BasePlayer player, string templateName, string mapName, Vector3 center)
        {
            MapGenerator generator = new MapGenerator
            {
                MapName = mapName,
                MapCenter = center,
                MapSize = 150f
            };
            
            switch (templateName.ToLower())
            {
                case "dust2_classic":
                    GenerateDust2Classic(generator);
                    break;
                case "mirage_compact":
                    GenerateMirageCompact(generator);
                    break;
                case "inferno_mini":
                    GenerateInfernoMini(generator);
                    break;
                case "cache_small":
                    GenerateCacheSmall(generator);
                    break;
                case "custom":
                    GenerateCustomMap(generator);
                    break;
                default:
                    SendReply(player, "Unknown template! Using custom template.");
                    GenerateCustomMap(generator);
                    break;
            }
            
            // Execute the generation
            ExecuteMapGeneration(generator, player);
        }
        
        private void GenerateDust2Classic(MapGenerator generator)
        {
            Vector3 center = generator.MapCenter;
            
            // Create main structures
            // Long A corridor
            CreateLongCorridor(generator, center + new Vector3(-50, 0, 30), new Vector3(0, 0, 0), 60f, 8f);
            
            // Short A
            CreateShortPath(generator, center + new Vector3(-30, 0, 50), new Vector3(0, 45, 0), 30f);
            
            // B Tunnels
            CreateTunnelSystem(generator, center + new Vector3(40, 0, -20), new Vector3(0, 0, 0), 40f);
            
            // Middle area
            CreateMiddleArea(generator, center, 25f);
            
            // Bomb sites
            generator.BombSites.Add(new BombSiteLayout
            {
                SiteName = "A",
                Center = center + new Vector3(-60, 0, 60),
                Radius = 8f
            });
            
            generator.BombSites.Add(new BombSiteLayout
            {
                SiteName = "B",
                Center = center + new Vector3(50, 0, -40),
                Radius = 8f
            });
            
            // Spawn points
            for (int i = 0; i < 5; i++)
            {
                generator.TerroristSpawns.Add(center + new Vector3(70 + i * 3, 0, -60));
                generator.CounterTerroristSpawns.Add(center + new Vector3(-80 + i * 3, 0, 80));
            }
        }
        
        private void GenerateMirageCompact(MapGenerator generator)
        {
            Vector3 center = generator.MapCenter;
            
            // A Site structures
            CreateBombSiteStructure(generator, center + new Vector3(-40, 0, 40), "A", 12f);
            
            // B Site structures  
            CreateBombSiteStructure(generator, center + new Vector3(40, 0, -30), "B", 10f);
            
            // Connector areas
            CreateConnectorPath(generator, center + new Vector3(-20, 0, 0), center + new Vector3(20, 0, 0));
            
            // Palace area (A site approach)
            CreatePalaceArea(generator, center + new Vector3(-60, 0, 20));
            
            // Apartments (B site approach)
            CreateApartmentArea(generator, center + new Vector3(60, 0, -10));
            
            // Spawn areas
            for (int i = 0; i < 5; i++)
            {
                generator.TerroristSpawns.Add(center + new Vector3(80 + i * 2, 0, -50));
                generator.CounterTerroristSpawns.Add(center + new Vector3(-80 + i * 2, 0, 60));
            }
        }
        
        private void GenerateInfernoMini(MapGenerator generator)
        {
            Vector3 center = generator.MapCenter;
            
            // Apartment building
            CreateApartmentBuilding(generator, center + new Vector3(-50, 0, 30));
            
            // Bombsite A (apartments)
            generator.BombSites.Add(new BombSiteLayout
            {
                SiteName = "A",
                Center = center + new Vector3(-45, 0, 35),
                Radius = 6f
            });
            
            // Bombsite B (site)
            CreateBombSiteB_Inferno(generator, center + new Vector3(40, 0, -25));
            
            // Banana (B approach)
            CreateBananaPath(generator, center + new Vector3(20, 0, -40), center + new Vector3(40, 0, -25));
            
            // Middle area with fountain
            CreateFountainArea(generator, center);
            
            // Spawn points
            for (int i = 0; i < 5; i++)
            {
                generator.TerroristSpawns.Add(center + new Vector3(70 + i * 2, 0, -60));
                generator.CounterTerroristSpawns.Add(center + new Vector3(-70 + i * 2, 0, 60));
            }
        }
        
        private void GenerateCacheSmall(MapGenerator generator)
        {
            Vector3 center = generator.MapCenter;
            
            // Main building structure
            CreateMainBuilding(generator, center);
            
            // A Site (outside)
            CreateOutdoorBombSite(generator, center + new Vector3(-50, 0, 30), "A");
            
            // B Site (inside building)
            CreateIndoorBombSite(generator, center + new Vector3(30, 0, -20), "B");
            
            // Warehouse area
            CreateWarehouseArea(generator, center + new Vector3(0, 0, -40));
            
            // Quad area (middle)
            CreateQuadArea(generator, center + new Vector3(-20, 0, 0));
            
            // Spawn points
            for (int i = 0; i < 5; i++)
            {
                generator.TerroristSpawns.Add(center + new Vector3(60 + i * 2, 0, -50));
                generator.CounterTerroristSpawns.Add(center + new Vector3(-60 + i * 2, 0, 50));
            }
        }
        
        private void GenerateCustomMap(MapGenerator generator)
        {
            Vector3 center = generator.MapCenter;
            
            // Create a balanced 3-lane map
            // Lane 1 (A site)
            CreateLane(generator, center + new Vector3(-40, 0, 0), center + new Vector3(-40, 0, 50), 8f);
            
            // Lane 2 (Middle)
            CreateLane(generator, center + new Vector3(0, 0, -20), center + new Vector3(0, 0, 40), 12f);
            
            // Lane 3 (B site)
            CreateLane(generator, center + new Vector3(40, 0, 0), center + new Vector3(40, 0, -50), 8f);
            
            // Connect lanes
            CreateConnectorPath(generator, center + new Vector3(-40, 0, 25), center + new Vector3(0, 0, 25));
            CreateConnectorPath(generator, center + new Vector3(0, 0, 10), center + new Vector3(40, 0, 10));
            
            // Bomb sites
            generator.BombSites.Add(new BombSiteLayout
            {
                SiteName = "A",
                Center = center + new Vector3(-40, 0, 50),
                Radius = 7f
            });
            
            generator.BombSites.Add(new BombSiteLayout
            {
                SiteName = "B", 
                Center = center + new Vector3(40, 0, -50),
                Radius = 7f
            });
            
            // Spawn points
            for (int i = 0; i < 5; i++)
            {
                generator.TerroristSpawns.Add(center + new Vector3(-10 + i * 5, 0, -60));
                generator.CounterTerroristSpawns.Add(center + new Vector3(-10 + i * 5, 0, 70));
            }
        }
        
