        #region Map Generation Helpers
        
        private void CreateLongCorridor(MapGenerator generator, Vector3 start, Vector3 rotation, float length, float width)
        {
            // Create walls along the corridor
            for (float i = 0; i < length; i += 4f)
            {
                // Left wall
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/building core/wall/wall.prefab",
                    Position = start + new Vector3(i, 0, -width/2),
                    Rotation = rotation,
                    Type = StructureType.Wall
                });
                
                // Right wall
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/building core/wall/wall.prefab",
                    Position = start + new Vector3(i, 0, width/2),
                    Rotation = rotation,
                    Type = StructureType.Wall
                });
            }
            
            // Add cover boxes
            for (float i = 10f; i < length - 10f; i += 20f)
            {
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/deployable/large wood storage/box.large.wood.prefab",
                    Position = start + new Vector3(i, 0, UnityEngine.Random.Range(-2f, 2f)),
                    Rotation = new Vector3(0, UnityEngine.Random.Range(0, 360), 0),
                    Type = StructureType.Cover
                });
            }
        }
        
        private void CreateShortPath(MapGenerator generator, Vector3 start, Vector3 rotation, float length)
        {
            // Create a shorter, more direct path with elevated positions
            for (float i = 0; i < length; i += 6f)
            {
                // Platform
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/building core/floor/floor.prefab",
                    Position = start + new Vector3(i, 1f, 0),
                    Rotation = rotation,
                    Type = StructureType.Platform
                });
                
                // Railing
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/building core/wall/wall.low.prefab",
                    Position = start + new Vector3(i, 1f, 2f),
                    Rotation = rotation,
                    Type = StructureType.Barrier
                });
            }
        }
        
        private void CreateTunnelSystem(MapGenerator generator, Vector3 start, Vector3 rotation, float length)
        {
            // Underground tunnel system
            for (float i = 0; i < length; i += 4f)
            {
                // Tunnel walls
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/building core/wall/wall.prefab",
                    Position = start + new Vector3(i, -2f, -3f),
                    Rotation = rotation,
                    Type = StructureType.Wall
                });
                
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/building core/wall/wall.prefab",
                    Position = start + new Vector3(i, -2f, 3f),
                    Rotation = rotation,
                    Type = StructureType.Wall
                });
                
                // Tunnel ceiling
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/building core/roof/roof.prefab",
                    Position = start + new Vector3(i, 1f, 0),
                    Rotation = rotation,
                    Type = StructureType.Roof
                });
            }
        }
        
        private void CreateMiddleArea(MapGenerator generator, Vector3 center, float radius)
        {
            // Central area with multiple levels and cover
            
            // Main platform
            generator.Structures.Add(new GeneratedStructure
            {
                PrefabName = "assets/prefabs/building core/floor/floor.triangle.prefab",
                Position = center,
                Rotation = Vector3.zero,
                Scale = new Vector3(2f, 1f, 2f),
                Type = StructureType.Platform
            });
            
            // Cover positions around the center
            for (int i = 0; i < 8; i++)
            {
                float angle = i * 45f * Mathf.Deg2Rad;
                Vector3 pos = center + new Vector3(Mathf.Cos(angle) * radius, 0, Mathf.Sin(angle) * radius);
                
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/deployable/barricades/barricade.concrete.prefab",
                    Position = pos,
                    Rotation = new Vector3(0, i * 45f, 0),
                    Type = StructureType.Cover
                });
            }
        }
        
        private void CreateBombSiteStructure(MapGenerator generator, Vector3 center, string siteName, float size)
        {
            // Create bomb site area with cover and plant positions
            
            // Main site platform
            generator.Structures.Add(new GeneratedStructure
            {
                PrefabName = "assets/prefabs/building core/floor/floor.prefab",
                Position = center,
                Rotation = Vector3.zero,
                Scale = new Vector3(size/4f, 1f, size/4f),
                Type = StructureType.Platform
            });
            
            // Plant boxes
            for (int i = 0; i < 3; i++)
            {
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/deployable/large wood storage/box.large.wood.prefab",
                    Position = center + new Vector3(UnityEngine.Random.Range(-size/2, size/2), 0, UnityEngine.Random.Range(-size/2, size/2)),
                    Rotation = new Vector3(0, UnityEngine.Random.Range(0, 360), 0),
                    Type = StructureType.Cover
                });
            }
            
            // Add to bomb sites
            generator.BombSites.Add(new BombSiteLayout
            {
                SiteName = siteName,
                Center = center,
                Radius = size/2f
            });
        }
        
        private void CreateConnectorPath(MapGenerator generator, Vector3 start, Vector3 end)
        {
            Vector3 direction = (end - start).normalized;
            float distance = Vector3.Distance(start, end);
            
            for (float i = 0; i < distance; i += 8f)
            {
                Vector3 pos = start + direction * i;
                
                // Add some cover along the path
                if (i > 5f && i < distance - 5f)
                {
                    generator.Structures.Add(new GeneratedStructure
                    {
                        PrefabName = "assets/prefabs/deployable/barricades/barricade.wood.prefab",
                        Position = pos + new Vector3(UnityEngine.Random.Range(-2f, 2f), 0, UnityEngine.Random.Range(-2f, 2f)),
                        Rotation = new Vector3(0, UnityEngine.Random.Range(0, 360), 0),
                        Type = StructureType.Cover
                    });
                }
            }
        }
        
        private void CreatePalaceArea(MapGenerator generator, Vector3 center)
        {
            // Multi-level structure for A site approach
            
            // Ground floor
            generator.Structures.Add(new GeneratedStructure
            {
                PrefabName = "assets/prefabs/building core/floor/floor.prefab",
                Position = center,
                Rotation = Vector3.zero,
                Scale = new Vector3(3f, 1f, 2f),
                Type = StructureType.Floor
            });
            
            // Upper level
            generator.Structures.Add(new GeneratedStructure
            {
                PrefabName = "assets/prefabs/building core/floor/floor.prefab",
                Position = center + new Vector3(0, 3f, 0),
                Rotation = Vector3.zero,
                Scale = new Vector3(2f, 1f, 1.5f),
                Type = StructureType.Platform
            });
            
            // Stairs
            generator.Structures.Add(new GeneratedStructure
            {
                PrefabName = "assets/prefabs/building core/stairs.l/stairs.l.prefab",
                Position = center + new Vector3(-4f, 0, 2f),
                Rotation = new Vector3(0, 90, 0),
                Type = StructureType.Stairs
            });
        }
        
        private void CreateApartmentArea(MapGenerator generator, Vector3 center)
        {
            // Apartment-style building for B site approach
            
            // Main building structure
            for (int floor = 0; floor < 3; floor++)
            {
                for (int x = 0; x < 3; x++)
                {
                    for (int z = 0; z < 2; z++)
                    {
                        generator.Structures.Add(new GeneratedStructure
                        {
                            PrefabName = "assets/prefabs/building core/floor/floor.prefab",
                            Position = center + new Vector3(x * 4f, floor * 3f, z * 4f),
                            Rotation = Vector3.zero,
                            Type = StructureType.Floor
                        });
                    }
                }
            }
            
            // Windows
            for (int floor = 1; floor < 3; floor++)
            {
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/building core/wall/wall.window.prefab",
                    Position = center + new Vector3(6f, floor * 3f, 4f),
                    Rotation = new Vector3(0, 90, 0),
                    Type = StructureType.Window
                });
            }
        }
        
        private void CreateLane(MapGenerator generator, Vector3 start, Vector3 end, float width)
        {
            Vector3 direction = (end - start).normalized;
            float distance = Vector3.Distance(start, end);
            
            // Create lane boundaries
            for (float i = 0; i <= distance; i += 4f)
            {
                Vector3 pos = start + direction * i;
                Vector3 perpendicular = new Vector3(-direction.z, 0, direction.x);
                
                // Left boundary
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/building core/wall/wall.low.prefab",
                    Position = pos + perpendicular * width/2,
                    Rotation = Vector3.zero,
                    Type = StructureType.Barrier
                });
                
                // Right boundary
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/building core/wall/wall.low.prefab",
                    Position = pos - perpendicular * width/2,
                    Rotation = Vector3.zero,
                    Type = StructureType.Barrier
                });
            }
        }
        
        private void ExecuteMapGeneration(MapGenerator generator, BasePlayer player)
        {
            int structuresCreated = 0;
            
            // Create all structures
            foreach (var structure in generator.Structures)
            {
                CreateStructure(structure);
                structuresCreated++;
                
                // Batch creation to prevent lag
                if (structuresCreated % 10 == 0)
                {
                    timer.Once(0.1f, () => { }); // Small delay
                }
            }
            
            // Register bomb sites
            foreach (var bombSite in generator.BombSites)
            {
                string siteName = $"{generator.MapName}_{bombSite.SiteName}";
                bombSites[siteName] = new BombSite
                {
                    Name = siteName,
                    MapName = generator.MapName,
                    MinBounds = bombSite.Center - Vector3.one * bombSite.Radius,
                    MaxBounds = bombSite.Center + Vector3.one * bombSite.Radius,
                    IsActive = true
                };
            }
            
            // Register map configuration
            mapConfigurations[generator.MapName] = new MapConfiguration
            {
                MapName = generator.MapName,
                TerroristSpawns = generator.TerroristSpawns,
                CounterTerroristSpawns = generator.CounterTerroristSpawns,
                SpectatorArea = generator.MapCenter + Vector3.up * 20f,
                BombSiteNames = generator.BombSites.Select(bs => $"{generator.MapName}_{bs.SiteName}").ToList()
            };
            
            SaveData();
            
            SendReply(player, $"Map '{generator.MapName}' generated successfully!");
            SendReply(player, $"Created {structuresCreated} structures, {generator.BombSites.Count} bomb sites");
            SendReply(player, $"T Spawns: {generator.TerroristSpawns.Count}, CT Spawns: {generator.CounterTerroristSpawns.Count}");
        }
        
        private void CreateStructure(GeneratedStructure structure)
        {
            // In a real implementation, this would spawn the actual prefab
            // For now, we'll simulate with basic Rust entities
            
            BaseEntity entity = null;
            
            switch (structure.Type)
            {
                case StructureType.Wall:
                    entity = GameManager.server.CreateEntity("assets/prefabs/building core/wall/wall.prefab", structure.Position);
                    break;
                case StructureType.Floor:
                    entity = GameManager.server.CreateEntity("assets/prefabs/building core/floor/floor.prefab", structure.Position);
                    break;
                case StructureType.Cover:
                    entity = GameManager.server.CreateEntity("assets/prefabs/deployable/large wood storage/box.large.wood.prefab", structure.Position);
                    break;
                case StructureType.Platform:
                    entity = GameManager.server.CreateEntity("assets/prefabs/building core/floor/floor.triangle.prefab", structure.Position);
                    break;
                default:
                    entity = GameManager.server.CreateEntity(structure.PrefabName, structure.Position);
                    break;
            }
            
            if (entity != null)
            {
                entity.transform.rotation = Quaternion.Euler(structure.Rotation);
                entity.transform.localScale = structure.Scale;
                entity.Spawn();
            }
        }
        
        private void ClearMapArea(Vector3 center, float radius)
        {
            var entities = new List<BaseEntity>();
            Vis.Entities(center, radius, entities);
            
            foreach (var entity in entities)
            {
                if (entity != null && !entity.IsDestroyed && !(entity is BasePlayer))
                {
                    entity.Kill();
                }
            }
        }
        
