        #region Additional Map Commands
        
        private void CmdListMaps(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_USE))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            SendReply(player, "=== AVAILABLE MAPS ===");
            
            if (mapConfigurations.Count == 0)
            {
                SendReply(player, "No maps configured yet!");
                return;
            }
            
            foreach (var map in mapConfigurations.Values)
            {
                string bombSites = string.Join(", ", map.BombSiteNames);
                SendReply(player, $"• {map.MapName} - Bomb Sites: {bombSites}");
                SendReply(player, $"  T Spawns: {map.TerroristSpawns.Count}, CT Spawns: {map.CounterTerroristSpawns.Count}");
            }
            
            SendReply(player, "=== MAP GENERATION TEMPLATES ===");
            SendReply(player, "• dust2_classic - Classic Dust2 layout");
            SendReply(player, "• mirage_compact - Compact Mirage layout");
            SendReply(player, "• inferno_mini - Mini Inferno layout");
            SendReply(player, "• cache_small - Small Cache layout");
            SendReply(player, "• custom - Balanced 3-lane map");
        }
        
        private void CmdTeleportToMap(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_USE))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length == 0)
            {
                SendReply(player, "Usage: /teleportmap <mapname>");
                return;
            }
            
            string mapName = args[0];
            
            if (!mapConfigurations.ContainsKey(mapName))
            {
                SendReply(player, $"Map '{mapName}' not found!");
                return;
            }
            
            var mapConfig = mapConfigurations[mapName];
            Vector3 teleportPos = mapConfig.SpectatorArea;
            
            if (mapConfig.TerroristSpawns.Count > 0)
            {
                teleportPos = mapConfig.TerroristSpawns[0] + Vector3.up * 10f;
            }
            
            TeleportPlayer(player, teleportPos);
            SendReply(player, $"Teleported to map '{mapName}'!");
        }
        
