        private void CreateAdvancedMapFeatures(MapGenerator generator)
        {
            // Add callouts for the generated map
            CreateMapCallouts(generator);
            
            // Add lighting
            CreateMapLighting(generator);
            
            // Add sound zones
            CreateSoundZones(generator);
            
            // Add interactive elements
            CreateInteractiveElements(generator);
        }
        
        private void CreateMapCallouts(MapGenerator generator)
        {
            // Create callouts for each bomb site
            foreach (var bombSite in generator.BombSites)
            {
                string calloutKey = $"{generator.MapName}_{bombSite.SiteName}_site";
                mapCallouts[calloutKey] = new MapCallout
                {
                    Name = $"{bombSite.SiteName} Site",
                    Position = bombSite.Center,
                    Radius = bombSite.Radius + 5f,
                    MapName = generator.MapName,
                    Description = $"Bomb site {bombSite.SiteName}"
                };
            }
            
            // Add spawn callouts
            if (generator.TerroristSpawns.Count > 0)
            {
                Vector3 tSpawnCenter = GetCenterPoint(generator.TerroristSpawns);
                mapCallouts[$"{generator.MapName}_t_spawn"] = new MapCallout
                {
                    Name = "T Spawn",
                    Position = tSpawnCenter,
                    Radius = 15f,
                    MapName = generator.MapName,
                    Description = "Terrorist spawn area"
                };
            }
            
            if (generator.CounterTerroristSpawns.Count > 0)
            {
                Vector3 ctSpawnCenter = GetCenterPoint(generator.CounterTerroristSpawns);
                mapCallouts[$"{generator.MapName}_ct_spawn"] = new MapCallout
                {
                    Name = "CT Spawn",
                    Position = ctSpawnCenter,
                    Radius = 15f,
                    MapName = generator.MapName,
                    Description = "Counter-Terrorist spawn area"
                };
            }
            
            // Add middle callout
            mapCallouts[$"{generator.MapName}_middle"] = new MapCallout
            {
                Name = "Middle",
                Position = generator.MapCenter,
                Radius = 20f,
                MapName = generator.MapName,
                Description = "Central area of the map"
            };
        }
        
        private Vector3 GetCenterPoint(List<Vector3> points)
        {
            if (points.Count == 0) return Vector3.zero;
            
            Vector3 sum = Vector3.zero;
            foreach (var point in points)
            {
                sum += point;
            }
            return sum / points.Count;
        }
        
        private void CreateMapLighting(MapGenerator generator)
        {
            // Add lighting to bomb sites
            foreach (var bombSite in generator.BombSites)
            {
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/deployable/lantern/lantern.deployed.prefab",
                    Position = bombSite.Center + Vector3.up * 4f,
                    Rotation = Vector3.zero,
                    Type = StructureType.Functional,
                    Properties = new Dictionary<string, object>
                    {
                        ["LightColor"] = bombSite.SiteName == "A" ? "blue" : "red",
                        ["Intensity"] = 2f
                    }
                });
            }
            
            // Add spawn area lighting
            if (generator.TerroristSpawns.Count > 0)
            {
                Vector3 tSpawnCenter = GetCenterPoint(generator.TerroristSpawns);
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/deployable/lantern/lantern.deployed.prefab",
                    Position = tSpawnCenter + Vector3.up * 5f,
                    Rotation = Vector3.zero,
                    Type = StructureType.Functional,
                    Properties = new Dictionary<string, object>
                    {
                        ["LightColor"] = "orange",
                        ["Intensity"] = 1.5f
                    }
                });
            }
            
            if (generator.CounterTerroristSpawns.Count > 0)
            {
                Vector3 ctSpawnCenter = GetCenterPoint(generator.CounterTerroristSpawns);
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/deployable/lantern/lantern.deployed.prefab",
                    Position = ctSpawnCenter + Vector3.up * 5f,
                    Rotation = Vector3.zero,
                    Type = StructureType.Functional,
                    Properties = new Dictionary<string, object>
                    {
                        ["LightColor"] = "blue",
                        ["Intensity"] = 1.5f
                    }
                });
            }
        }
        
        private void CreateSoundZones(MapGenerator generator)
        {
            // Add ambient sounds to different areas
            // This would be implemented with actual sound entities in a real plugin
            
            // Bomb site ambient sounds
            foreach (var bombSite in generator.BombSites)
            {
                // Add subtle beeping or electronic sounds near bomb sites
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/misc/radio/radio.prefab",
                    Position = bombSite.Center + new Vector3(3f, 1f, 3f),
                    Rotation = Vector3.zero,
                    Type = StructureType.Functional,
                    Properties = new Dictionary<string, object>
                    {
                        ["SoundType"] = "ambient_electronic",
                        ["Volume"] = 0.3f
                    }
                });
            }
        }
        
        private void CreateInteractiveElements(MapGenerator generator)
        {
            // Add interactive elements like doors, switches, etc.
            
            // Add doors between major areas
            Vector3 midPoint = (generator.MapCenter + generator.BombSites[0].Center) / 2f;
            generator.Structures.Add(new GeneratedStructure
            {
                PrefabName = "assets/prefabs/building core/door/door.hinged.metal.prefab",
                Position = midPoint,
                Rotation = Vector3.zero,
                Type = StructureType.Door,
                Properties = new Dictionary<string, object>
                {
                    ["IsLocked"] = false,
                    ["AutoClose"] = true,
                    ["CloseDelay"] = 5f
                }
            });
            
            // Add breakable windows
            foreach (var bombSite in generator.BombSites)
            {
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/building core/wall/wall.window.prefab",
                    Position = bombSite.Center + new Vector3(5f, 2f, 0),
                    Rotation = Vector3.zero,
                    Type = StructureType.Window,
                    Properties = new Dictionary<string, object>
                    {
                        ["IsBreakable"] = true,
                        ["Health"] = 50f
                    }
                });
            }
        }
        
