        #region Map Validation and Testing
        
        private void CmdValidateMap(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_ADMIN))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length == 0)
            {
                SendReply(player, "Usage: /validatemap <mapname>");
                return;
            }
            
            string mapName = args[0];
            
            if (!mapConfigurations.ContainsKey(mapName))
            {
                SendReply(player, $"Map '{mapName}' not found!");
                return;
            }
            
            var mapConfig = mapConfigurations[mapName];
            var issues = ValidateMapConfiguration(mapConfig);
            
            SendReply(player, $"=== MAP VALIDATION: {mapName} ===");
            
            if (issues.Count == 0)
            {
                SendReply(player, "✓ Map validation passed! No issues found.");
            }
            else
            {
                SendReply(player, $"✗ Found {issues.Count} issues:");
                foreach (var issue in issues)
                {
                    SendReply(player, $"  • {issue}");
                }
            }
        }
        
        private List<string> ValidateMapConfiguration(MapConfiguration mapConfig)
        {
            var issues = new List<string>();
            
            // Check spawn points
            if (mapConfig.TerroristSpawns.Count < 5)
            {
                issues.Add($"Insufficient Terrorist spawns: {mapConfig.TerroristSpawns.Count}/5 minimum");
            }
            
            if (mapConfig.CounterTerroristSpawns.Count < 5)
            {
                issues.Add($"Insufficient Counter-Terrorist spawns: {mapConfig.CounterTerroristSpawns.Count}/5 minimum");
            }
            
            // Check bomb sites
            if (mapConfig.BombSiteNames.Count < 2)
            {
                issues.Add($"Insufficient bomb sites: {mapConfig.BombSiteNames.Count}/2 minimum");
            }
            
            // Check spawn distances
            if (mapConfig.TerroristSpawns.Count > 0 && mapConfig.CounterTerroristSpawns.Count > 0)
            {
                float minDistance = GetMinimumSpawnDistance(mapConfig.TerroristSpawns, mapConfig.CounterTerroristSpawns);
                if (minDistance < 50f)
                {
                    issues.Add($"Spawn points too close: {minDistance:F1}m (minimum 50m recommended)");
                }
            }
            
            // Check bomb site accessibility
            foreach (var bombSiteName in mapConfig.BombSiteNames)
            {
                if (!bombSites.ContainsKey(bombSiteName))
                {
                    issues.Add($"Bomb site '{bombSiteName}' not properly configured");
                }
            }
            
            return issues;
        }
        
        private float GetMinimumSpawnDistance(List<Vector3> tSpawns, List<Vector3> ctSpawns)
        {
            float minDistance = float.MaxValue;
            
            foreach (var tSpawn in tSpawns)
            {
                foreach (var ctSpawn in ctSpawns)
                {
                    float distance = Vector3.Distance(tSpawn, ctSpawn);
                    if (distance < minDistance)
                    {
                        minDistance = distance;
                    }
                }
            }
            
            return minDistance;
        }
        
