        #region Ultra Detailed Implementation Methods
        
        private void GenerateDetailedRooms(UltraDetailedMapGenerator generator)
        {
            foreach (var building in generator.Buildings)
            {
                foreach (var floor in building.Floors)
                {
                    GenerateFloorRooms(building, floor, generator);
                }
            }
        }
        
        private void GenerateFloorRooms(DetailedBuilding building, Floor floor, UltraDetailedMapGenerator generator)
        {
            // Office rooms
            for (int x = 0; x < 8; x++)
            {
                for (int z = 0; z < 6; z++)
                {
                    var room = new DetailedRoom
                    {
                        RoomId = $"{building.BuildingId}_floor{floor.Level}_room{x}_{z}",
                        Name = DetermineRoomName(floor.Level, x, z),
                        Type = DetermineRoomType(floor.Level, x, z),
                        Function = RoomFunction.Commercial,
                        Center = building.Position + new Vector3(x * 5f - 17.5f, floor.Level * 3.5f + 1.75f, z * 4f - 10f),
                        Area = 20f,
                        Volume = 54f,
                        CeilingHeight = 2.7f
                    };
                    
                    // Generate room surfaces
                    GenerateRoomSurfaces(room);
                    
                    // Add lighting
                    GenerateRoomLighting(room);
                    
                    // Add furniture
                    GenerateRoomFurniture(room);
                    
                    // Add gameplay elements
                    GenerateRoomGameplayElements(room);
                    
                    building.Rooms.Add(room);
                    generator.Rooms.Add(room);
                }
            }
        }
        
        private void GenerateRoomSurfaces(DetailedRoom room)
        {
            // Floor
            room.Floor = new FloorSurface
            {
                Material = GetFloorMaterial(room.Type),
                Color = GetFloorColor(room.Type),
                Texture = GetFloorTexture(room.Type),
                Reflectivity = GetFloorReflectivity(room.Type),
                Friction = GetFloorFriction(room.Type),
                FootstepSound = GetFloorFootstepSound(room.Type)
            };
            
            // Walls
            for (int i = 0; i < 4; i++)
            {
                room.Walls.Add(new WallSurface
                {
                    WallId = $"{room.RoomId}_wall_{i}",
                    Material = GetWallMaterial(room.Type),
                    Color = GetWallColor(room.Type),
                    Texture = GetWallTexture(room.Type),
                    Finish = GetWallFinish(room.Type),
                    HasBaseboards = true,
                    HasCrownMolding = room.Type == RoomType.Office
                });
            }
            
            // Ceiling
            room.Ceiling = new CeilingSurface
            {
                Material = GetCeilingMaterial(room.Type),
                Color = Color.white,
                HasDropCeiling = room.Type == RoomType.Office,
                HasCeilingTiles = room.Type == RoomType.Office,
                TilePattern = room.Type == RoomType.Office ? "2x2_grid" : "none"
            };
        }
        
        private void GenerateRoomLighting(DetailedRoom room)
        {
            room.Lighting = new RoomLighting
            {
                AmbientLevel = GetAmbientLighting(room.Type),
                TaskLevel = GetTaskLighting(room.Type),
                AccentLevel = GetAccentLighting(room.Type),
                ColorTemperature = GetColorTemperature(room.Type),
                HasNaturalLight = HasWindows(room.Type),
                HasArtificialLight = true
            };
            
            // Add light fixtures based on room type
            switch (room.Type)
            {
                case RoomType.Office:
                    room.LightFixtures.Add(new LightFixture
                    {
                        Type = "fluorescent_panel",
                        Position = room.Center + Vector3.up * 2.5f,
                        Intensity = 800f,
                        ColorTemperature = 4000f,
                        CastsShadows = true,
                        IsControllable = true
                    });
                    break;
                    
                case RoomType.Bathroom:
                    room.LightFixtures.Add(new LightFixture
                    {
                        Type = "vanity_light",
                        Position = room.Center + new Vector3(0, 2f, 1.5f),
                        Intensity = 400f,
                        ColorTemperature = 3000f,
                        CastsShadows = false,
                        IsControllable = true
                    });
                    break;
                    
                case RoomType.Hallway:
                    for (int i = 0; i < 3; i++)
                    {
                        room.LightFixtures.Add(new LightFixture
                        {
                            Type = "recessed_downlight",
                            Position = room.Center + new Vector3(i * 2f - 2f, 2.5f, 0),
                            Intensity = 300f,
                            ColorTemperature = 3500f,
                            CastsShadows = true,
                            IsControllable = false
                        });
                    }
                    break;
            }
        }
        
        private void GenerateRoomFurniture(DetailedRoom room)
        {
            switch (room.Type)
            {
                case RoomType.Office:
                    GenerateOfficeFurniture(room);
                    break;
                case RoomType.Conference:
                    GenerateConferenceFurniture(room);
                    break;
                case RoomType.Bathroom:
                    GenerateBathroomFixtures(room);
                    break;
                case RoomType.Storage:
                    GenerateStorageFurniture(room);
                    break;
                case RoomType.Lobby:
                    GenerateLobbyFurniture(room);
                    break;
            }
        }
        
        private void GenerateOfficeFurniture(DetailedRoom room)
        {
            // Desk
            room.Furniture.Add(new FurnitureItem
            {
                ItemId = $"{room.RoomId}_desk",
                Type = "office_desk",
                Position = room.Center + new Vector3(1f, 0, 0.5f),
                Rotation = new Vector3(0, 180, 0),
                Dimensions = new Vector3(1.5f, 0.75f, 0.8f),
                Material = "wood_laminate",
                Color = new Color(0.6f, 0.4f, 0.2f),
                IsInteractable = true,
                HasDrawers = true,
                DrawerCount = 3,
                CanStoreItems = true,
                StorageCapacity = 20
            });
            
            // Office chair
            room.Furniture.Add(new FurnitureItem
            {
                ItemId = $"{room.RoomId}_chair",
                Type = "office_chair",
                Position = room.Center + new Vector3(1f, 0, -0.3f),
                Rotation = new Vector3(0, 0, 0),
                Dimensions = new Vector3(0.6f, 1.2f, 0.6f),
                Material = "fabric_mesh",
                Color = Color.black,
                IsInteractable = true,
                CanSitOn = true,
                IsAdjustable = true,
                HasWheels = true
            });
            
            // Filing cabinet
            room.Furniture.Add(new FurnitureItem
            {
                ItemId = $"{room.RoomId}_filing",
                Type = "filing_cabinet",
                Position = room.Center + new Vector3(-1.5f, 0, 1f),
                Rotation = new Vector3(0, 90, 0),
                Dimensions = new Vector3(0.4f, 1.3f, 0.6f),
                Material = "metal",
                Color = new Color(0.7f, 0.7f, 0.7f),
                IsInteractable = true,
                HasLock = true,
                CanStoreItems = true,
                StorageCapacity = 50
            });
            
            // Computer setup
            room.Equipment.Add(new Equipment
            {
                EquipmentId = $"{room.RoomId}_computer",
                Type = "desktop_computer",
                Position = room.Center + new Vector3(1.2f, 0.75f, 0.3f),
                IsElectronic = true,
                PowerConsumption = 150f,
                RequiresPower = true,
                IsInteractable = true,
                HasScreen = true,
                ScreenSize = 24f,
                IsNetworked = true
            });
        }
        
        private void GenerateRoomGameplayElements(DetailedRoom room)
        {
            // Cover points
            foreach (var furniture in room.Furniture)
            {
                if (furniture.Dimensions.y > 0.8f) // Tall enough for cover
                {
                    room.CoverPoints.Add(new CoverPoint
                    {
                        Position = furniture.Position,
                        CoverType = DetermineCoverType(furniture),
                        Height = furniture.Dimensions.y,
                        Width = furniture.Dimensions.x,
                        Protection = CalculateProtection(furniture),
                        CanCrouchBehind = furniture.Dimensions.y > 0.6f,
                        CanStandBehind = furniture.Dimensions.y > 1.5f,
                        CanLeanAround = true
                    });
                }
            }
            
            // Hiding spots
            if (room.Type == RoomType.Storage || room.Type == RoomType.Utility)
            {
                room.HidingSpots.Add(new HidingSpot
                {
                    Position = room.Center + new Vector3(-1.5f, 0, -1.5f),
                    HidingType = HidingType.Corner,
                    Visibility = 0.2f,
                    Accessibility = 0.8f,
                    RequiresCrouch = false,
                    MaxOccupants = 1
                });
            }
            
            // Vantage points
            if (room.Type == RoomType.Office && HasWindows(room.Type))
            {
                room.VantagePoints.Add(new VantagePoint
                {
                    Position = room.Center + new Vector3(2f, 0, 2f),
                    ViewDirection = Vector3.forward,
                    ViewAngle = 90f,
                    ViewDistance = 50f,
                    ElevationAdvantage = 0f,
                    ConcealmentLevel = 0.6f,
                    RequiresEquipment = false
                });
            }
        }
        
        private void GenerateInfrastructure(UltraDetailedMapGenerator generator)
        {
            // Electrical system
            generator.Electrical = new ElectricalSystem
            {
                MainPanel = new ElectricalPanel
                {
                    Position = generator.MapCenter + new Vector3(-15f, 0, -10f),
                    Voltage = 240f,
                    Amperage = 200f,
                    CircuitCount = 24,
                    HasBackupPower = true,
                    BackupType = "generator"
                }
            };
            
            // Generate electrical circuits for each building
            foreach (var building in generator.Buildings)
            {
                GenerateBuildingElectrical(building, generator.Electrical);
            }
            
            // Plumbing system
            generator.Plumbing = new PlumbingSystem
            {
                MainWaterLine = new WaterLine
                {
                    StartPosition = generator.MapCenter + new Vector3(-20f, -2f, 0),
                    EndPosition = generator.MapCenter + new Vector3(20f, -2f, 0),
                    Diameter = 6f,
                    Pressure = 60f,
                    Material = "copper"
                }
            };
            
            // Generate plumbing for each building
            foreach (var building in generator.Buildings)
            {
                GenerateBuildingPlumbing(building, generator.Plumbing);
            }
            
            // HVAC system
            generator.Ventilation = new VentilationSystem
            {
                MainUnit = new HVACUnit
                {
                    Position = generator.MapCenter + new Vector3(0, 25f, 0),
                    Capacity = 50000f, // BTU
                    AirFlowRate = 2000f, // CFM
                    HasHeating = true,
                    HasCooling = true,
                    HasFiltration = true,
                    FilterType = "HEPA"
                }
            };
        }
        
        private void GenerateAdvancedLighting(UltraDetailedMapGenerator generator)
        {
            // Exterior lighting
            GenerateExteriorLighting(generator);
            
            // Interior lighting (already generated per room)
            
            // Emergency lighting
            GenerateEmergencyLighting(generator);
            
            // Security lighting
            GenerateSecurityLighting(generator);
            
            // Decorative lighting
            GenerateDecorativeLighting(generator);
        }
        
        private void GenerateExteriorLighting(UltraDetailedMapGenerator generator)
        {
            // Street lights
            for (float x = -generator.MapSize/2; x <= generator.MapSize/2; x += 20f)
            {
                generator.Lighting.Add(new DetailedLighting
                {
                    LightId = $"street_light_{x}",
                    Type = LightType.Street,
                    Position = new Vector3(x, 6f, generator.MapCenter.z - 30f),
                    Color = new Color(1f, 0.9f, 0.7f),
                    Intensity = 2000f,
                    Range = 15f,
                    SpotAngle = 120f,
                    ShadowType = ShadowType.Hard,
                    ShadowStrength = 0.8f,
                    VisibilityRadius = 12f,
                    AffectsGameplay = true,
                    CanBeDestroyed = true,
                    Health = 100f,
                    HasSwitch = false,
                    WeatherResistance = WeatherResistance.High
                });
            }
            
            // Building exterior lights
            foreach (var building in generator.Buildings)
            {
                // Facade lighting
                for (int i = 0; i < 4; i++)
                {
                    generator.Lighting.Add(new DetailedLighting
                    {
                        LightId = $"{building.BuildingId}_facade_{i}",
                        Type = LightType.Flood,
                        Position = building.Position + new Vector3(
                            Mathf.Cos(i * 90f * Mathf.Deg2Rad) * (building.Dimensions.x/2 + 2f),
                            building.Dimensions.y * 0.8f,
                            Mathf.Sin(i * 90f * Mathf.Deg2Rad) * (building.Dimensions.z/2 + 2f)
                        ),
                        Color = Color.white,
                        Intensity = 1500f,
                        Range = 20f,
                        SpotAngle = 60f,
                        AffectsGameplay = true,
                        CanBeDestroyed = true,
                        Health = 75f
                    });
                }
            }
        }
        
        // Helper methods for room generation
        private string DetermineRoomName(int floor, int x, int z)
        {
            if (floor == 0)
            {
                if (x == 0 && z == 0) return "Main Lobby";
                if (x == 7 && z == 2) return "Security Office";
                if (z == 5) return "Storage Room";
                return $"Ground Floor Room {x}-{z}";
            }
            else
            {
                if (x == 0) return "Conference Room";
                if (x == 7) return "Manager Office";
                if (z == 0) return "Break Room";
                return $"Office {floor}{x:D2}{z:D2}";
            }
        }
        
        private RoomType DetermineRoomType(int floor, int x, int z)
        {
            if (floor == 0)
            {
                if (x == 0 && z == 0) return RoomType.Lobby;
                if (x == 7 && z == 2) return RoomType.Security;
                if (z == 5) return RoomType.Storage;
                if (x == 1 && z == 0) return RoomType.Bathroom;
                return RoomType.Utility;
            }
            else
            {
                if (x == 0) return RoomType.Conference;
                if (x == 7) return RoomType.Office;
                if (z == 0) return RoomType.Kitchen;
                if (x == 1 && z == 1) return RoomType.Bathroom;
                return RoomType.Office;
            }
        }
        
        // Add the command to initialize ultra detailed generation
        private void CmdGenerateUltraMap(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_ADMIN))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length < 2)
            {
                SendReply(player, "Usage: /generateultramap <template> <mapname>");
                SendReply(player, "Templates: urban_complex, industrial_facility, military_compound, residential_district");
                return;
            }
            
            string template = args[0];
            string mapName = args[1];
            Vector3 playerPos = player.transform.position;
            
            SendReply(player, "WARNING: Ultra detailed map generation will create thousands of objects!");
            SendReply(player, "This process may take several minutes and use significant server resources.");
            SendReply(player, "Type /confirmultramap to proceed or wait 30 seconds to cancel.");
            
            timer.Once(30f, () =>
            {
                SendReply(player, "Ultra map generation cancelled due to timeout.");
            });
            
            // Store the generation request
            adminClipboard[player.userID] = new ClipboardData
            {
                PendingCommand = $"ultramap {template} {mapName} {playerPos.x} {playerPos.y} {playerPos.z}"
            };
        }
        
        private void CmdConfirmUltraMap(BasePlayer player, string command, string[] args)
        {
            if (!adminClipboard.ContainsKey(player.userID) || 
                !adminClipboard[player.userID].PendingCommand.StartsWith("ultramap"))
            {
                SendReply(player, "No pending ultra map generation found!");
                return;
            }
            
            var parts = adminClipboard[player.userID].PendingCommand.Split(' ');
            if (parts.Length >= 5)
            {
                string template = parts[1];
                string mapName = parts[2];
                Vector3 position = new Vector3(
                    float.Parse(parts[3]),
                    float.Parse(parts[4]),
                    float.Parse(parts[5])
                );
                
                GenerateUltraDetailedMap(player, template, mapName, position);
            }
            
            adminClipboard.Remove(player.userID);
        }
        
