        #region Server Map Integration System
        
        private void AutoGenerateServerMaps()
        {
            PrintWarning("Starting automatic map generation for server...");
            
            // Check if we already have maps configured
            if (mapConfigurations.Count > 2) // More than just default templates
            {
                PrintWarning("Maps already exist, skipping auto-generation.");
                return;
            }
            
            // Generate the main server map
            Vector3 center = config.MapGenerationCenter;
            if (center == Vector3.zero)
            {
                center = DetectOptimalMapCenter();
            }
            
            PrintWarning($"Generating server map '{config.ServerMapName}' at {center}");
            
            // Create a comprehensive map for the server
            var generator = new MapGenerator
            {
                MapName = config.ServerMapName,
                MapCenter = center,
                MapSize = 200f
            };
            
            // Generate based on template
            switch (config.DefaultMapTemplate.ToLower())
            {
                case "dust2_classic":
                    GenerateDust2Classic(generator);
                    break;
                case "mirage_compact":
                    GenerateMirageCompact(generator);
                    break;
                case "inferno_mini":
                    GenerateInfernoMini(generator);
                    break;
                case "cache_small":
                    GenerateCacheSmall(generator);
                    break;
                default:
                    GenerateCustomMap(generator);
                    break;
            }
            
            // Execute generation
            ExecuteMapGeneration(generator, null);
            
            // Generate additional practice maps
            if (config.AutoGenerateDefaultMaps)
            {
                GenerateAdditionalMaps(center);
            }
            
            PrintWarning("Automatic map generation completed!");
        }
        
        private Vector3 DetectOptimalMapCenter()
        {
            PrintWarning("Auto-detecting optimal map generation center...");
            
            // Method 1: Find the geometric center of the Rust map
            var bounds = TerrainMeta.Bounds;
            Vector3 terrainCenter = bounds.center;
            
            // Method 2: Find a flat area suitable for building
            Vector3 optimalCenter = FindFlatBuildingArea(terrainCenter, 300f);
            
            // Method 3: Avoid water and extreme elevations
            optimalCenter = AvoidWaterAndExtremes(optimalCenter);
            
            // Method 4: Check for existing structures and avoid them
            optimalCenter = AvoidExistingStructures(optimalCenter);
            
            config.MapGenerationCenter = optimalCenter;
            SaveConfig();
            
            PrintWarning($"Optimal map center detected: {optimalCenter}");
            return optimalCenter;
        }
        
        private Vector3 FindFlatBuildingArea(Vector3 searchCenter, float searchRadius)
        {
            Vector3 bestLocation = searchCenter;
            float bestFlatness = float.MaxValue;
            
            // Sample points in a grid around the search center
            for (float x = -searchRadius; x <= searchRadius; x += 20f)
            {
                for (float z = -searchRadius; z <= searchRadius; z += 20f)
                {
                    Vector3 testPoint = searchCenter + new Vector3(x, 0, z);
                    
                    // Get terrain height at this point
                    float height = TerrainMeta.HeightMap.GetHeight(testPoint);
                    testPoint.y = height;
                    
                    // Calculate flatness (variance in nearby heights)
                    float flatness = CalculateTerrainFlatness(testPoint, 50f);
                    
                    // Check if this is flatter than our current best
                    if (flatness < bestFlatness)
                    {
                        bestFlatness = flatness;
                        bestLocation = testPoint;
                    }
                }
            }
            
            return bestLocation;
        }
        
        private float CalculateTerrainFlatness(Vector3 center, float radius)
        {
            List<float> heights = new List<float>();
            
            // Sample heights in a circle around the center
            for (int i = 0; i < 16; i++)
            {
                float angle = i * 22.5f * Mathf.Deg2Rad;
                Vector3 samplePoint = center + new Vector3(
                    Mathf.Cos(angle) * radius,
                    0,
                    Mathf.Sin(angle) * radius
                );
                
                float height = TerrainMeta.HeightMap.GetHeight(samplePoint);
                heights.Add(height);
            }
            
            // Calculate variance (lower = flatter)
            float average = heights.Average();
            float variance = heights.Sum(h => Mathf.Pow(h - average, 2)) / heights.Count;
            
            return variance;
        }
        
        private Vector3 AvoidWaterAndExtremes(Vector3 center)
        {
            // Check if the center is in water
            if (WaterLevel.Test(center))
            {
                // Find nearest land
                for (float radius = 10f; radius <= 200f; radius += 10f)
                {
                    for (int i = 0; i < 16; i++)
                    {
                        float angle = i * 22.5f * Mathf.Deg2Rad;
                        Vector3 testPoint = center + new Vector3(
                            Mathf.Cos(angle) * radius,
                            0,
                            Mathf.Sin(angle) * radius
                        );
                        
                        testPoint.y = TerrainMeta.HeightMap.GetHeight(testPoint);
                        
                        if (!WaterLevel.Test(testPoint))
                        {
                            return testPoint;
                        }
                    }
                }
            }
            
            // Check elevation (avoid too high or too low)
            float height = TerrainMeta.HeightMap.GetHeight(center);
            if (height < -10f || height > 100f)
            {
                // Find more reasonable elevation
                return FindReasonableElevation(center);
            }
            
            return center;
        }
        
        private Vector3 FindReasonableElevation(Vector3 center)
        {
            // Look for elevation between 0 and 50 meters
            for (float radius = 50f; radius <= 300f; radius += 25f)
            {
                for (int i = 0; i < 12; i++)
                {
                    float angle = i * 30f * Mathf.Deg2Rad;
                    Vector3 testPoint = center + new Vector3(
                        Mathf.Cos(angle) * radius,
                        0,
                        Mathf.Sin(angle) * radius
                    );
                    
                    float height = TerrainMeta.HeightMap.GetHeight(testPoint);
                    testPoint.y = height;
                    
                    if (height >= 0f && height <= 50f && !WaterLevel.Test(testPoint))
                    {
                        return testPoint;
                    }
                }
            }
            
            return center; // Fallback to original if nothing found
        }
        
        private Vector3 AvoidExistingStructures(Vector3 center)
        {
            // Check for existing entities in the area
            var entities = new List<BaseEntity>();
            Vis.Entities(center, 100f, entities);
            
            // Filter for buildings and large structures
            var structures = entities.Where(e => 
                e is BuildingBlock || 
                e is DecayEntity || 
                e.name.Contains("building") ||
                e.name.Contains("structure")).ToList();
            
            if (structures.Count > 10) // Too many existing structures
            {
                // Find a clearer area
                return FindClearArea(center, 150f);
            }
            
            return center;
        }
        
        private Vector3 FindClearArea(Vector3 center, float searchRadius)
        {
            for (float radius = 50f; radius <= searchRadius; radius += 25f)
            {
                for (int i = 0; i < 8; i++)
                {
                    float angle = i * 45f * Mathf.Deg2Rad;
                    Vector3 testPoint = center + new Vector3(
                        Mathf.Cos(angle) * radius,
                        0,
                        Mathf.Sin(angle) * radius
                    );
                    
                    testPoint.y = TerrainMeta.HeightMap.GetHeight(testPoint);
                    
                    // Check for entities in this area
                    var entities = new List<BaseEntity>();
                    Vis.Entities(testPoint, 50f, entities);
                    
                    var structures = entities.Where(e => 
                        e is BuildingBlock || 
                        e is DecayEntity).ToList();
                    
                    if (structures.Count < 5) // Relatively clear
                    {
                        return testPoint;
                    }
                }
            }
            
            return center; // Fallback
        }
        
        private void DetectMapCenter()
        {
            if (config.MapGenerationCenter != Vector3.zero) return;
            
            config.MapGenerationCenter = DetectOptimalMapCenter();
            SaveConfig();
        }
        
        private void GenerateAdditionalMaps(Vector3 baseCenter)
