        private void GenerateAimTrainingMap(MapGenerator generator)
        {
            Vector3 center = generator.MapCenter;
            
            // Create a simple rectangular training area
            CreateTrainingWalls(generator, center, 40f, 20f);
            
            // Add target positions
            for (int i = 0; i < 10; i++)
            {
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/deployable/signs/sign.large.wood.prefab",
                    Position = center + new Vector3(15f, 2f, i * 3f - 15f),
                    Rotation = new Vector3(0, 180, 0),
                    Type = StructureType.Decoration
                });
            }
            
            // Spawn points
            for (int i = 0; i < 5; i++)
            {
                generator.TerroristSpawns.Add(center + new Vector3(-15f, 0, i * 2f - 4f));
                generator.CounterTerroristSpawns.Add(center + new Vector3(-15f, 0, i * 2f - 4f));
            }
        }
        
        private void GenerateRetakePracticeMap(MapGenerator generator)
        {
            Vector3 center = generator.MapCenter;
            
            // Create a bomb site with multiple angles
            CreateBombSiteStructure(generator, center, "A", 15f);
            
            // Add multiple approach angles
            for (int i = 0; i < 4; i++)
            {
                float angle = i * 90f;
                Vector3 approachStart = center + new Vector3(
                    Mathf.Cos(angle * Mathf.Deg2Rad) * 25f,
                    0,
                    Mathf.Sin(angle * Mathf.Deg2Rad) * 25f
                );
                
                CreateConnectorPath(generator, approachStart, center);
            }
            
            // Spawn points around the site
            for (int i = 0; i < 5; i++)
            {
                float angle = i * 72f * Mathf.Deg2Rad;
                generator.TerroristSpawns.Add(center + new Vector3(
                    Mathf.Cos(angle) * 30f,
                    0,
                    Mathf.Sin(angle) * 30f
                ));
            }
            
            // CT spawns closer to site
            for (int i = 0; i < 3; i++)
            {
                generator.CounterTerroristSpawns.Add(center + new Vector3(i * 3f - 3f, 0, -8f));
            }
        }
        
        private void Generate1v1Arena(MapGenerator generator)
        {
            Vector3 center = generator.MapCenter;
            
            // Create a symmetrical arena
            CreateArenaWalls(generator, center, 25f);
            
            // Add cover in the middle
            generator.Structures.Add(new GeneratedStructure
            {
                PrefabName = "assets/prefabs/deployable/barricades/barricade.concrete.prefab",
                Position = center,
                Rotation = Vector3.zero,
                Type = StructureType.Cover
            });
            
            // Symmetrical spawns
            generator.TerroristSpawns.Add(center + new Vector3(-10f, 0, 0));
            generator.CounterTerroristSpawns.Add(center + new Vector3(10f, 0, 0));
        }
        
        private void CreateTrainingWalls(MapGenerator generator, Vector3 center, float width, float depth)
        {
            // Create walls around the training area
            for (float x = -width/2; x <= width/2; x += 4f)
            {
                // Front and back walls
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/building core/wall/wall.prefab",
                    Position = center + new Vector3(x, 0, -depth/2),
                    Rotation = Vector3.zero,
                    Type = StructureType.Wall
                });
                
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/building core/wall/wall.prefab",
                    Position = center + new Vector3(x, 0, depth/2),
                    Rotation = Vector3.zero,
                    Type = StructureType.Wall
                });
            }
            
            for (float z = -depth/2; z <= depth/2; z += 4f)
            {
                // Left and right walls
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/building core/wall/wall.prefab",
                    Position = center + new Vector3(-width/2, 0, z),
                    Rotation = new Vector3(0, 90, 0),
                    Type = StructureType.Wall
                });
                
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/building core/wall/wall.prefab",
                    Position = center + new Vector3(width/2, 0, z),
                    Rotation = new Vector3(0, 90, 0),
                    Type = StructureType.Wall
                });
            }
        }
        
        private void CreateArenaWalls(MapGenerator generator, Vector3 center, float radius)
        {
            // Create circular arena walls
            for (int i = 0; i < 16; i++)
            {
                float angle = i * 22.5f * Mathf.Deg2Rad;
                Vector3 wallPos = center + new Vector3(
                    Mathf.Cos(angle) * radius,
                    0,
                    Mathf.Sin(angle) * radius
                );
                
                generator.Structures.Add(new GeneratedStructure
                {
                    PrefabName = "assets/prefabs/building core/wall/wall.prefab",
                    Position = wallPos,
                    Rotation = new Vector3(0, i * 22.5f, 0),
                    Type = StructureType.Wall
                });
            }
        }
        
        private void ValidateAllMaps()
        {
            PrintWarning("Validating all configured maps...");
            
            foreach (var mapConfig in mapConfigurations.Values)
            {
                var issues = ValidateMapConfiguration(mapConfig);
                if (issues.Count > 0)
                {
                    PrintWarning($"Map '{mapConfig.MapName}' has {issues.Count} validation issues:");
                    foreach (var issue in issues)
                    {
                        PrintWarning($"  - {issue}");
                    }
                }
                else
                {
                    PrintWarning($"Map '{mapConfig.MapName}' passed validation.");
                }
            }
        }
        
