        #region Map File Management
        
        private void CmdExportMap(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_ADMIN))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length == 0)
            {
                SendReply(player, "Usage: /exportmap <mapname>");
                return;
            }
            
            string mapName = args[0];
            
            if (!mapConfigurations.ContainsKey(mapName))
            {
                SendReply(player, $"Map '{mapName}' not found!");
                return;
            }
            
            ExportMapToFile(mapName, player);
        }
        
        private void CmdImportMap(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_ADMIN))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length == 0)
            {
                SendReply(player, "Usage: /importmap <filename>");
                return;
            }
            
            string filename = args[0];
            ImportMapFromFile(filename, player);
        }
        
        private void ExportMapToFile(string mapName, BasePlayer player)
        {
            try
            {
                var mapConfig = mapConfigurations[mapName];
                var exportData = new
                {
                    MapConfiguration = mapConfig,
                    BombSites = bombSites.Where(bs => bs.Value.MapName == mapName).ToDictionary(bs => bs.Key, bs => bs.Value),
                    Callouts = mapCallouts.Where(c => c.Value.MapName == mapName).ToDictionary(c => c.Key, c => c.Value),
                    ExportDate = DateTime.Now,
                    PluginVersion = "1.0.0"
                };
                
                string json = JsonConvert.SerializeObject(exportData, Formatting.Indented);
                string filename = $"CS2Plugin_Map_{mapName}_{DateTime.Now:yyyyMMdd_HHmmss}.json";
                
                Interface.Oxide.DataFileSystem.WriteObject(filename, exportData);
                
                SendReply(player, $"Map '{mapName}' exported to {filename}");
            }
            catch (Exception ex)
            {
                SendReply(player, $"Error exporting map: {ex.Message}");
            }
        }
        
        private void ImportMapFromFile(string filename, BasePlayer player)
        {
            try
            {
                var importData = Interface.Oxide.DataFileSystem.ReadObject<dynamic>(filename);
                
                // Import map configuration
                var mapConfig = JsonConvert.DeserializeObject<MapConfiguration>(importData.MapConfiguration.ToString());
                mapConfigurations[mapConfig.MapName] = mapConfig;
                
                // Import bomb sites
                if (importData.BombSites != null)
                {
                    var bombSiteData = JsonConvert.DeserializeObject<Dictionary<string, BombSite>>(importData.BombSites.ToString());
                    foreach (var bs in bombSiteData)
                    {
                        bombSites[bs.Key] = bs.Value;
                    }
                }
                
                // Import callouts
                if (importData.Callouts != null)
                {
                    var calloutData = JsonConvert.DeserializeObject<Dictionary<string, MapCallout>>(importData.Callouts.ToString());
                    foreach (var c in calloutData)
                    {
                        mapCallouts[c.Key] = c.Value;
                    }
                }
                
                SaveData();
                
                SendReply(player, $"Map '{mapConfig.MapName}' imported successfully from {filename}");
            }
            catch (Exception ex)
            {
                SendReply(player, $"Error importing map: {ex.Message}");
            }
        }
        
