        #region Voting Commands
        
        private void CmdVoteMap(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_USE))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            var data = GetPlayerData(player.userID);
            
            // Check if player is in a queue
            if (!data.IsInQueue)
            {
                SendReply(player, "You must be in a queue to start a map vote!");
                return;
            }
            
            // Check if there's already an active vote for this queue
            var existingVote = GetActiveVoteForQueue(data.QueueZoneName);
            if (existingVote != null)
            {
                SendReply(player, "There's already an active vote for this queue!");
                ShowVoteUI(player, existingVote);
                return;
            }
            
            // Start a new map vote
            StartMapVote(player, data.QueueZoneName);
        }
        
        private void CmdVote(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_USE))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length == 0)
            {
                // Show active votes
                ShowActiveVotes(player);
                return;
            }
            
            if (args.Length >= 2)
            {
                string voteId = args[0];
                if (int.TryParse(args[1], out int optionId))
                {
                    CastVote(player, voteId, optionId);
                }
                else
                {
                    SendReply(player, "Invalid option number!");
                }
            }
        }
        
        private void CmdTeleportVote(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_USE))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            var data = GetPlayerData(player.userID);
            
            if (!data.IsInQueue)
            {
                SendReply(player, "You must be in a queue to start a teleport vote!");
                return;
            }
            
            StartTeleportVote(player, data.QueueZoneName);
        }
        
        private void CmdForceVote(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_ADMIN))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length < 2)
            {
                SendReply(player, "Usage: /forcevote <type> <target>");
                SendReply(player, "Types: map, teleport, gamemode");
                return;
            }
            
            string voteType = args[0].ToLower();
            string target = args[1];
            
            switch (voteType)
            {
                case "map":
                    ForceMapVote(player, target);
                    break;
                case "teleport":
                    ForceTeleportVote(player, target);
                    break;
                case "gamemode":
                    ForceGameModeVote(player, target);
                    break;
                default:
                    SendReply(player, "Invalid vote type!");
                    break;
            }
        }
        
        #endregion
        
        #region Voting Logic
        
        private void StartMapVote(BasePlayer initiator, string queueZoneName)
        {
            if (!queueZones.ContainsKey(queueZoneName))
            {
                SendReply(initiator, "Queue zone not found!");
                return;
            }
            
            var zone = queueZones[queueZoneName];
            var eligibleVoters = zone.QueuedPlayers.ToList();
            
            if (eligibleVoters.Count < 2)
            {
                SendReply(initiator, "Need at least 2 players to start a vote!");
                return;
            }
            
            var voteId = GenerateVoteId();
            var vote = new Vote
            {
                VoteId = voteId,
                Type = VoteType.MapSelection,
                Title = "Map Selection Vote",
                Description = "Choose the map for your next match!",
                EligibleVoters = eligibleVoters,
                StartTime = DateTime.Now,
                Duration = 30f,
                InitiatorId = initiator.userID,
                QueueZoneName = queueZoneName,
                RequiresMajority = true,
                MinimumVotePercentage = 0.5f,
                AutoExecute = true
            };
            
            // Add map options
            var availableMaps = GetAvailableMapsForVoting();
            for (int i = 0; i < availableMaps.Count && i < 5; i++) // Limit to 5 options
            {
                var map = availableMaps[i];
                vote.Options.Add(new VoteOption
                {
                    OptionId = i + 1,
                    Name = map.Key,
                    Description = GetMapDescription(map.Value),
                    MapName = map.Key,
                    TeleportLocation = map.Value.SpectatorArea
                });
            }
            
            activeVotes[vote.VoteId] = vote;
            
            // Start vote timer
            vote.VoteTimer = timer.Once(vote.Duration, () => EndVote(vote.VoteId));
            
            // Notify all eligible voters
            NotifyVoteStart(vote);
            
            // Show UI to all voters
            foreach (var voterId in eligibleVoters)
            {
                var voter = BasePlayer.FindByID(voterId);
                if (voter != null)
                {
                    ShowVoteUI(voter, vote);
                }
            }
        }
        
        private void StartTeleportVote(BasePlayer initiator, string queueZoneName)
        {
            if (!queueZones.ContainsKey(queueZoneName))
            {
                SendReply(initiator, "Queue zone not found!");
                return;
            }
            
            var zone = queueZones[queueZoneName];
            var eligibleVoters = zone.QueuedPlayers.ToList();
            
            if (eligibleVoters.Count < 2)
            {
                SendReply(initiator, "Need at least 2 players to start a vote!");
                return;
            }
            
            var voteId = GenerateVoteId();
            var vote = new Vote
            {
                VoteId = voteId,
                Type = VoteType.Teleportation,
                Title = "Teleport Location Vote",
                Description = "Choose where to teleport for practice!",
                EligibleVoters = eligibleVoters,
                StartTime = DateTime.Now,
                Duration = 20f,
                InitiatorId = initiator.userID,
                QueueZoneName = queueZoneName,
                RequiresMajority = true,
                MinimumVotePercentage = 0.5f,
                AutoExecute = true
            };
            
            // Add teleport location options
            var teleportLocations = GetTeleportLocations();
            for (int i = 0; i < teleportLocations.Count && i < 6; i++)
            {
                var location = teleportLocations[i];
                vote.Options.Add(new VoteOption
                {
                    OptionId = i + 1,
                    Name = location.Key,
                    Description = location.Value.Description,
                    TeleportLocation = location.Value.Position,
                    CustomData = new Dictionary<string, object>
                    {
                        ["LocationType"] = location.Value.Type,
                        ["MapName"] = location.Value.MapName
                    }
                });
            }
            
            activeVotes[vote.VoteId] = vote;
            
            // Start vote timer
            vote.VoteTimer = timer.Once(vote.Duration, () => EndVote(vote.VoteId));
            
            // Notify and show UI
            NotifyVoteStart(vote);
            foreach (var voterId in eligibleVoters)
            {
                var voter = BasePlayer.FindByID(voterId);
                if (voter != null)
                {
                    ShowVoteUI(voter, vote);
                }
            }
        }
        
        private void CastVote(BasePlayer player, string voteId, int optionId)
        {
            if (!activeVotes.ContainsKey(voteId))
            {
                SendReply(player, "Vote not found or has ended!");
                return;
            }
            
            var vote = activeVotes[voteId];
            
            if (!vote.EligibleVoters.Contains(player.userID))
            {
                SendReply(player, "You are not eligible to vote in this poll!");
                return;
            }
            
            if (!vote.IsActive)
            {
                SendReply(player, "This vote has ended!");
                return;
            }
            
            var option = vote.Options.FirstOrDefault(o => o.OptionId == optionId);
            if (option == null)
            {
                SendReply(player, "Invalid vote option!");
                return;
            }
            
            // Remove previous vote if exists
            if (vote.PlayerVotes.ContainsKey(player.userID))
            {
                var previousOption = vote.Options.FirstOrDefault(o => o.OptionId == vote.PlayerVotes[player.userID]);
                if (previousOption != null)
                {
                    previousOption.VoteCount--;
                }
            }
            
            // Cast new vote
            vote.PlayerVotes[player.userID] = optionId;
            option.VoteCount++;
            
            SendReply(player, $"Vote cast for: {option.Name}");
            
            // Update UI for all voters
            UpdateVoteUI(vote);
            
            // Check if all players have voted
            if (vote.PlayerVotes.Count >= vote.EligibleVoters.Count)
            {
                EndVote(voteId);
            }
        }
        
        private void EndVote(string voteId)
        {
            if (!activeVotes.ContainsKey(voteId))
                return;
            
            var vote = activeVotes[voteId];
            vote.IsActive = false;
            vote.VoteTimer?.Destroy();
            
            // Calculate results
            var results = CalculateVoteResults(vote);
            
            // Notify results
            NotifyVoteResults(vote, results);
            
            // Execute vote result if auto-execute is enabled
            if (vote.AutoExecute && results.WinningOption != null)
            {
                ExecuteVoteResult(vote, results);
            }
            
            // Clean up UI
            foreach (var voterId in vote.EligibleVoters)
            {
                var voter = BasePlayer.FindByID(voterId);
                if (voter != null)
                {
                    DestroyVoteUI(voter);
                }
            }
            
            // Remove from active votes after delay
            timer.Once(5f, () => activeVotes.Remove(voteId));
        }
        
        private VoteResults CalculateVoteResults(Vote vote)
        {
            var results = new VoteResults
            {
                TotalVotes = vote.PlayerVotes.Count,
                TotalEligibleVoters = vote.EligibleVoters.Count,
                VotePercentage = (float)vote.PlayerVotes.Count / vote.EligibleVoters.Count
            };
            
            if (vote.Options.Count > 0)
            {
                results.WinningOption = vote.Options.OrderByDescending(o => o.VoteCount).First();
                results.WinningVotes = results.WinningOption.VoteCount;
                results.WinningPercentage = (float)results.WinningVotes / Math.Max(1, results.TotalVotes);
            }
            
            results.PassedRequirements = results.VotePercentage >= vote.MinimumVotePercentage &&
                                       (!vote.RequiresMajority || results.WinningPercentage > 0.5f);
            
            return results;
        }
        
        private void ExecuteVoteResult(Vote vote, VoteResults results)
        {
            if (!results.PassedRequirements || results.WinningOption == null)
            {
                return;
            }
            
            switch (vote.Type)
            {
                case VoteType.MapSelection:
                    ExecuteMapSelection(vote, results.WinningOption);
                    break;
                case VoteType.Teleportation:
                    ExecuteTeleportation(vote, results.WinningOption);
                    break;
                case VoteType.MapChange:
                    ExecuteMapChange(vote, results.WinningOption);
                    break;
            }
        }
        
        private void ExecuteMapSelection(Vote vote, VoteOption winningOption)
        {
            if (!queueZones.ContainsKey(vote.QueueZoneName))
                return;
            
            var zone = queueZones[vote.QueueZoneName];
            zone.SelectedMap = winningOption.MapName;
            
            // Notify players
            foreach (var playerId in vote.EligibleVoters)
            {
                var player = BasePlayer.FindByID(playerId);
                if (player != null)
                {
                    SendReply(player, $"Map selected: {winningOption.Name}");
                    SendReply(player, "The next match will be played on this map!");
                }
            }
        }
        
        private void ExecuteTeleportation(Vote vote, VoteOption winningOption)
        {
            // Teleport all eligible voters to the winning location
            foreach (var playerId in vote.EligibleVoters)
            {
                var player = BasePlayer.FindByID(playerId);
                if (player != null)
                {
                    TeleportPlayer(player, winningOption.TeleportLocation);
                    SendReply(player, $"Teleported to: {winningOption.Name}");
                }
            }
        }
        
        private void ExecuteMapChange(Vote vote, VoteOption winningOption)
        {
            // Change the current map for the queue
            if (queueZones.ContainsKey(vote.QueueZoneName))
            {
                var zone = queueZones[vote.QueueZoneName];
                zone.SelectedMap = winningOption.MapName;
                
                // If there's an active match, end it and start new one
                // Implementation depends on your match management system
            }
        }
        
        #endregion
        
        #region Voting UI System
        
        private void ShowVoteUI(BasePlayer player, Vote vote)
        {
            var container = new CuiElementContainer();
            
            // Main vote panel
            container.Add(new CuiPanel
            {
                Image = { Color = "0 0 0 0.8" },
                RectTransform = { AnchorMin = "0.2 0.3", AnchorMax = "0.8 0.8" }
            }, "Overlay", "VoteUI");
            
            // Title
            container.Add(new CuiLabel
            {
                Text = { Text = vote.Title, FontSize = 20, Align = TextAnchor.MiddleCenter, Color = "1 1 1 1" },
                RectTransform = { AnchorMin = "0 0.85", AnchorMax = "1 0.95" }
            }, "VoteUI");
            
            // Description
            container.Add(new CuiLabel
            {
                Text = { Text = vote.Description, FontSize = 14, Align = TextAnchor.MiddleCenter, Color = "0.8 0.8 0.8 1" },
                RectTransform = { AnchorMin = "0 0.75", AnchorMax = "1 0.85" }
            }, "VoteUI");
            
            // Timer
            float timeLeft = vote.Duration - (float)(DateTime.Now - vote.StartTime).TotalSeconds;
            container.Add(new CuiLabel
            {
                Text = { Text = $"Time Left: {timeLeft:F0}s", FontSize = 12, Align = TextAnchor.MiddleCenter, Color = "1 1 0 1" },
                RectTransform = { AnchorMin = "0 0.68", AnchorMax = "1 0.75" }
            }, "VoteUI");
            
            // Vote options
            float optionHeight = 0.6f / Math.Max(1, vote.Options.Count);
            for (int i = 0; i < vote.Options.Count; i++)
            {
                var option = vote.Options[i];
                float yMin = 0.65f - (i + 1) * optionHeight;
                float yMax = 0.65f - i * optionHeight;
                
                // Option button
                string buttonColor = vote.PlayerVotes.ContainsKey(player.userID) && vote.PlayerVotes[player.userID] == option.OptionId 
                    ? "0.2 0.8 0.2 1" : "0.3 0.3 0.3 1";
                
                container.Add(new CuiButton
                {
                    Button = { Command = $"cs2.vote {vote.VoteId} {option.OptionId}", Color = buttonColor },
                    RectTransform = { AnchorMin = $"0.05 {yMin}", AnchorMax = $"0.7 {yMax}" },
                    Text = { Text = $"{option.OptionId}. {option.Name}", FontSize = 12, Align = TextAnchor.MiddleLeft, Color = "1 1 1 1" }
                }, "VoteUI");
                
                // Vote count
                container.Add(new CuiLabel
                {
                    Text = { Text = $"{option.VoteCount} votes", FontSize = 10, Align = TextAnchor.MiddleCenter, Color = "0.7 0.7 0.7 1" },
                    RectTransform = { AnchorMin = $"0.72 {yMin}", AnchorMax = $"0.95 {yMax}" }
                }, "VoteUI");
                
                // Progress bar
                float percentage = vote.EligibleVoters.Count > 0 ? (float)option.VoteCount / vote.EligibleVoters.Count : 0f;
                container.Add(new CuiPanel
                {
                    Image = { Color = "0.2 0.6 1 0.3" },
                    RectTransform = { AnchorMin = $"0.05 {yMin + 0.01f}", AnchorMax = $"{0.05f + percentage * 0.65f} {yMax - 0.01f}" }
                }, "VoteUI", $"VoteProgress_{i}");
            }
            
            // Vote status
            int totalVoted = vote.PlayerVotes.Count;
            int totalEligible = vote.EligibleVoters.Count;
            container.Add(new CuiLabel
            {
                Text = { Text = $"Votes: {totalVoted}/{totalEligible}", FontSize = 12, Align = TextAnchor.MiddleCenter, Color = "1 1 1 1" },
                RectTransform = { AnchorMin = "0 0.05", AnchorMax = "1 0.15" }
            }, "VoteUI");
            
            // Register vote command
            cmd.AddChatCommand("cs2.vote", this, "CmdVoteOption");
            
            CuiHelper.DestroyUi(player, "VoteUI");
            CuiHelper.AddUi(player, container);
        }
        
        private void CmdVoteOption(BasePlayer player, string command, string[] args)
        {
            if (args.Length >= 2)
            {
                string voteId = args[0];
                if (int.TryParse(args[1], out int optionId))
                {
                    CastVote(player, voteId, optionId);
                }
            }
        }
        
        private void UpdateVoteUI(Vote vote)
        {
            foreach (var voterId in vote.EligibleVoters)
            {
                var voter = BasePlayer.FindByID(voterId);
                if (voter != null)
                {
                    ShowVoteUI(voter, vote);
                }
            }
        }
        
        private void DestroyVoteUI(BasePlayer player)
        {
            CuiHelper.DestroyUi(player, "VoteUI");
        }
        
        private void ShowActiveVotes(BasePlayer player)
        {
            var playerVotes = activeVotes.Values.Where(v => v.EligibleVoters.Contains(player.userID) && v.IsActive).ToList();
            
            if (playerVotes.Count == 0)
            {
                SendReply(player, "No active votes available.");
                return;
            }
            
            SendReply(player, "=== ACTIVE VOTES ===");
            foreach (var vote in playerVotes)
            {
                float timeLeft = vote.Duration - (float)(DateTime.Now - vote.StartTime).TotalSeconds;
                SendReply(player, $"• {vote.Title} - {timeLeft:F0}s left");
                SendReply(player, $"  Use: /vote {vote.VoteId} <option>");
            }
        }
        
