        #region Voting Helper Methods
        
        private string GenerateVoteId()
        {
            return $"vote_{DateTime.Now.Ticks}_{UnityEngine.Random.Range(1000, 9999)}";
        }
        
        private Vote GetActiveVoteForQueue(string queueZoneName)
        {
            return activeVotes.Values.FirstOrDefault(v => v.QueueZoneName == queueZoneName && v.IsActive);
        }
        
        private Dictionary<string, MapConfiguration> GetAvailableMapsForVoting()
        {
            return mapConfigurations.Where(m => 
                m.Value.TerroristSpawns.Count >= 5 && 
                m.Value.CounterTerroristSpawns.Count >= 5 &&
                m.Value.BombSiteNames.Count >= 2
            ).ToDictionary(m => m.Key, m => m.Value);
        }
        
        private string GetMapDescription(MapConfiguration map)
        {
            return $"T:{map.TerroristSpawns.Count} CT:{map.CounterTerroristSpawns.Count} Sites:{map.BombSiteNames.Count}";
        }
        
        private Dictionary<string, TeleportLocation> GetTeleportLocations()
        {
            var locations = new Dictionary<string, TeleportLocation>();
            
            // Add map-based locations
            foreach (var map in mapConfigurations)
            {
                locations[$"{map.Key}_spectator"] = new TeleportLocation
                {
                    Name = $"{map.Key} Spectator Area",
                    Description = $"Spectator area for {map.Key}",
                    Position = map.Value.SpectatorArea,
                    Type = "spectator",
                    MapName = map.Key
                };
                
                if (map.Value.TerroristSpawns.Count > 0)
                {
                    locations[$"{map.Key}_t_spawn"] = new TeleportLocation
                    {
                        Name = $"{map.Key} T Spawn",
                        Description = $"Terrorist spawn for {map.Key}",
                        Position = map.Value.TerroristSpawns[0],
                        Type = "spawn",
                        MapName = map.Key
                    };
                }
                
                if (map.Value.CounterTerroristSpawns.Count > 0)
                {
                    locations[$"{map.Key}_ct_spawn"] = new TeleportLocation
                    {
                        Name = $"{map.Key} CT Spawn",
                        Description = $"Counter-Terrorist spawn for {map.Key}",
                        Position = map.Value.CounterTerroristSpawns[0],
                        Type = "spawn",
                        MapName = map.Key
                    };
                }
            }
            
            // Add bomb site locations
            foreach (var bombSite in bombSites.Values)
            {
                var center = (bombSite.MinBounds + bombSite.MaxBounds) / 2f;
                locations[$"bombsite_{bombSite.Name}"] = new TeleportLocation
                {
                    Name = $"Bomb Site {bombSite.Name}",
                    Description = $"Bomb site {bombSite.Name} on {bombSite.MapName}",
                    Position = center,
                    Type = "bombsite",
                    MapName = bombSite.MapName
                };
            }
            
            // Add lobby
            locations["lobby"] = new TeleportLocation
            {
                Name = "Lobby",
                Description = "Main lobby area",
                Position = config.LobbySpawnPoint,
                Type = "lobby",
                MapName = "lobby"
            };
            
            return locations;
        }
        
        private void NotifyVoteStart(Vote vote)
        {
            foreach (var voterId in vote.EligibleVoters)
            {
                var voter = BasePlayer.FindByID(voterId);
                if (voter != null)
                {
                    SendReply(voter, $"🗳️ {vote.Title} started!");
                    SendReply(voter, $"📝 {vote.Description}");
                    SendReply(voter, $"⏰ {vote.Duration} seconds to vote");
                    SendReply(voter, "Use the UI or type /vote <voteId> <option>");
                }
            }
        }
        
        private void NotifyVoteResults(Vote vote, VoteResults results)
        {
            string resultMessage;
            
            if (results.PassedRequirements && results.WinningOption != null)
            {
                resultMessage = $"🎉 Vote passed! Winner: {results.WinningOption.Name} ({results.WinningVotes} votes)";
            }
            else if (results.TotalVotes == 0)
            {
                resultMessage = "❌ Vote failed - No votes cast";
            }
            else if (results.VotePercentage < vote.MinimumVotePercentage)
            {
                resultMessage = $"❌ Vote failed - Not enough participation ({results.VotePercentage:P0} < {vote.MinimumVotePercentage:P0})";
            }
            else
            {
                resultMessage = $"❌ Vote failed - No clear majority";
            }
            
            foreach (var voterId in vote.EligibleVoters)
            {
                var voter = BasePlayer.FindByID(voterId);
                if (voter != null)
                {
                    SendReply(voter, resultMessage);
                    
                    // Show detailed results
                    SendReply(voter, "📊 Vote Results:");
                    foreach (var option in vote.Options.OrderByDescending(o => o.VoteCount))
                    {
                        float percentage = results.TotalVotes > 0 ? (float)option.VoteCount / results.TotalVotes : 0f;
                        SendReply(voter, $"  {option.Name}: {option.VoteCount} votes ({percentage:P0})");
                    }
                }
            }
        }
        
        private void ForceMapVote(BasePlayer admin, string queueZoneName)
        {
            if (!queueZones.ContainsKey(queueZoneName))
            {
                SendReply(admin, "Queue zone not found!");
                return;
            }
            
            StartMapVote(admin, queueZoneName);
            SendReply(admin, $"Forced map vote started for queue '{queueZoneName}'");
        }
        
        private void ForceTeleportVote(BasePlayer admin, string queueZoneName)
        {
            if (!queueZones.ContainsKey(queueZoneName))
            {
                SendReply(admin, "Queue zone not found!");
                return;
            }
            
            StartTeleportVote(admin, queueZoneName);
            SendReply(admin, $"Forced teleport vote started for queue '{queueZoneName}'");
        }
        
        private void ForceGameModeVote(BasePlayer admin, string queueZoneName)
        {
            // Implementation for game mode voting
            SendReply(admin, "Game mode voting not yet implemented!");
        }
        
