        #region ELO Rating & Ranking System
        
        public class PlayerRanking
        {
            public ulong PlayerId { get; set; }
            public int ELO { get; set; } = 1000;
            public Rank CurrentRank { get; set; } = Rank.Silver_1;
            public int RankPoints { get; set; } = 0;
            public int PlacementMatches { get; set; } = 0;
            public bool IsPlaced { get; set; } = false;
            public DateTime LastMatchDate { get; set; }
            public float RankDecayMultiplier { get; set; } = 1.0f;
            public List<MatchResult> RecentMatches { get; set; } = new List<MatchResult>();
            public int WinStreak { get; set; } = 0;
            public int LossStreak { get; set; } = 0;
            public SeasonStats CurrentSeason { get; set; } = new SeasonStats();
        }
        
        public enum Rank
        {
            Unranked = 0,
            Silver_1 = 1, Silver_2 = 2, Silver_3 = 3, Silver_4 = 4, Silver_Elite = 5, Silver_Elite_Master = 6,
            Gold_Nova_1 = 7, Gold_Nova_2 = 8, Gold_Nova_3 = 9, Gold_Nova_Master = 10,
            Master_Guardian_1 = 11, Master_Guardian_2 = 12, Master_Guardian_Elite = 13, Distinguished_Master_Guardian = 14,
            Legendary_Eagle = 15, Legendary_Eagle_Master = 16, Supreme_Master_First_Class = 17, Global_Elite = 18
        }
        
        public class MatchResult
        {
            public ulong MatchId { get; set; }
            public bool Won { get; set; }
            public int RoundsWon { get; set; }
            public int RoundsLost { get; set; }
            public int Kills { get; set; }
            public int Deaths { get; set; }
            public int Assists { get; set; }
            public float MVPRating { get; set; }
            public int ELOChange { get; set; }
            public DateTime MatchDate { get; set; }
            public string MapName { get; set; }
        }
        
        public class SeasonStats
        {
            public int SeasonNumber { get; set; }
            public int Wins { get; set; } = 0;
            public int Losses { get; set; } = 0;
            public int Draws { get; set; } = 0;
            public float AverageKD { get; set; } = 0f;
            public float HeadshotPercentage { get; set; } = 0f;
            public Rank HighestRank { get; set; } = Rank.Unranked;
            public int TotalKills { get; set; } = 0;
            public int TotalDeaths { get; set; } = 0;
            public int MVPs { get; set; } = 0;
        }
        
        private Dictionary<ulong, PlayerRanking> playerRankings = new Dictionary<ulong, PlayerRanking>();
        private int currentSeason = 1;
        
        private void CalculateELOChange(Match match)
        {
            var tPlayers = match.TerroristPlayers.Select(id => GetPlayerRanking(id)).ToList();
            var ctPlayers = match.CounterTerroristPlayers.Select(id => GetPlayerRanking(id)).ToList();
            
            float tAvgELO = tPlayers.Average(p => p.ELO);
            float ctAvgELO = ctPlayers.Average(p => p.ELO);
            
            bool tWon = match.TerroristScore > match.CounterTerroristScore;
            
            foreach (var playerId in match.TerroristPlayers.Concat(match.CounterTerroristPlayers))
            {
                var ranking = GetPlayerRanking(playerId);
                var playerData = GetPlayerData(playerId);
                
                bool playerWon = (match.TerroristPlayers.Contains(playerId) && tWon) ||
                                (match.CounterTerroristPlayers.Contains(playerId) && !tWon);
                
                int eloChange = CalculateIndividualELO(ranking, playerData, playerWon, tAvgELO, ctAvgELO, match);
                
                ranking.ELO += eloChange;
                ranking.ELO = Mathf.Clamp(ranking.ELO, 100, 3000);
                
                UpdateRank(ranking);
                UpdateStreaks(ranking, playerWon);
                
                // Add to recent matches
                ranking.RecentMatches.Add(new MatchResult
                {
                    MatchId = match.MatchId,
                    Won = playerWon,
                    RoundsWon = playerWon ? (tWon ? match.TerroristScore : match.CounterTerroristScore) : (tWon ? match.CounterTerroristScore : match.TerroristScore),
                    RoundsLost = playerWon ? (tWon ? match.CounterTerroristScore : match.TerroristScore) : (tWon ? match.TerroristScore : match.CounterTerroristScore),
                    Kills = playerData.RoundKills,
                    Deaths = playerData.RoundDeaths,
                    ELOChange = eloChange,
                    MatchDate = DateTime.Now,
                    MapName = match.MapName
                });
                
                // Keep only last 20 matches
                if (ranking.RecentMatches.Count > 20)
                {
                    ranking.RecentMatches.RemoveAt(0);
                }
                
                var player = BasePlayer.FindByID(playerId);
                if (player != null)
                {
                    SendReply(player, $"ELO: {ranking.ELO} ({(eloChange >= 0 ? "+" : "")}{eloChange}) | Rank: {ranking.CurrentRank}");
                }
            }
        }
        
        private int CalculateIndividualELO(PlayerRanking ranking, PlayerData playerData, bool won, float tAvgELO, float ctAvgELO, Match match)
        {
            // Base ELO calculation
            float expectedScore = 1f / (1f + Mathf.Pow(10f, (ctAvgELO - tAvgELO) / 400f));
            float actualScore = won ? 1f : 0f;
            
            // K-factor based on rank and placement matches
            int kFactor = GetKFactor(ranking);
            
            // Performance multiplier based on individual performance
            float performanceMultiplier = CalculatePerformanceMultiplier(playerData, match);
            
            // Round difference impact
            float roundDiffMultiplier = CalculateRoundDifferenceMultiplier(match);
            
            int baseChange = Mathf.RoundToInt(kFactor * (actualScore - expectedScore));
            int finalChange = Mathf.RoundToInt(baseChange * performanceMultiplier * roundDiffMultiplier);
            
            return finalChange;
        }
        
        private int GetKFactor(PlayerRanking ranking)
        {
            if (ranking.PlacementMatches < 10) return 50; // Placement matches
            if (ranking.ELO < 1200) return 32; // Lower ranks
            if (ranking.ELO < 2000) return 24; // Mid ranks
            return 16; // High ranks
        }
        
        private float CalculatePerformanceMultiplier(PlayerData playerData, Match match)
        {
            float kd = playerData.RoundDeaths > 0 ? (float)playerData.RoundKills / playerData.RoundDeaths : playerData.RoundKills;
            float baseMultiplier = 1.0f;
            
            // KD impact
            if (kd > 1.5f) baseMultiplier += 0.2f;
            else if (kd < 0.5f) baseMultiplier -= 0.2f;
            
            // MVP rounds impact
            if (playerData.MVPRounds > 0) baseMultiplier += 0.1f * playerData.MVPRounds;
            
            return Mathf.Clamp(baseMultiplier, 0.5f, 1.5f);
        }
        
        private float CalculateRoundDifferenceMultiplier(Match match)
        {
            int roundDiff = Mathf.Abs(match.TerroristScore - match.CounterTerroristScore);
            
            if (roundDiff <= 2) return 1.2f; // Close game
            if (roundDiff >= 10) return 0.8f; // Blowout
            return 1.0f; // Normal game
        }
        
        private void UpdateRank(PlayerRanking ranking)
        {
            Rank newRank = CalculateRankFromELO(ranking.ELO);
            
            if (newRank != ranking.CurrentRank)
            {
                Rank oldRank = ranking.CurrentRank;
                ranking.CurrentRank = newRank;
                
                var player = BasePlayer.FindByID(ranking.PlayerId);
                if (player != null)
                {
                    if (newRank > oldRank)
                    {
                        SendReply(player, $"🎉 RANK UP! You are now {newRank}!");
                        // Play rank up sound/effect
                    }
                    else
                    {
                        SendReply(player, $"📉 Rank down to {newRank}");
                    }
                }
            }
        }
        
        private Rank CalculateRankFromELO(int elo)
        {
            if (elo < 600) return Rank.Silver_1;
            if (elo < 700) return Rank.Silver_2;
            if (elo < 800) return Rank.Silver_3;
            if (elo < 900) return Rank.Silver_4;
            if (elo < 1000) return Rank.Silver_Elite;
            if (elo < 1100) return Rank.Silver_Elite_Master;
            if (elo < 1200) return Rank.Gold_Nova_1;
            if (elo < 1300) return Rank.Gold_Nova_2;
            if (elo < 1400) return Rank.Gold_Nova_3;
            if (elo < 1500) return Rank.Gold_Nova_Master;
            if (elo < 1600) return Rank.Master_Guardian_1;
            if (elo < 1700) return Rank.Master_Guardian_2;
            if (elo < 1800) return Rank.Master_Guardian_Elite;
            if (elo < 1900) return Rank.Distinguished_Master_Guardian;
            if (elo < 2000) return Rank.Legendary_Eagle;
            if (elo < 2100) return Rank.Legendary_Eagle_Master;
            if (elo < 2200) return Rank.Supreme_Master_First_Class;
            return Rank.Global_Elite;
        }
        
        private void UpdateStreaks(PlayerRanking ranking, bool won)
        {
            if (won)
            {
                ranking.WinStreak++;
                ranking.LossStreak = 0;
            }
            else
            {
                ranking.LossStreak++;
                ranking.WinStreak = 0;
            }
        }
        
        private PlayerRanking GetPlayerRanking(ulong playerId)
        {
            if (!playerRankings.ContainsKey(playerId))
            {
                playerRankings[playerId] = new PlayerRanking
                {
                    PlayerId = playerId,
                    CurrentSeason = new SeasonStats { SeasonNumber = currentSeason }
                };
            }
            return playerRankings[playerId];
        }
        
        #endregion
        
        #region AI Training Bots System
        
        public class AIBot
        {
            public string BotId { get; set; }
            public string Name { get; set; }
            public BotDifficulty Difficulty { get; set; }
            public BotPersonality Personality { get; set; }
            public Vector3 Position { get; set; }
            public Vector3 Rotation { get; set; }
            public Team Team { get; set; }
            public BotState State { get; set; }
            public List<Vector3> PatrolPoints { get; set; } = new List<Vector3>();
            public int CurrentPatrolIndex { get; set; } = 0;
            public ulong TargetPlayerId { get; set; } = 0;
            public float LastShotTime { get; set; } = 0f;
            public float ReactionTime { get; set; } = 0.5f;
            public float Accuracy { get; set; } = 0.7f;
            public string CurrentWeapon { get; set; } = "rifle.ak";
            public Dictionary<string, float> Skills { get; set; } = new Dictionary<string, float>();
            public Timer BehaviorTimer { get; set; }
        }
        
        public enum BotDifficulty
        {
            Easy, Medium, Hard, Expert, Professional
        }
        
        public enum BotPersonality
        {
            Aggressive, Defensive, Tactical, Rusher, Lurker, Support, AWPer
        }
        
        public enum BotState
        {
            Idle, Patrolling, Engaging, Retreating, Planting, Defusing, Following
        }
        
        private Dictionary<string, AIBot> activeBots = new Dictionary<string, AIBot>();
        
        private void CmdAddBot(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_ADMIN))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length < 2)
            {
                SendReply(player, "Usage: /addbot <difficulty> <personality> [name]");
                SendReply(player, "Difficulties: easy, medium, hard, expert, professional");
                SendReply(player, "Personalities: aggressive, defensive, tactical, rusher, lurker, support, awper");
                return;
            }
            
            if (!Enum.TryParse<BotDifficulty>(args[0], true, out BotDifficulty difficulty))
            {
                SendReply(player, "Invalid difficulty! Use: easy, medium, hard, expert, professional");
                return;
            }
            
            if (!Enum.TryParse<BotPersonality>(args[1], true, out BotPersonality personality))
            {
                SendReply(player, "Invalid personality! Use: aggressive, defensive, tactical, rusher, lurker, support, awper");
                return;
            }
            
            string botName = args.Length > 2 ? args[2] : GenerateBotName(personality);
            
            CreateAIBot(player.transform.position, difficulty, personality, botName);
            SendReply(player, $"Created {difficulty} {personality} bot '{botName}'");
        }
        
        private void CreateAIBot(Vector3 position, BotDifficulty difficulty, BotPersonality personality, string name)
        {
            string botId = $"bot_{UnityEngine.Random.Range(1000, 9999)}";
            
            var bot = new AIBot
            {
                BotId = botId,
                Name = name,
                Difficulty = difficulty,
                Personality = personality,
                Position = position,
                State = BotState.Idle,
                ReactionTime = GetBotReactionTime(difficulty),
                Accuracy = GetBotAccuracy(difficulty),
                CurrentWeapon = GetBotWeapon(personality)
            };
            
            // Set bot skills based on difficulty
            SetBotSkills(bot);
            
            // Create patrol points
            GenerateBotPatrolPoints(bot, position);
            
            activeBots[botId] = bot;
            
            // Start bot AI behavior
            StartBotBehavior(bot);
        }
        
        private float GetBotReactionTime(BotDifficulty difficulty)
        {
            switch (difficulty)
            {
                case BotDifficulty.Easy: return UnityEngine.Random.Range(0.8f, 1.2f);
                case BotDifficulty.Medium: return UnityEngine.Random.Range(0.5f, 0.8f);
                case BotDifficulty.Hard: return UnityEngine.Random.Range(0.3f, 0.5f);
                case BotDifficulty.Expert: return UnityEngine.Random.Range(0.2f, 0.3f);
                case BotDifficulty.Professional: return UnityEngine.Random.Range(0.1f, 0.2f);
                default: return 0.5f;
            }
        }
        
        private float GetBotAccuracy(BotDifficulty difficulty)
        {
            switch (difficulty)
            {
                case BotDifficulty.Easy: return UnityEngine.Random.Range(0.3f, 0.5f);
                case BotDifficulty.Medium: return UnityEngine.Random.Range(0.5f, 0.7f);
                case BotDifficulty.Hard: return UnityEngine.Random.Range(0.7f, 0.85f);
                case BotDifficulty.Expert: return UnityEngine.Random.Range(0.85f, 0.95f);
                case BotDifficulty.Professional: return UnityEngine.Random.Range(0.95f, 0.99f);
                default: return 0.7f;
            }
        }
        
        private string GetBotWeapon(BotPersonality personality)
        {
            switch (personality)
            {
                case BotPersonality.AWPer: return "rifle.bolt";
                case BotPersonality.Rusher: return "smg.thompson";
                case BotPersonality.Support: return "rifle.lr300";
                default: return "rifle.ak";
            }
        }
        
        private void SetBotSkills(AIBot bot)
        {
            float skillMultiplier = GetSkillMultiplier(bot.Difficulty);
            
            bot.Skills["Aim"] = UnityEngine.Random.Range(0.5f, 1.0f) * skillMultiplier;
            bot.Skills["Movement"] = UnityEngine.Random.Range(0.5f, 1.0f) * skillMultiplier;
            bot.Skills["Tactics"] = UnityEngine.Random.Range(0.5f, 1.0f) * skillMultiplier;
            bot.Skills["Utility"] = UnityEngine.Random.Range(0.3f, 0.8f) * skillMultiplier;
            bot.Skills["Economy"] = UnityEngine.Random.Range(0.4f, 0.9f) * skillMultiplier;
        }
        
        private float GetSkillMultiplier(BotDifficulty difficulty)
        {
            switch (difficulty)
            {
                case BotDifficulty.Easy: return 0.4f;
                case BotDifficulty.Medium: return 0.6f;
                case BotDifficulty.Hard: return 0.8f;
                case BotDifficulty.Expert: return 0.95f;
                case BotDifficulty.Professional: return 1.0f;
                default: return 0.6f;
            }
        }
        
        private string GenerateBotName(BotPersonality personality)
        {
            var names = new Dictionary<BotPersonality, List<string>>
            {
                [BotPersonality.Aggressive] = new List<string> { "Rambo", "Berserker", "Fury", "Blitz", "Storm" },
                [BotPersonality.Defensive] = new List<string> { "Guardian", "Shield", "Fortress", "Anchor", "Wall" },
                [BotPersonality.Tactical] = new List<string> { "Strategist", "Mastermind", "Planner", "Tactician", "Chess" },
                [BotPersonality.Rusher] = new List<string> { "Flash", "Sonic", "Rush", "Speed", "Bolt" },
                [BotPersonality.Lurker] = new List<string> { "Shadow", "Ghost", "Phantom", "Stealth", "Ninja" },
                [BotPersonality.Support] = new List<string> { "Helper", "Backup", "Assist", "Support", "Medic" },
                [BotPersonality.AWPer] = new List<string> { "Sniper", "Eagle", "Hawk", "Scope", "Precision" }
            };
            
            var nameList = names[personality];
            return nameList[UnityEngine.Random.Range(0, nameList.Count)];
        }
        
        private void GenerateBotPatrolPoints(AIBot bot, Vector3 center)
        {
            // Generate patrol points in a radius around the spawn point
            for (int i = 0; i < 5; i++)
            {
                float angle = i * 72f * Mathf.Deg2Rad;
                float radius = UnityEngine.Random.Range(10f, 25f);
                
                Vector3 patrolPoint = center + new Vector3(
                    Mathf.Cos(angle) * radius,
                    0,
                    Mathf.Sin(angle) * radius
                );
                
                bot.PatrolPoints.Add(patrolPoint);
            }
        }
        
        private void StartBotBehavior(AIBot bot)
        {
            bot.BehaviorTimer = timer.Repeat(0.1f, 0, () => UpdateBotBehavior(bot));
        }
        
        private void UpdateBotBehavior(AIBot bot)
        {
            if (bot == null) return;
            
            // Find nearby players
            var nearbyPlayers = BasePlayer.activePlayerList.Where(p => 
                Vector3.Distance(p.transform.position, bot.Position) <= 50f &&
                !p.IsDead()).ToList();
            
            // Update bot state based on situation
            UpdateBotState(bot, nearbyPlayers);
            
            // Execute behavior based on current state
            ExecuteBotBehavior(bot, nearbyPlayers);
        }
        
        private void UpdateBotState(AIBot bot, List<BasePlayer> nearbyPlayers)
        {
            var enemies = nearbyPlayers.Where(p => GetPlayerData(p.userID).CurrentTeam != bot.Team).ToList();
            
            if (enemies.Count > 0)
            {
                bot.State = BotState.Engaging;
                bot.TargetPlayerId = enemies.OrderBy(e => Vector3.Distance(e.transform.position, bot.Position)).First().userID;
            }
            else if (bot.State == BotState.Engaging)
            {
                bot.State = BotState.Patrolling;
                bot.TargetPlayerId = 0;
            }
        }
        
        private void ExecuteBotBehavior(AIBot bot, List<BasePlayer> nearbyPlayers)
        {
            switch (bot.State)
            {
                case BotState.Patrolling:
                    ExecutePatrolBehavior(bot);
                    break;
                case BotState.Engaging:
                    ExecuteEngageBehavior(bot, nearbyPlayers);
                    break;
                case BotState.Planting:
                    ExecutePlantBehavior(bot);
                    break;
                case BotState.Defusing:
                    ExecuteDefuseBehavior(bot);
                    break;
            }
        }
        
        private void ExecutePatrolBehavior(AIBot bot)
        {
            if (bot.PatrolPoints.Count == 0) return;
            
            Vector3 targetPoint = bot.PatrolPoints[bot.CurrentPatrolIndex];
            float distance = Vector3.Distance(bot.Position, targetPoint);
            
            if (distance < 2f)
            {
                bot.CurrentPatrolIndex = (bot.CurrentPatrolIndex + 1) % bot.PatrolPoints.Count;
            }
            else
            {
                // Move towards patrol point
                Vector3 direction = (targetPoint - bot.Position).normalized;
                bot.Position += direction * GetBotMoveSpeed(bot) * 0.1f;
            }
        }
        
        private void ExecuteEngageBehavior(AIBot bot, List<BasePlayer> nearbyPlayers)
        {
            var target = BasePlayer.FindByID(bot.TargetPlayerId);
            if (target == null || target.IsDead()) return;
            
            float distance = Vector3.Distance(bot.Position, target.transform.position);
            
            // Aim at target
            Vector3 aimDirection = (target.transform.position - bot.Position).normalized;
            bot.Rotation = Quaternion.LookRotation(aimDirection).eulerAngles;
            
            // Shoot if in range and has line of sight
            if (distance <= GetBotEngageRange(bot) && HasLineOfSight(bot.Position, target.transform.position))
            {
                if (Time.time - bot.LastShotTime >= GetBotFireRate(bot))
                {
                    SimulateBotShot(bot, target);
                    bot.LastShotTime = Time.time;
                }
            }
            else
            {
                // Move closer to target
                Vector3 moveDirection = (target.transform.position - bot.Position).normalized;
                bot.Position += moveDirection * GetBotMoveSpeed(bot) * 0.1f;
            }
        }
        
        private float GetBotMoveSpeed(AIBot bot)
        {
            float baseSpeed = 5f;
            return baseSpeed * bot.Skills["Movement"];
        }
        
        private float GetBotEngageRange(AIBot bot)
        {
            switch (bot.Personality)
            {
                case BotPersonality.AWPer: return 50f;
                case BotPersonality.Rusher: return 15f;
                default: return 30f;
            }
        }
        
        private float GetBotFireRate(AIBot bot)
        {
            float baseRate = 0.15f; // Base fire rate
            return baseRate / bot.Skills["Aim"];
        }
        
        private bool HasLineOfSight(Vector3 from, Vector3 to)
        {
            // Simplified line of sight check
            return !Physics.Raycast(from, (to - from).normalized, Vector3.Distance(from, to));
        }
        
        private void SimulateBotShot(AIBot bot, BasePlayer target)
        {
            // Calculate hit chance based on bot accuracy and distance
            float distance = Vector3.Distance(bot.Position, target.transform.position);
            float hitChance = bot.Accuracy * (1f - (distance / 100f)); // Accuracy decreases with distance
            
            if (UnityEngine.Random.value <= hitChance)
            {
                // Hit the target
                float damage = GetWeaponDamage(bot.CurrentWeapon);
                
                // Apply damage to target
                target.Hurt(damage, DamageType.Bullet);
                
                // Update bot stats
                var botData = GetPlayerData(bot.TargetPlayerId); // Simulate bot as player for stats
                if (target.IsDead())
                {
                    // Bot got a kill
                    PrintToChat($"[BOT] {bot.Name} eliminated {target.displayName}");
                }
            }
        }
        
        private float GetWeaponDamage(string weaponName)
        {
            switch (weaponName)
            {
                case "rifle.ak": return 36f;
                case "rifle.lr300": return 40f;
                case "rifle.bolt": return 80f;
                case "smg.thompson": return 38f;
                default: return 30f;
            }
        }
        
