        public class WeaponSkin
        {
            public string SkinId { get; set; }
            public string Name { get; set; }
            public string WeaponType { get; set; }
            public SkinRarity Rarity { get; set; }
            public SkinWear Wear { get; set; }
            public string TexturePath { get; set; }
            public Color PrimaryColor { get; set; }
            public Color SecondaryColor { get; set; }
            public bool HasStatTrak { get; set; } = false;
            public int StatTrakKills { get; set; } = 0;
            public float MarketValue { get; set; }
            public DateTime UnlockDate { get; set; }
            public string Description { get; set; }
            public List<string> Tags { get; set; } = new List<string>();
            public bool IsLimited { get; set; } = false;
            public string Collection { get; set; }
        }
        
        public enum SkinRarity
        {
            Consumer_Grade = 1,    // White
            Industrial_Grade = 2,  // Light Blue
            Mil_Spec = 3,         // Blue
            Restricted = 4,        // Purple
            Classified = 5,        // Pink
            Covert = 6,           // Red
            Contraband = 7         // Gold
        }
        
        public enum SkinWear
        {
            Factory_New = 1,
            Minimal_Wear = 2,
            Field_Tested = 3,
            Well_Worn = 4,
            Battle_Scarred = 5
        }
        
