            public Dictionary<string, WeaponSkin> OwnedSkins { get; set; } = new Dictionary<string, WeaponSkin>();
            public Dictionary<string, string> EquippedSkins { get; set; } = new Dictionary<string, string>(); // WeaponType -> SkinId
            public int Currency { get; set; } = 1000; // In-game currency for buying skins
            public List<string> Wishlist { get; set; } = new List<string>();
            public Dictionary<string, DateTime> RecentDrops { get; set; } = new Dictionary<string, DateTime>();
        }
        
        private Dictionary<ulong, PlayerInventory> playerInventories = new Dictionary<ulong, PlayerInventory>();
        private Dictionary<string, WeaponSkin> availableSkins = new Dictionary<string, WeaponSkin>();
        
