        private void CreateSkin(string id, string name, string weaponType, SkinRarity rarity, string description, Color primary, Color secondary)
        {
            availableSkins[id] = new WeaponSkin
            {
                SkinId = id,
                Name = name,
                WeaponType = weaponType,
                Rarity = rarity,
                Wear = SkinWear.Factory_New,
                PrimaryColor = primary,
                SecondaryColor = secondary,
                Description = description,
                MarketValue = CalculateSkinValue(rarity),
                Collection = "CS2 Collection"
            };
        }
        
        private float CalculateSkinValue(SkinRarity rarity)
        {
            switch (rarity)
            {
                case SkinRarity.Consumer_Grade: return UnityEngine.Random.Range(10f, 50f);
                case SkinRarity.Industrial_Grade: return UnityEngine.Random.Range(50f, 150f);
                case SkinRarity.Mil_Spec: return UnityEngine.Random.Range(150f, 400f);
                case SkinRarity.Restricted: return UnityEngine.Random.Range(400f, 1000f);
                case SkinRarity.Classified: return UnityEngine.Random.Range(1000f, 3000f);
                case SkinRarity.Covert: return UnityEngine.Random.Range(3000f, 10000f);
                case SkinRarity.Contraband: return UnityEngine.Random.Range(10000f, 50000f);
                default: return 100f;
            }
        }
        
        private PlayerInventory GetPlayerInventory(ulong playerId)
        {
            if (!playerInventories.ContainsKey(playerId))
            {
                playerInventories[playerId] = new PlayerInventory { PlayerId = playerId };
            }
            return playerInventories[playerId];
        }
        
        private void CmdSkins(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_USE))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length == 0)
            {
                ShowSkinsMenu(player);
                return;
            }
            
            switch (args[0].ToLower())
            {
                case "equip":
                    if (args.Length >= 2) EquipSkin(player, args[1]);
                    break;
                case "unequip":
                    if (args.Length >= 2) UnequipSkin(player, args[1]);
                    break;
                case "buy":
                    if (args.Length >= 2) BuySkin(player, args[1]);
                    break;
                case "sell":
                    if (args.Length >= 2) SellSkin(player, args[1]);
                    break;
                case "inspect":
                    if (args.Length >= 2) InspectSkin(player, args[1]);
                    break;
                default:
                    ShowSkinsMenu(player);
                    break;
            }
        }
        
        private void ShowSkinsMenu(BasePlayer player)
        {
            var inventory = GetPlayerInventory(player.userID);
            
            SendReply(player, "=== WEAPON SKINS ===");
            SendReply(player, $"Currency: ${inventory.Currency}");
            SendReply(player, $"Owned Skins: {inventory.OwnedSkins.Count}");
            SendReply(player, "");
            SendReply(player, "Commands:");
            SendReply(player, "/skins equip <skinid> - Equip a skin");
            SendReply(player, "/skins unequip <weapontype> - Unequip skin");
            SendReply(player, "/skins buy <skinid> - Buy a skin");
            SendReply(player, "/skins sell <skinid> - Sell a skin");
            SendReply(player, "/skins inspect <skinid> - Inspect skin details");
            SendReply(player, "/skinshop - Browse available skins");
            SendReply(player, "/mykins - View your collection");
        }
        
        private void CmdSkinShop(BasePlayer player, string command, string[] args)
        {
            SendReply(player, "=== SKIN SHOP ===");
            
            var sortedSkins = availableSkins.Values.OrderBy(s => s.Rarity).ThenBy(s => s.MarketValue).ToList();
            
            foreach (var skin in sortedSkins.Take(10)) // Show first 10
            {
                string rarityColor = GetRarityColor(skin.Rarity);
                SendReply(player, $"{rarityColor}[{skin.Rarity}] {skin.Name} - ${skin.MarketValue:F0}");
                SendReply(player, $"  Use: /skins buy {skin.SkinId}");
            }
            
            SendReply(player, $"Showing 10 of {availableSkins.Count} available skins");
        }
        
        private void CmdMySkins(BasePlayer player, string command, string[] args)
        {
            var inventory = GetPlayerInventory(player.userID);
            
            SendReply(player, "=== MY SKINS ===");
            
            if (inventory.OwnedSkins.Count == 0)
            {
                SendReply(player, "You don't own any skins yet!");
                SendReply(player, "Use /skinshop to browse available skins");
                return;
            }
            
            foreach (var skin in inventory.OwnedSkins.Values)
            {
                string rarityColor = GetRarityColor(skin.Rarity);
                string equipped = inventory.EquippedSkins.ContainsValue(skin.SkinId) ? " [EQUIPPED]" : "";
                string statTrak = skin.HasStatTrak ? $" (StatTrak™: {skin.StatTrakKills} kills)" : "";
                
                SendReply(player, $"{rarityColor}{skin.Name}{equipped}{statTrak}");
                SendReply(player, $"  Wear: {skin.Wear} | Value: ${skin.MarketValue:F0}");
            }
        }
        
        private string GetRarityColor(SkinRarity rarity)
        {
            switch (rarity)
            {
                case SkinRarity.Consumer_Grade: return "<color=#B0C3D9>";
                case SkinRarity.Industrial_Grade: return "<color=#5E98D9>";
                case SkinRarity.Mil_Spec: return "<color=#4B69FF>";
                case SkinRarity.Restricted: return "<color=#8847FF>";
                case SkinRarity.Classified: return "<color=#D32CE6>";
                case SkinRarity.Covert: return "<color=#EB4B4B>";
                case SkinRarity.Contraband: return "<color=#E4AE39>";
                default: return "<color=white>";
            }
        }
        
        private void EquipSkin(BasePlayer player, string skinId)
        {
            var inventory = GetPlayerInventory(player.userID);
            
            if (!inventory.OwnedSkins.ContainsKey(skinId))
            {
                SendReply(player, "You don't own this skin!");
                return;
            }
            
            var skin = inventory.OwnedSkins[skinId];
            inventory.EquippedSkins[skin.WeaponType] = skinId;
            
            SendReply(player, $"Equipped {skin.Name}!");
            
            // Apply skin to current weapon if holding it
            ApplySkinToCurrentWeapon(player, skin);
        }
        
        private void UnequipSkin(BasePlayer player, string weaponType)
        {
            var inventory = GetPlayerInventory(player.userID);
            
            if (inventory.EquippedSkins.ContainsKey(weaponType))
            {
                inventory.EquippedSkins.Remove(weaponType);
                SendReply(player, $"Unequipped skin for {weaponType}");
            }
            else
            {
                SendReply(player, "No skin equipped for this weapon type!");
            }
        }
        
        private void BuySkin(BasePlayer player, string skinId)
        {
            var inventory = GetPlayerInventory(player.userID);
            
            if (!availableSkins.ContainsKey(skinId))
            {
                SendReply(player, "Skin not found!");
                return;
            }
            
            var skin = availableSkins[skinId];
            
            if (inventory.OwnedSkins.ContainsKey(skinId))
            {
                SendReply(player, "You already own this skin!");
                return;
            }
            
            if (inventory.Currency < skin.MarketValue)
            {
                SendReply(player, $"Insufficient funds! Need ${skin.MarketValue:F0}, you have ${inventory.Currency}");
                return;
            }
            
            // Create a copy with random wear
            var purchasedSkin = new WeaponSkin
            {
                SkinId = skin.SkinId,
                Name = skin.Name,
                WeaponType = skin.WeaponType,
                Rarity = skin.Rarity,
                Wear = (SkinWear)UnityEngine.Random.Range(1, 6),
                PrimaryColor = skin.PrimaryColor,
                SecondaryColor = skin.SecondaryColor,
                Description = skin.Description,
                MarketValue = skin.MarketValue,
                UnlockDate = DateTime.Now,
                HasStatTrak = UnityEngine.Random.value < 0.1f, // 10% chance for StatTrak
                Collection = skin.Collection
            };
            
            inventory.Currency -= (int)skin.MarketValue;
            inventory.OwnedSkins[skinId] = purchasedSkin;
            
            string statTrakText = purchasedSkin.HasStatTrak ? " with StatTrak™" : "";
            SendReply(player, $"Purchased {purchasedSkin.Name} ({purchasedSkin.Wear}){statTrakText}!");
        }
        
        private void SellSkin(BasePlayer player, string skinId)
        {
            var inventory = GetPlayerInventory(player.userID);
            
            if (!inventory.OwnedSkins.ContainsKey(skinId))
            {
                SendReply(player, "You don't own this skin!");
                return;
            }
            
            var skin = inventory.OwnedSkins[skinId];
            float sellPrice = skin.MarketValue * 0.7f; // 70% of market value
            
            inventory.Currency += (int)sellPrice;
            inventory.OwnedSkins.Remove(skinId);
            
            // Remove from equipped if it was equipped
            var equippedEntry = inventory.EquippedSkins.FirstOrDefault(e => e.Value == skinId);
            if (!equippedEntry.Equals(default(KeyValuePair<string, string>)))
            {
                inventory.EquippedSkins.Remove(equippedEntry.Key);
            }
            
            SendReply(player, $"Sold {skin.Name} for ${sellPrice:F0}!");
        }
        
        private void InspectSkin(BasePlayer player, string skinId)
        {
            WeaponSkin skin = null;
            
            // Check if player owns it
            var inventory = GetPlayerInventory(player.userID);
            if (inventory.OwnedSkins.ContainsKey(skinId))
            {
                skin = inventory.OwnedSkins[skinId];
            }
            else if (availableSkins.ContainsKey(skinId))
            {
                skin = availableSkins[skinId];
            }
            
            if (skin == null)
            {
                SendReply(player, "Skin not found!");
                return;
            }
            
            SendReply(player, $"=== {skin.Name} ===");
            SendReply(player, $"Rarity: {GetRarityColor(skin.Rarity)}{skin.Rarity}</color>");
            SendReply(player, $"Wear: {skin.Wear}");
            SendReply(player, $"Market Value: ${skin.MarketValue:F0}");
            SendReply(player, $"Collection: {skin.Collection}");
            if (skin.HasStatTrak) SendReply(player, $"StatTrak™ Kills: {skin.StatTrakKills}");
            SendReply(player, $"Description: {skin.Description}");
        }
        
