            if (container?.playerOwner == null) return;
            
            var player = container.playerOwner;
            var inventory = GetPlayerInventory(player.userID);
            
            // Check if player has a skin equipped for this weapon type
            if (inventory.EquippedSkins.ContainsKey(item.info.shortname))
            {
                string skinId = inventory.EquippedSkins[item.info.shortname];
                if (inventory.OwnedSkins.ContainsKey(skinId))
                {
                    var skin = inventory.OwnedSkins[skinId];
                    ApplySkinToItem(item, skin);
                }
            }
        }
        
