        // Daily skin drops
        private void CheckDailySkinDrop(BasePlayer player)
        {
            var inventory = GetPlayerInventory(player.userID);
            var today = DateTime.Now.Date;
            
            if (!inventory.RecentDrops.ContainsKey("daily") || 
                inventory.RecentDrops["daily"].Date < today)
            {
                // Give daily drop
                GiveRandomSkinDrop(player);
                inventory.RecentDrops["daily"] = DateTime.Now;
            }
        }
        
        private void GiveRandomSkinDrop(BasePlayer player)
        {
            var inventory = GetPlayerInventory(player.userID);
            
            // Random skin based on rarity weights
            var dropChances = new Dictionary<SkinRarity, float>
            {
                [SkinRarity.Consumer_Grade] = 0.7992f,
                [SkinRarity.Industrial_Grade] = 0.1598f,
                [SkinRarity.Mil_Spec] = 0.032f,
                [SkinRarity.Restricted] = 0.0064f,
                [SkinRarity.Classified] = 0.0013f,
                [SkinRarity.Covert] = 0.0003f,
                [SkinRarity.Contraband] = 0.00001f
            };
            
            SkinRarity droppedRarity = SelectRandomRarity(dropChances);
            var eligibleSkins = availableSkins.Values.Where(s => s.Rarity == droppedRarity).ToList();
            
            if (eligibleSkins.Count > 0)
            {
                var selectedSkin = eligibleSkins[UnityEngine.Random.Range(0, eligibleSkins.Count)];
                
                // Create dropped skin with random wear
                var droppedSkin = new WeaponSkin
                {
                    SkinId = selectedSkin.SkinId + "_drop_" + DateTime.Now.Ticks,
                    Name = selectedSkin.Name,
                    WeaponType = selectedSkin.WeaponType,
                    Rarity = selectedSkin.Rarity,
                    Wear = (SkinWear)UnityEngine.Random.Range(1, 6),
                    PrimaryColor = selectedSkin.PrimaryColor,
                    SecondaryColor = selectedSkin.SecondaryColor,
                    Description = selectedSkin.Description,
                    MarketValue = selectedSkin.MarketValue * GetWearMultiplier((SkinWear)UnityEngine.Random.Range(1, 6)),
                    UnlockDate = DateTime.Now,
                    HasStatTrak = UnityEngine.Random.value < 0.1f,
                    Collection = selectedSkin.Collection
                };
                
                inventory.OwnedSkins[droppedSkin.SkinId] = droppedSkin;
                
                string rarityColor = GetRarityColor(droppedSkin.Rarity);
                SendReply(player, $"🎁 SKIN DROP: {rarityColor}{droppedSkin.Name}</color> ({droppedSkin.Wear})!");
            }
        }
        
        private SkinRarity SelectRandomRarity(Dictionary<SkinRarity, float> chances)
        {
            float random = UnityEngine.Random.value;
            float cumulative = 0f;
            
            foreach (var kvp in chances)
            {
                cumulative += kvp.Value;
                if (random <= cumulative)
                {
                    return kvp.Key;
                }
            }
            
            return SkinRarity.Consumer_Grade;
        }
        
        private float GetWearMultiplier(SkinWear wear)
        {
            switch (wear)
            {
                case SkinWear.Factory_New: return 1.0f;
                case SkinWear.Minimal_Wear: return 0.9f;
                case SkinWear.Field_Tested: return 0.8f;
                case SkinWear.Well_Worn: return 0.6f;
                case SkinWear.Battle_Scarred: return 0.4f;
                default: return 0.8f;
            }
        }
        
