        private Dictionary<string, HeatMapData> mapHeatMaps = new Dictionary<string, HeatMapData>();
        private Dictionary<ulong, PlayerAnalytics> playerAnalytics = new Dictionary<ulong, PlayerAnalytics>();
        
        private void RecordKillPosition(BasePlayer killer, BasePlayer victim, Vector3 position, string mapName)
        {
            if (!mapHeatMaps.ContainsKey(mapName))
            {
                mapHeatMaps[mapName] = new HeatMapData { MapName = mapName };
            }
            
            var heatMap = mapHeatMaps[mapName];
            
            // Round position to grid for heat map
            Vector3 gridPos = RoundToGrid(position, 2f);
            
            if (!heatMap.KillPositions.ContainsKey(gridPos))
                heatMap.KillPositions[gridPos] = 0;
            if (!heatMap.DeathPositions.ContainsKey(gridPos))
                heatMap.DeathPositions[gridPos] = 0;
            
            heatMap.KillPositions[gridPos]++;
            heatMap.DeathPositions[gridPos]++;
            heatMap.LastUpdated = DateTime.Now;
            
            // Update player analytics
            var killerAnalytics = GetPlayerAnalytics(killer.userID);
            var victimAnalytics = GetPlayerAnalytics(victim.userID);
            
            // Record weapon used
            var activeItem = killer.GetActiveItem();
            if (activeItem != null)
            {
                string weaponName = activeItem.info.shortname;
                if (!killerAnalytics.WeaponKills.ContainsKey(weaponName))
                    killerAnalytics.WeaponKills[weaponName] = 0;
                killerAnalytics.WeaponKills[weaponName]++;
            }
        }
        
        private Vector3 RoundToGrid(Vector3 position, float gridSize)
        {
            return new Vector3(
                Mathf.Round(position.x / gridSize) * gridSize,
                Mathf.Round(position.y / gridSize) * gridSize,
                Mathf.Round(position.z / gridSize) * gridSize
            );
        }
        
        private PlayerAnalytics GetPlayerAnalytics(ulong playerId)
        {
            if (!playerAnalytics.ContainsKey(playerId))
            {
                playerAnalytics[playerId] = new PlayerAnalytics { PlayerId = playerId };
            }
            return playerAnalytics[playerId];
        }
        
        private void CmdHeatMap(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_USE))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length == 0)
            {
                SendReply(player, "Usage: /heatmap <mapname> [type]");
                SendReply(player, "Types: kills, deaths, plants, defuses");
                return;
            }
            
            string mapName = args[0];
            string type = args.Length > 1 ? args[1].ToLower() : "kills";
            
            if (!mapHeatMaps.ContainsKey(mapName))
            {
                SendReply(player, $"No heat map data available for {mapName}");
                return;
            }
            
            ShowHeatMap(player, mapName, type);
        }
        
        private void ShowHeatMap(BasePlayer player, string mapName, string type)
        {
            var heatMap = mapHeatMaps[mapName];
            Dictionary<Vector3, int> data;
            
            switch (type)
            {
                case "kills":
                    data = heatMap.KillPositions;
                    break;
                case "deaths":
                    data = heatMap.DeathPositions;
                    break;
                case "plants":
                    data = heatMap.BombPlantPositions;
                    break;
                case "defuses":
                    data = heatMap.BombDefusePositions;
                    break;
                default:
                    data = heatMap.KillPositions;
                    break;
            }
            
            SendReply(player, $"=== HEAT MAP: {mapName.ToUpper()} ({type.ToUpper()}) ===");
            
            var sortedData = data.OrderByDescending(kvp => kvp.Value).Take(10);
            
            foreach (var entry in sortedData)
            {
                Vector3 pos = entry.Key;
                int count = entry.Value;
                string intensity = GetHeatIntensity(count, data.Values.Max());
                
                SendReply(player, $"{intensity} {pos.x:F0}, {pos.y:F0}, {pos.z:F0} - {count} events");
            }
            
            SendReply(player, $"Total data points: {data.Count}");
            SendReply(player, $"Last updated: {heatMap.LastUpdated:yyyy-MM-dd HH:mm}");
        }
        
        private string GetHeatIntensity(int count, int maxCount)
        {
            float intensity = (float)count / maxCount;
            
            if (intensity >= 0.8f) return "🔥🔥🔥"; // Very hot
            if (intensity >= 0.6f) return "🔥🔥";   // Hot
            if (intensity >= 0.4f) return "🔥";     // Warm
            if (intensity >= 0.2f) return "🟡";     // Cool
            return "🔵"; // Cold
        }
        
        private void CmdPlayerStats(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_USE))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            ulong targetId = player.userID;
            if (args.Length > 0)
            {
                var targetPlayer = BasePlayer.Find(args[0]);
                if (targetPlayer != null)
                {
                    targetId = targetPlayer.userID;
                }
            }
            
            ShowAdvancedStats(player, targetId);
        }
        
        private void ShowAdvancedStats(BasePlayer viewer, ulong targetId)
        {
            var analytics = GetPlayerAnalytics(targetId);
            var playerData = GetPlayerData(targetId);
            var ranking = GetPlayerRanking(targetId);
            
            var targetPlayer = BasePlayer.FindByID(targetId);
            string targetName = targetPlayer?.displayName ?? "Unknown Player";
            
            SendReply(viewer, $"=== ADVANCED STATS: {targetName} ===");
            
            // Basic stats
            float kd = playerData.Deaths > 0 ? (float)playerData.Kills / playerData.Deaths : playerData.Kills;
            float hs = playerData.ShotsFired > 0 ? (float)playerData.HeadShots / playerData.ShotsFired * 100f : 0f;
            
            SendReply(viewer, $"Rank: {ranking.CurrentRank} ({ranking.ELO} ELO)");
            SendReply(viewer, $"K/D: {kd:F2} ({playerData.Kills}K/{playerData.Deaths}D)");
            SendReply(viewer, $"Headshot %: {hs:F1}%");
            SendReply(viewer, $"Accuracy: {playerData.Accuracy:F1}%");
            
            // Weapon stats
            SendReply(viewer, "\n--- WEAPON PERFORMANCE ---");
            var topWeapons = analytics.WeaponKills.OrderByDescending(kvp => kvp.Value).Take(3);
            foreach (var weapon in topWeapons)
            {
                float acc = analytics.WeaponAccuracy.ContainsKey(weapon.Key) ? analytics.WeaponAccuracy[weapon.Key] : 0f;
                SendReply(viewer, $"{weapon.Key}: {weapon.Value} kills ({acc:F1}% acc)");
            }
            
            // Clutch stats
            SendReply(viewer, "\n--- CLUTCH PERFORMANCE ---");
            var clutches = analytics.ClutchHistory;
            int clutchWins = clutches.Count(c => c.Won);
            float clutchWinRate = clutches.Count > 0 ? (float)clutchWins / clutches.Count * 100f : 0f;
            
            SendReply(viewer, $"Clutch Win Rate: {clutchWinRate:F1}% ({clutchWins}/{clutches.Count})");
            
            var clutchBreakdown = clutches.GroupBy(c => c.EnemiesAlive)
                .ToDictionary(g => g.Key, g => new { Total = g.Count(), Won = g.Count(c => c.Won) });
            
            foreach (var clutch in clutchBreakdown.OrderBy(kvp => kvp.Key))
            {
                float winRate = clutch.Value.Total > 0 ? (float)clutch.Value.Won / clutch.Value.Total * 100f : 0f;
                SendReply(viewer, $"1v{clutch.Key}: {winRate:F1}% ({clutch.Value.Won}/{clutch.Value.Total})");
            }
            
            // Economy stats
            SendReply(viewer, "\n--- ECONOMY ---");
            SendReply(viewer, $"Money Earned: ${analytics.Economy.TotalMoneyEarned:N0}");
            SendReply(viewer, $"Avg Per Round: ${analytics.Economy.AverageMoneyPerRound:F0}");
            SendReply(viewer, $"Eco Rounds: {analytics.Economy.EcoRoundsPlayed}");
            SendReply(viewer, $"Full Buys: {analytics.Economy.FullBuyRounds}");
            
            // Utility stats
            SendReply(viewer, "\n--- UTILITY USAGE ---");
            SendReply(viewer, $"Enemies Flashed: {analytics.Utility.EnemiesFlashed}");
            SendReply(viewer, $"Teammates Flashed: {analytics.Utility.TeammatesFlashed}");
            SendReply(viewer, $"Utility Kills: {analytics.Utility.UtilityKills}");
            
            // Movement stats
            SendReply(viewer, "\n--- MOVEMENT ---");
            SendReply(viewer, $"Distance Moved: {analytics.Movement.TotalDistanceMoved:F0}m");
            SendReply(viewer, $"Average Speed: {analytics.Movement.AverageSpeed:F1} m/s");
            SendReply(viewer, $"Jumps: {analytics.Movement.JumpCount}");
        }
        
        #endregion
        
        #region Tournament System
        
        public class Tournament
        {
            public ulong TournamentId { get; set; }
            public string Name { get; set; }
            public TournamentFormat Format { get; set; }
            public TournamentStatus Status { get; set; }
            public DateTime StartDate { get; set; }
            public DateTime EndDate { get; set; }
            public int MaxTeams { get; set; }
            public List<TournamentTeam> RegisteredTeams { get; set; } = new List<TournamentTeam>();
            public List<TournamentMatch> Matches { get; set; } = new List<TournamentMatch>();
            public Dictionary<string, object> Prizes { get; set; } = new Dictionary<string, object>();
            public List<string> MapPool { get; set; } = new List<string>();
            public TournamentRules Rules { get; set; } = new TournamentRules();
            public ulong OrganizerId { get; set; }
        }
        
        public enum TournamentFormat
        {
            SingleElimination, DoubleElimination, RoundRobin, Swiss, Ladder
        }
        
        public enum TournamentStatus
        {
            Registration, InProgress, Completed, Cancelled
        }
        
        public class TournamentTeam
        {
            public string TeamId { get; set; }
            public string Name { get; set; }
            public List<ulong> PlayerIds { get; set; } = new List<ulong>();
            public ulong CaptainId { get; set; }
            public int Wins { get; set; } = 0;
            public int Losses { get; set; } = 0;
            public int RoundWins { get; set; } = 0;
            public int RoundLosses { get; set; } = 0;
            public bool IsEliminated { get; set; } = false;
        }
        
        public class TournamentMatch
        {
            public string MatchId { get; set; }
            public string Team1Id { get; set; }
            public string Team2Id { get; set; }
            public string MapName { get; set; }
            public int Team1Score { get; set; } = 0;
            public int Team2Score { get; set; } = 0;
            public MatchStatus Status { get; set; } = MatchStatus.Scheduled;
            public DateTime ScheduledTime { get; set; }
            public string WinnerId { get; set; }
            public int Round { get; set; }
            public bool IsGrandFinal { get; set; } = false;
        }
        
        public enum MatchStatus
        {
            Scheduled, InProgress, Completed, Postponed, Cancelled
        }
        
        public class TournamentRules
        {
            public int TeamSize { get; set; } = 5;
            public int RoundsToWin { get; set; } = 16;
            public bool AllowSubstitutes { get; set; } = true;
            public int MaxSubstitutes { get; set; } = 2;
            public TimeSpan MatchTimeout { get; set; } = TimeSpan.FromHours(2);
            public bool RequireAllPlayersOnline { get; set; } = true;
        }
        
        private Dictionary<ulong, Tournament> activeTournaments = new Dictionary<ulong, Tournament>();
        
        private void CmdCreateTournament(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_ADMIN))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length < 3)
            {
                SendReply(player, "Usage: /createtournament <name> <format> <maxteams>");
                SendReply(player, "Formats: single, double, roundrobin, swiss");
                return;
            }
            
            string name = args[0];
            if (!Enum.TryParse<TournamentFormat>(args[1], true, out TournamentFormat format))
            {
                SendReply(player, "Invalid format! Use: single, double, roundrobin, swiss");
                return;
            }
            
            if (!int.TryParse(args[2], out int maxTeams) || maxTeams < 2 || maxTeams > 64)
            {
                SendReply(player, "Max teams must be between 2 and 64!");
                return;
            }
            
            ulong tournamentId = (ulong)UnityEngine.Random.Range(100000, 999999);
            
            var tournament = new Tournament
            {
                TournamentId = tournamentId,
                Name = name,
                Format = format,
                Status = TournamentStatus.Registration,
                MaxTeams = maxTeams,
                OrganizerId = player.userID,
                StartDate = DateTime.Now.AddHours(1), // Default start in 1 hour
                MapPool = new List<string> { "dust2", "mirage", "inferno", "cache", "train" }
            };
            
            activeTournaments[tournamentId] = tournament;
            
            SendReply(player, $"Tournament '{name}' created! ID: {tournamentId}");
            SendReply(player, $"Format: {format} | Max Teams: {maxTeams}");
            SendReply(player, "Teams can now register with /jointeam <tournamentid> <teamname>");
        }
        
        private void CmdJoinTournament(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_USE))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length < 2)
            {
                SendReply(player, "Usage: /jointeam <tournamentid> <teamname>");
                return;
            }
            
            if (!ulong.TryParse(args[0], out ulong tournamentId))
            {
                SendReply(player, "Invalid tournament ID!");
                return;
            }
            
            if (!activeTournaments.ContainsKey(tournamentId))
            {
                SendReply(player, "Tournament not found!");
                return;
            }
            
            var tournament = activeTournaments[tournamentId];
            
            if (tournament.Status != TournamentStatus.Registration)
            {
                SendReply(player, "Tournament registration is closed!");
                return;
            }
            
            string teamName = args[1];
            
            // Check if team name already exists
            if (tournament.RegisteredTeams.Any(t => t.Name.Equals(teamName, StringComparison.OrdinalIgnoreCase)))
            {
                SendReply(player, "Team name already taken!");
                return;
            }
            
            // Check if player is already in a team
            if (tournament.RegisteredTeams.Any(t => t.PlayerIds.Contains(player.userID)))
            {
                SendReply(player, "You are already registered in this tournament!");
                return;
            }
            
            if (tournament.RegisteredTeams.Count >= tournament.MaxTeams)
            {
                SendReply(player, "Tournament is full!");
                return;
            }
            
            var team = new TournamentTeam
            {
                TeamId = Guid.NewGuid().ToString(),
                Name = teamName,
                CaptainId = player.userID
            };
            team.PlayerIds.Add(player.userID);
            
            tournament.RegisteredTeams.Add(team);
            
            SendReply(player, $"Team '{teamName}' registered for tournament '{tournament.Name}'!");
            SendReply(player, $"You are the team captain. Use /inviteplayer <playername> to invite teammates.");
            
            // Announce to all players
            PrintToChat($"Team '{teamName}' joined tournament '{tournament.Name}' ({tournament.RegisteredTeams.Count}/{tournament.MaxTeams})");
        }
        
        private void CmdStartTournament(BasePlayer player, string command, string[] args)
        {
            if (!permission.UserHasPermission(player.UserIDString, PERMISSION_ADMIN))
            {
                SendReply(player, "You don't have permission to use this command!");
                return;
            }
            
            if (args.Length == 0)
            {
                SendReply(player, "Usage: /starttournament <tournamentid>");
                return;
            }
            
            if (!ulong.TryParse(args[0], out ulong tournamentId))
            {
                SendReply(player, "Invalid tournament ID!");
                return;
            }
            
            if (!activeTournaments.ContainsKey(tournamentId))
            {
                SendReply(player, "Tournament not found!");
                return;
            }
            
            var tournament = activeTournaments[tournamentId];
            
            if (tournament.OrganizerId != player.userID)
            {
                SendReply(player, "Only the tournament organizer can start the tournament!");
                return;
            }
            
            if (tournament.RegisteredTeams.Count < 2)
            {
                SendReply(player, "Need at least 2 teams to start tournament!");
                return;
            }
            
            StartTournament(tournament);
            SendReply(player, $"Tournament '{tournament.Name}' started!");
        }
        
        private void StartTournament(Tournament tournament)
        {
            tournament.Status = TournamentStatus.InProgress;
            tournament.StartDate = DateTime.Now;
            
            // Generate bracket based on format
            switch (tournament.Format)
            {
                case TournamentFormat.SingleElimination:
                    GenerateSingleEliminationBracket(tournament);
                    break;
                case TournamentFormat.DoubleElimination:
                    GenerateDoubleEliminationBracket(tournament);
                    break;
                case TournamentFormat.RoundRobin:
                    GenerateRoundRobinMatches(tournament);
                    break;
                case TournamentFormat.Swiss:
                    GenerateSwissRound(tournament, 1);
                    break;
            }
            
            // Announce tournament start
            PrintToChat($"🏆 Tournament '{tournament.Name}' has started!");
            PrintToChat($"Format: {tournament.Format} | Teams: {tournament.RegisteredTeams.Count}");
            
            // Schedule first matches
            ScheduleNextMatches(tournament);
        }
        
        private void GenerateSingleEliminationBracket(Tournament tournament)
        {
            var teams = tournament.RegisteredTeams.ToList();
            
            // Shuffle teams for random seeding
            for (int i = 0; i < teams.Count; i++)
            {
                var temp = teams[i];
                int randomIndex = UnityEngine.Random.Range(i, teams.Count);
                teams[i] = teams[randomIndex];
                teams[randomIndex] = temp;
            }
            
            int round = 1;
            
            // Create first round matches
            for (int i = 0; i < teams.Count; i += 2)
            {
                if (i + 1 < teams.Count)
                {
                    var match = new TournamentMatch
                    {
                        MatchId = Guid.NewGuid().ToString(),
                        Team1Id = teams[i].TeamId,
                        Team2Id = teams[i + 1].TeamId,
                        Round = round,
                        ScheduledTime = DateTime.Now.AddMinutes(round * 30),
                        MapName = tournament.MapPool[UnityEngine.Random.Range(0, tournament.MapPool.Count)]
                    };
                    
                    tournament.Matches.Add(match);
                }
            }
        }
        
        private void ScheduleNextMatches(Tournament tournament)
        {
            var nextMatches = tournament.Matches
                .Where(m => m.Status == MatchStatus.Scheduled)
                .OrderBy(m => m.Round)
                .ThenBy(m => m.ScheduledTime)
                .Take(2); // Schedule up to 2 matches at once
            
            foreach (var match in nextMatches)
            {
                ScheduleMatch(tournament, match);
            }
        }
        
        private void ScheduleMatch(Tournament tournament, TournamentMatch match)
        {
            var team1 = tournament.RegisteredTeams.First(t => t.TeamId == match.Team1Id);
            var team2 = tournament.RegisteredTeams.First(t => t.TeamId == match.Team2Id);
            
            PrintToChat($"🎮 Tournament Match: {team1.Name} vs {team2.Name}");
            PrintToChat($"Map: {match.MapName} | Round: {match.Round}");
            
            // Notify team members
            NotifyTeamMembers(team1, $"Your tournament match vs {team2.Name} is starting!");
            NotifyTeamMembers(team2, $"Your tournament match vs {team1.Name} is starting!");
            
            // Create match queue zone
            CreateTournamentMatchQueue(tournament, match);
        }
        
        private void NotifyTeamMembers(TournamentTeam team, string message)
        {
            foreach (var playerId in team.PlayerIds)
            {
                var player = BasePlayer.FindByID(playerId);
                if (player != null)
                {
                    SendReply(player, $"🏆 TOURNAMENT: {message}");
                }
            }
        }
        
        private void CreateTournamentMatchQueue(Tournament tournament, TournamentMatch match)
        {
            // Create a special queue zone for tournament matches
            string queueName = $"tournament_{match.MatchId}";
            
            var queueZone = new QueueZone
            {
                Name = queueName,
                MinBounds = new Vector3(-5, 0, -5),
                MaxBounds = new Vector3(5, 5, 5),
                TeamSize = tournament.Rules.TeamSize,
                IsActive = true,
                SelectedMap = match.MapName
            };
            
            queueZones[queueName] = queueZone;
            
            // Set match to in progress when queue fills
            timer.Once(60f, () => CheckTournamentMatchStart(tournament, match));
        }
        
        private void CheckTournamentMatchStart(Tournament tournament, TournamentMatch match)
        {
            // Implementation for starting tournament matches
            match.Status = MatchStatus.InProgress;
            
            PrintToChat($"🏆 Tournament match started: {match.Team1Id} vs {match.Team2Id}");
        }
        
        #endregion
        
        #endregion
    }
